# User class for Flask-Login
class User(UserMixin):
    def __init__(self, user_data):
        self.id = user_data['id']
        self.username = user_data['username']
        self.email = user_data['email']
        self.full_name = user_data['full_name']
        self.role = user_data['role']
        self.campus = user_data['campus']
        self.active = user_data['active']
        self.password_hash = user_data['password_hash']
        self.custom_permissions = user_data.get('custom_permissions') or {}
        self.region_id = user_data.get('region_id')
        
    def is_authenticated(self):
        return True
        
    def is_active(self):
        return self.active
        
    def is_anonymous(self):
        return False
        
    def get_id(self):
        return str(self.id)
        
    def check_password(self, password):
        """Check if the provided password is correct"""
        from werkzeug.security import check_password_hash
        try:
            # Try standard werkzeug password check
            return check_password_hash(self.password_hash, password)
        except (ValueError, AttributeError):
            # If scrypt hash fails (not available), try bcrypt as fallback
            try:
                import bcrypt
                # Check if it's a bcrypt hash
                if self.password_hash.startswith('$2b$') or self.password_hash.startswith('$2a$'):
                    return bcrypt.checkpw(password.encode('utf-8'), self.password_hash.encode('utf-8'))
            except:
                pass
            # If all else fails, check for plain text match (for development only)
            if self.password_hash == password:
                return True
            return False
        
    def has_permission(self, permission_type, action=None, campus=None):
        """Check if user has specific permission based on role and custom_permissions
        
        Supports both old-style (e.g., 'log_stats') and new RBAC-style (e.g., 'groups', 'view') permissions
        
        Custom permissions (from Role Manager) can override role defaults:
        - 'input: true' grants log_stats and recall_stats
        - 'dashboard: true' grants dashboard_access and recall_stats
        - 'finance: true' grants finance_access
        """
        # If action is provided, use RBAC system
        if action is not None:
            try:
                from utils.rbac import rbac_manager
                custom_perms = getattr(self, 'custom_permissions', {}) or {}
                return rbac_manager.has_permission(self.role, permission_type, action, custom_permissions=custom_perms)
            except Exception as e:
                logger.error(f"Error checking RBAC permission: {e}")
                # Fall back to old system if RBAC fails
        
        # FIRST: Check custom_permissions (set via Role Manager)
        custom_perms = getattr(self, 'custom_permissions', {}) or {}
        
        # Map feature flags to backend permissions
        if permission_type == 'log_stats':
            # If user has 'input: true' in custom_permissions, grant log_stats
            if custom_perms.get('input') is True:
                logger.info(f"[PERMISSION_CHECK] User granted log_stats via custom_permissions.input=True")
                return True
            # Explicitly denied
            if custom_perms.get('input') is False:
                logger.info(f"[PERMISSION_CHECK] User denied log_stats via custom_permissions.input=False")
                return False
        
        if permission_type == 'recall_stats':
            # If user has 'input: true' or 'dashboard: true', grant recall_stats (needed to view data)
            if custom_perms.get('input') is True or custom_perms.get('dashboard') is True:
                logger.info(f"[PERMISSION_CHECK] User granted recall_stats via custom_permissions (input={custom_perms.get('input')}, dashboard={custom_perms.get('dashboard')})")
                return True
            # Explicitly denied
            if custom_perms.get('input') is False and custom_perms.get('dashboard') is False:
                return False
        
        if permission_type == 'dashboard_access':
            # If user has 'dashboard: true', grant dashboard_access
            if custom_perms.get('dashboard') is True:
                return True
            if custom_perms.get('dashboard') is False:
                return False
        
        if permission_type == 'finance_access':
            # If user has 'finance: true', grant finance_access
            if custom_perms.get('finance') is True:
                return True
            if custom_perms.get('finance') is False:
                return False
        
        # Define permissions for each role (legacy system)
        role_permissions = {
            'superadmin': {
                'log_stats': True,
                'recall_stats': True,
                'dashboard_access': True,
                'query_access': True,
                'edit_access': True,
                'finance_access': True,
                'manage_users': True,
                'manage_campuses': True,
                'view_all_campuses': True
            },
            'admin': {
                'log_stats': True,
                'recall_stats': True,
                'dashboard_access': True,
                'query_access': True,
                'edit_access': True,
                'finance_access': True,
                'manage_users': True,
                'manage_campuses': True,
                'view_all_campuses': True
            },
            'senior_leadership': {
                'log_stats': True,
                'recall_stats': True,
                'dashboard_access': True,
                'query_access': True,
                'edit_access': True,
                'finance_access': True,
                'manage_users': True,
                'manage_campuses': True,
                'view_all_campuses': True
            },
            'senior_leader': {
                'log_stats': True,
                'recall_stats': True,
                'dashboard_access': True,
                'query_access': True,
                'edit_access': True,
                'finance_access': True,
                'manage_users': True,
                'manage_campuses': True,
                'view_all_campuses': True
            },
            'senior_pastor': {
                'log_stats': True,
                'recall_stats': True,
                'dashboard_access': True,
                'query_access': True,
                'edit_access': True,
                'finance_access': True,
                'manage_users': True,
                'manage_campuses': True,
                'view_all_campuses': True
            },
            'lead_pastor': {
                'log_stats': True,
                'recall_stats': True,
                'dashboard_access': True,
                'query_access': True,
                'edit_access': True,
                'finance_access': True,
                'manage_users': True,
                'manage_campuses': True,
                'view_all_campuses': True
            },
            'finance': {
                'log_stats': False,
                'recall_stats': False,  # Cannot view dashboards
                'dashboard_access': False,  # No dashboard access
                'query_access': False,
                'finance_access': True,  # Can ONLY submit finance data
                'manage_users': False,
                'manage_campuses': False,
                'view_all_campuses': False
            },
            'campus_pastor': {
                'log_stats': True,  # Can log stats for their campus
                'recall_stats': 'own_campus',  # Can only see their own campus
                'dashboard_access': 'own_campus',
                'query_access': True,
                'edit_access': True,
                'finance_access': False,
                'manage_users': False,
                'manage_campuses': False,
                'view_all_campuses': False
            },
            'pastor': {
                'log_stats': True,  # Can log stats
                'recall_stats': 'own_campus',
                'dashboard_access': 'own_campus',
                'query_access': True,
                'edit_access': True,
                'finance_access': False,
                'manage_users': False,
                'manage_campuses': False,
                'view_all_campuses': False
            }
        }
        
        perms = role_permissions.get(self.role, {})
        perm_value = perms.get(permission_type, False)
        
        # Log permission check for debugging
        if permission_type == 'log_stats':
            logger.info(f"[PERMISSION_CHECK] User role: '{self.role}', permission_type: '{permission_type}', perm_value: {perm_value}, campus: {campus}, user_campus: {getattr(self, 'campus', None)}")
        
        # Handle campus-specific permissions
        if permission_type == 'log_stats':
            if perm_value is True:
                return True
            elif perm_value == 'own_campus':
                # For own_campus, allow if no campus specified or if it matches user's campus
                user_campus = getattr(self, 'campus', None)
                result = campus is None or campus == user_campus or user_campus == 'all_campuses'
                logger.info(f"[PERMISSION_CHECK] own_campus check: campus={campus}, user_campus={user_campus}, result={result}")
                return result
            # If role not found in permissions, default to False but log it
            if self.role not in role_permissions:
                logger.warning(f"[PERMISSION_CHECK] Role '{self.role}' not found in role_permissions. Available roles: {list(role_permissions.keys())}")
            return False
            
        elif permission_type == 'recall_stats':
            # Check role-based permissions (custom_permissions already checked above)
            if perm_value is True:
                return True
            elif perm_value == 'own_campus':
                return campus is None or campus == self.campus or self.campus == 'all_campuses'
            return False
            
        elif permission_type == 'dashboard_access':
            if perm_value is True:
                return True
            elif perm_value == 'own_campus':
                return campus is None or campus == self.campus or self.campus == 'all_campuses'
            return perm_value
            
        elif permission_type == 'query_access':
            return perm_value is True
            
        # For all other permissions, just return the boolean value
        else:
            return perm_value is True
        
    def get_accessible_campuses(self):
        """Get list of campuses this user can access for data recall"""
        if self.has_permission('recall_stats'):
            if self.campus == 'all_campuses':
                return ['all_campuses', 'paradise', 'adelaide_city', 'salisbury', 'south', 'mount_barker']
            else:
                return [self.campus]
        return []

@login_manager.user_loader
def load_user(user_id):
    """Load user by ID for Flask-Login"""
    try:
        conn = get_db()
        cursor = conn.cursor()
        
        # Try to select with custom_permissions and region_id, fallback if columns don't exist
        try:
            cursor.execute('''
                SELECT id, username, password_hash, full_name, email, role, campus, active, custom_permissions, region_id
                FROM users
                WHERE id = ? AND active = 1
            ''', (user_id,))
        except Exception:
            try:
                # Try with custom_permissions but without region_id
                cursor.execute('''
                    SELECT id, username, password_hash, full_name, email, role, campus, active, custom_permissions
                    FROM users
                    WHERE id = ? AND active = 1
                ''', (user_id,))
            except Exception:
                # Fallback if custom_permissions column doesn't exist yet
                cursor.execute('''
                    SELECT id, username, password_hash, full_name, email, role, campus, active
                    FROM users
                    WHERE id = ? AND active = 1
                ''', (user_id,))
        
        row = cursor.fetchone()
        conn.close()
        
        if row:
            import json
            custom_permissions = {}
            region_id = None
            
            if len(row) > 8:
                try:
                    custom_perms = row[8]
                    if custom_perms:
                        custom_permissions = json.loads(custom_perms) if isinstance(custom_perms, str) else custom_perms
                except:
                    custom_permissions = {}
            
            # Get region_id if available (column 9)
            if len(row) > 9:
                region_id = row[9]
            
            user_data = {
                'id': str(row[0]),  # Flask-Login expects string ID
                'username': row[1],
                'password_hash': row[2],
                'full_name': row[3] or row[1],
                'email': row[4] or '',
                'role': row[5],
                'campus': row[6] or '',
                'active': bool(row[7]),
                'custom_permissions': custom_permissions,
                'region_id': region_id
            }
            return User(user_data)
        return None
    except Exception as e:
        logger.error(f"Error loading user {user_id}: {e}", exc_info=True)
        return None

def authenticate_user(username_or_email, password):
    """Authenticate user and return User object if valid
    Accepts either username or email for login (case-insensitive)
    """
    try:
        logger.info(f"[AUTH] 🔐 Attempting authentication for: '{username_or_email}'")
        conn = get_db()
        cursor = conn.cursor()
        
        # Normalize input (trim and lowercase for case-insensitive matching)
        normalized_input = username_or_email.strip().lower()
        
        # Check both username and email fields (case-insensitive)
        # SQLite: Use LOWER() on both sides for reliable case-insensitive comparison
        # Try to include custom_permissions and region_id if columns exist
        try:
            cursor.execute('''
                SELECT id, username, password_hash, full_name, email, role, campus, active, custom_permissions, region_id
                FROM users
                WHERE (LOWER(TRIM(username)) = LOWER(?) OR LOWER(TRIM(email)) = LOWER(?)) AND active = 1
            ''', (username_or_email.strip(), username_or_email.strip()))
        except Exception as col_error:
            # Check if error is due to missing column
            error_msg = str(col_error).lower()
            if 'no such column' in error_msg:
                try:
                    # Try with custom_permissions but without region_id
                    cursor.execute('''
                        SELECT id, username, password_hash, full_name, email, role, campus, active, custom_permissions
                        FROM users
                        WHERE (LOWER(TRIM(username)) = LOWER(?) OR LOWER(TRIM(email)) = LOWER(?)) AND active = 1
                    ''', (username_or_email.strip(), username_or_email.strip()))
                except Exception:
                    # Fallback if custom_permissions column doesn't exist yet
                    cursor.execute('''
                        SELECT id, username, password_hash, full_name, email, role, campus, active
                        FROM users
                        WHERE (LOWER(TRIM(username)) = LOWER(?) OR LOWER(TRIM(email)) = LOWER(?)) AND active = 1
                    ''', (username_or_email.strip(), username_or_email.strip()))
            else:
                # Re-raise if it's a different error
                logger.error(f"Database error in authenticate_user: {col_error}")
                raise
        
        row = cursor.fetchone()
        
        if row:
            logger.info(f"[AUTH] ✅ User FOUND in database:")
            logger.info(f"      - ID: {row[0]}")
            logger.info(f"      - Username: '{row[1]}'")
            logger.info(f"      - Email: '{row[4]}'")
            logger.info(f"      - Role: {row[5]}")
            logger.info(f"      - Active: {bool(row[7])}")
            
            # Handle custom_permissions if column exists
            import json
            custom_permissions = {}
            region_id = None
            if len(row) > 8:
                try:
                    custom_perms = row[8]
                    if custom_perms:
                        custom_permissions = json.loads(custom_perms) if isinstance(custom_perms, str) else custom_perms
                except:
                    custom_permissions = {}
            
            # Get region_id if available (column 9)
            if len(row) > 9:
                region_id = row[9]
            
            user_data = {
                'id': str(row[0]),
                'username': row[1],
                'password_hash': row[2],
                'full_name': row[3] or row[1],
                'email': row[4] or '',
                'role': row[5],
                'campus': row[6] or '',
                'active': bool(row[7]),
                'custom_permissions': custom_permissions,
                'region_id': region_id
            }
            
            user = User(user_data)
            password_valid = user.check_password(password)
            
            logger.info(f"[AUTH] 🔑 Password check result: {password_valid}")
            if password_valid:
                # Update last login with ISO8601 format for SQLite compatibility
                now = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
                logger.info(f"[AUTH] 📝 Updating last_login to: {now} for user ID: {row[0]}")
                cursor.execute('UPDATE users SET last_login = ? WHERE id = ?', 
                             (now, row[0]))
                conn.commit()
                logger.info(f"[AUTH] ✅ last_login updated successfully")
                conn.close()
                logger.info(f"[AUTH] ✅ Authentication SUCCESS for '{username_or_email}'")
                return user
            else:
                logger.warning(f"[AUTH] ❌ Password INVALID for '{username_or_email}'")
        else:
            logger.warning(f"[AUTH] ❌ User NOT FOUND: '{username_or_email}' (normalized: '{normalized_input}')")
            # Try to find similar users for debugging
            cursor.execute('''
                SELECT username, email, active
                FROM users
                WHERE LOWER(email) LIKE ? OR LOWER(username) LIKE ?
                LIMIT 5
            ''', (f'%{normalized_input}%', f'%{normalized_input}%'))
            similar = cursor.fetchall()
            if similar:
                logger.warning(f"[AUTH] Found similar users: {similar}")
        
        conn.close()
        return None
    except Exception as e:
        logger.error(f"[AUTH] ❌ Authentication ERROR for '{username_or_email}': {e}", exc_info=True)
        return None

