@app.route('/api/debug/connect-attendance/<person_id>', methods=['GET'])
@login_required
def debug_connect_attendance(person_id):
    """Debug endpoint to check ConnectAttendance records for a person"""
    try:
        from models import ConnectAttendance, HeartbeatConnectGroup, Person
        from datetime import date, timedelta
        
        person = Person.query.filter_by(id=person_id, is_active=True).first()
        if not person:
            return jsonify({'error': 'Person not found'}), 404
        
        # Get all ConnectAttendance records
        all_records = ConnectAttendance.query.filter_by(person_id=person_id).order_by(ConnectAttendance.date.desc()).all()
        
        # Get records in last 12 weeks
        end_date = date.today()
        start_date = end_date - timedelta(weeks=12)
        recent_records = ConnectAttendance.query.filter(
            ConnectAttendance.person_id == person_id,
            ConnectAttendance.date >= start_date,
            ConnectAttendance.date <= end_date
        ).order_by(ConnectAttendance.date.desc()).all()
        
        # Get latest heartbeat snapshot
        from models import HeartbeatSnapshot
        latest_snapshot = HeartbeatSnapshot.query.filter_by(person_id=person_id).order_by(HeartbeatSnapshot.calculated_at.desc()).first()
        
        return jsonify({
            'person': {
                'id': person.id,
                'name': person.full_name,
                'email': person.email
            },
            'all_records': [{
                'id': r.id,
                'date': r.date.isoformat() if r.date else None,
                'status': r.status,
                'group_id': r.connect_group_id,
                'group_name': r.connect_group.name if r.connect_group else None,
                'created_at': r.created_at.isoformat() if r.created_at else None
            } for r in all_records],
            'recent_records': [{
                'id': r.id,
                'date': r.date.isoformat() if r.date else None,
                'status': r.status,
                'group_id': r.connect_group_id,
                'group_name': r.connect_group.name if r.connect_group else None,
                'in_range': start_date <= r.date <= end_date if r.date else False
            } for r in recent_records],
            'date_range': {
                'start': start_date.isoformat(),
                'end': end_date.isoformat()
            },
            'latest_snapshot': {
                'calculated_at': latest_snapshot.calculated_at.isoformat() if latest_snapshot else None,
                'engagement_score': latest_snapshot.engagement_score if latest_snapshot else None,
                'total_score': latest_snapshot.total_score if latest_snapshot else None
            } if latest_snapshot else None
        })
    except Exception as e:
        logger.error(f"Error in debug_connect_attendance: {e}", exc_info=True)
        return jsonify({'error': str(e)}), 500

