@app.route('/api/persons/demo/<person_id>', methods=['PUT'])
def update_person_demo(person_id):
    """Update person details (demo version - no auth required)"""
    try:
        person = Person.query.filter_by(id=person_id, is_active=True).first()
        if not person:
            return jsonify({'error': 'Person not found'}), 404
        
        data = request.get_json()
        if not data:
            return jsonify({'error': 'No data provided'}), 400
        
        # Update basic information
        if 'full_name' in data:
            person.full_name = data['full_name']
        if 'preferred_name' in data:
            person.preferred_name = data['preferred_name']
        if 'email' in data:
            # Normalize email - convert empty string to None
            email_value = data['email'].strip() if data.get('email') else None
            email_value = email_value if email_value else None
            
            # Note: Multiple people can share the same email (e.g., family members, kids)
            # No uniqueness check performed
            
            person.email = email_value
        if 'campus' in data:
            person.campus = data['campus']
        if 'phone' in data:
            person.phone = data['phone'] if data['phone'] else None
        if 'department' in data:
            person.department = data['department'] if data['department'] else None
        if 'connect_group' in data:
            person.connect_group = data['connect_group']
        if 'dream_team_roles' in data:
            # Convert array to JSON string for storage
            roles = data['dream_team_roles']
            person.dream_team_roles = json.dumps(roles) if roles and len(roles) > 0 else None
        if 'tags' in data:
            # Convert array to JSON string for storage
            tags = data['tags']
            person.tags = json.dumps(tags) if tags and len(tags) > 0 else None
        if 'pastoral_notes' in data:
            person.pastoral_notes = data['pastoral_notes'] if data['pastoral_notes'] else None
        
        # Update birthday (convert empty strings to None)
        if 'birthday' in data:
            value = data['birthday']
            if value == '' or value is None:
                person.birthday = None
            else:
                try:
                    if isinstance(value, str):
                        from datetime import datetime
                        person.birthday = datetime.strptime(value, '%Y-%m-%d').date()
                    else:
                        person.birthday = value
                except ValueError:
                    return jsonify({'error': 'Invalid date format for birthday'}), 400
        
        # Update discipleship milestones (convert empty strings to None)
        milestone_fields = [
            'dna_completed', 'baptised_on', 'rise_attended', 
            'filled_holy_spirit', 'first_served_on'
        ]
        
        for field in milestone_fields:
            if field in data:
                value = data[field]
                if value == '' or value is None:
                    setattr(person, field, None)
                else:
                    # Try to parse the date
                    try:
                        if isinstance(value, str):
                            # Parse date string
                            from datetime import datetime
                            parsed_date = datetime.strptime(value, '%Y-%m-%d').date()
                            setattr(person, field, parsed_date)
                        else:
                            setattr(person, field, value)
                    except ValueError:
                        return jsonify({'error': f'Invalid date format for {field}'}), 400
        
        # Update engagement profile pulse status if attendance/serving changed
        # (Pulse will be recalculated automatically on next access)
        
        db.session.commit()
        
        # Return updated person data
        person_data = person.to_dict()
        if person.engagement_profile:
            person_data['engagement'] = person.engagement_profile.to_dict()
        
        return jsonify({
            'message': 'Person updated successfully',
            'person': person_data
        })
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error updating person {person_id} (demo): {e}", exc_info=True)
        return jsonify({'error': f'Failed to update person: {str(e)}'}), 500


@app.route('/api/persons', methods=['GET'])
@login_required
def get_persons():
    """Get all persons with basic info (admin only)"""
    try:
        if not current_user.has_permission('query_access'):
            return jsonify({'error': 'Insufficient permissions'}), 403
        
        # Log database URI for debugging
        db_uri = app.config.get('SQLALCHEMY_DATABASE_URI', '')
        logger.info(f"GET /api/persons - Using database: {db_uri}")
        
        # Get query parameters
        campus_filter = request.args.get('campus', None)
        pulse_filter = request.args.get('pulse_status', None)
        department_filter = request.args.get('department', None)
        search = request.args.get('search', '').strip()
        # Archive filter: 'active', 'archived', 'all' (defaults to 'active' for backward compatibility)
        archive_filter = request.args.get('archive_filter', None)
        if archive_filter is None:
            # Support old 'include_archived' parameter for backward compatibility
            include_archived = request.args.get('include_archived', 'false').lower() == 'true'
            archive_filter = 'all' if include_archived else 'active'
        
        new_people = request.args.get('new_people', 'false').lower() == 'true'
        new_christians = request.args.get('new_christians', 'false').lower() == 'true'
        
        # Build query - FORCE fresh query from database
        if archive_filter == 'archived':
            query = Person.query.filter_by(is_active=False)
        elif archive_filter == 'all':
            query = Person.query
        else:  # 'active' or default
            query = Person.query.filter_by(is_active=True)
        
        if campus_filter and campus_filter != 'all_campuses':
            query = query.filter(Person.campus == campus_filter)
        
        if department_filter and department_filter != 'all':
            # Use case-insensitive matching for department filter
            # Handle different case formats that might exist in the database (e.g., "kids" vs "Kids")
            # SQLite uses LOWER() for case-insensitive comparison
            query = query.filter(
                db.func.lower(Person.department) == db.func.lower(department_filter)
            )
        
        if search:
            search_term = f"%{search}%"
            query = query.filter(
                db.or_(
                    Person.full_name.ilike(search_term),
                    Person.email.ilike(search_term),
                    Person.preferred_name.ilike(search_term)
                )
            )
        
        # Force fresh query by expiring session and querying directly
        db.session.expire_all()
        
        # Check if new columns exist before querying
        # Use raw SQL to check table schema
        try:
            from sqlalchemy import text
            table_info = db.session.execute(text("PRAGMA table_info(persons)")).fetchall()
            existing_columns = [row[1] for row in table_info]
            has_new_columns = all(col in existing_columns for col in ['family_id', 'is_new_christian', 'new_christian_date', 'follow_up_status', 'service_attended', 'is_new_person', 'new_person_date'])
        except Exception as e:
            logger.warning(f"Could not check table schema: {e}")
            has_new_columns = False
        
        # If new columns don't exist, use raw SQL to select only existing columns
        if not has_new_columns:
            logger.info("New Person columns not found, using raw SQL query")
            # Build SELECT statement with only existing columns
            base_columns = [
                'id', 'full_name', 'preferred_name', 'email', 'phone', 'campus', 
                'department', 'connect_group', 'dream_team_roles', 'birthday', 
                'pastoral_notes', 'tags', 'is_active', 'created_at', 'updated_at',
                'dna_completed', 'baptised_on', 'filled_holy_spirit', 'rise_attended', 'first_served_on'
            ]
            
            # Build WHERE clause
            where_clauses = []
            params = {}
            
            # Apply archive filter
            if archive_filter == 'archived':
                where_clauses.append("is_active = 0")
            elif archive_filter == 'all':
                pass  # Show all, no filter
            else:  # 'active' or default
                where_clauses.append("is_active = 1")
            
            if campus_filter and campus_filter != 'all_campuses':
                where_clauses.append("campus = :campus")
                params['campus'] = campus_filter
            
            if department_filter and department_filter != 'all':
                where_clauses.append("LOWER(department) = LOWER(:department)")
                params['department'] = department_filter
            
            if search:
                where_clauses.append("(full_name LIKE :search OR email LIKE :search OR preferred_name LIKE :search)")
                params['search'] = f"%{search}%"
            
            where_sql = " AND ".join(where_clauses) if where_clauses else "1=1"
            
            # Execute raw SQL
            sql = f"SELECT {', '.join(base_columns)} FROM persons WHERE {where_sql} ORDER BY full_name"
            rows = db.session.execute(text(sql), params).fetchall()
            
            # Convert rows to Person-like objects
            persons = []
            for row in rows:
                person_dict = dict(zip(base_columns, row))
                # Create a minimal Person object
                person = Person()
                for key, value in person_dict.items():
                    setattr(person, key, value)
                persons.append(person)
        else:
            # New columns exist, use normal query
            persons = query.order_by(Person.full_name).all()
        
        # Apply new_people filter (last 30 days OR manually flagged)
        if new_people:
            thirty_days_ago = datetime.utcnow() - timedelta(days=30)
            thirty_days_ago_date = thirty_days_ago.date()
            filtered_persons = []
            for p in persons:
                try:
                    # Check if manually flagged as new person
                    is_new_person = getattr(p, 'is_new_person', None)  # None if column doesn't exist
                    new_person_date = getattr(p, 'new_person_date', None)
                    
                    # Include if:
                    # 1. Manually flagged as new person (is_new_person=True) AND date is within last 30 days (or no date set)
                    # 2. OR created in last 30 days AND is_new_person is not explicitly False (for backward compatibility)
                    is_flagged_new = False
                    if is_new_person is True:  # Explicitly True
                        if new_person_date is None:
                            # No date set, include if flagged
                            is_flagged_new = True
                        else:
                            # Convert to date if needed
                            if isinstance(new_person_date, str):
                                try:
                                    new_person_date = datetime.fromisoformat(new_person_date.replace('Z', '+00:00')).date()
                                except:
                                    new_person_date = datetime.strptime(new_person_date, '%Y-%m-%d').date()
                            elif hasattr(new_person_date, 'date'):
                                new_person_date = new_person_date.date()
                            
                            # Check if date is within last 30 days
                            if new_person_date >= thirty_days_ago_date:
                                is_flagged_new = True
                    
                    # Only include recently created if is_new_person is not explicitly False
                    # This allows backward compatibility while respecting manual unmarking
                    is_recently_created = False
                    if is_new_person is not False:  # None or True (not explicitly False)
                        is_recently_created = p.created_at and p.created_at >= thirty_days_ago
                    
                    if is_flagged_new or is_recently_created:
                        filtered_persons.append(p)
                except Exception as e:
                    logger.debug(f"Error checking new_person status for person {getattr(p, 'id', 'unknown')}: {e}")
                    continue
            persons = filtered_persons
        
        # Apply new_christians filter
        if new_christians:
            two_years_ago = datetime.utcnow().date() - timedelta(days=730)
            filtered_persons = []
            for p in persons:
                try:
                    baptised_on = getattr(p, 'baptised_on', None)
                    is_new_christian = getattr(p, 'is_new_christian', False)
                    new_christian_date = getattr(p, 'new_christian_date', None)
                    if (baptised_on and baptised_on >= two_years_ago) or is_new_christian or (new_christian_date and new_christian_date >= two_years_ago):
                        filtered_persons.append(p)
                except Exception as e:
                    logger.debug(f"Error checking new_christian status for person {getattr(p, 'id', 'unknown')}: {e}")
                    continue
            persons = filtered_persons
        
        # Log what we found
        logger.info(f"GET /api/persons - Query returned {len(persons)} persons")
        logger.info(f"GET /api/persons - Database URI: {db_uri}")
        for person in persons:
            logger.info(f"  • {person.id}: '{person.full_name}' ({person.email})")
        
        # Serialize persons with engagement data
        result = []
        for person in persons:
            try:
                person_data = person.to_dict()
            except Exception as e:
                logger.error(f"Error serializing person {person.id}: {e}", exc_info=True)
                # Skip this person if we can't serialize them
                continue
            
            # Add engagement profile data - use raw SQL to avoid SQLAlchemy schema issues
            engagement_data = None
            try:
                # Use raw SQL query to avoid SQLAlchemy ORM schema mismatch issues
                from sqlalchemy import text
                engagement_row = db.session.execute(
                    text("""
                        SELECT pulse_status, last_seen, attendance_frequency, serving_frequency, 
                               overall_engagement, attendance_log, serving_log
                        FROM engagement_profiles 
                        WHERE person_id = :person_id
                    """),
                    {'person_id': person.id}
                ).fetchone()
                
                if engagement_row:
                    # Parse the engagement data manually
                    pulse_status = engagement_row[0] or 'red'
                    # Handle last_seen - might be date object or string
                    last_seen_raw = engagement_row[1]
                    if last_seen_raw:
                        if isinstance(last_seen_raw, str):
                            # Already a string, might be ISO format or SQLite format
                            # Try to parse and reformat if it's a valid date string
                            try:
                                # If it's already ISO format, use as-is
                                if 'T' in last_seen_raw or len(last_seen_raw) == 10:
                                    last_seen = last_seen_raw
                                else:
                                    # SQLite format like '2025-12-17 00:00:00.000000'
                                    dt = datetime.fromisoformat(last_seen_raw.replace(' ', 'T').split('.')[0])
                                    last_seen = dt.isoformat()
                            except:
                                last_seen = last_seen_raw  # Use as-is if parsing fails
                        elif hasattr(last_seen_raw, 'isoformat'):
                            last_seen = last_seen_raw.isoformat()
                        else:
                            last_seen = str(last_seen_raw)
                    else:
                        last_seen = None
                    attendance_frequency = float(engagement_row[2] or 0.0)
                    serving_frequency = float(engagement_row[3] or 0.0)
                    overall_engagement = float(engagement_row[4] or 0.0)
                    
                    # Parse JSON logs
                    try:
                        attendance_log = json.loads(engagement_row[5] or '[]')
                    except:
                        attendance_log = []
                    
                    try:
                        # Note: milestones_log doesn't exist - get from serving_log (index 6) instead
                        milestones_log = json.loads(engagement_row[6] or '[]') if len(engagement_row) > 6 else []
                    except:
                        milestones_log = []
                    
                    # Calculate pulse reasons from the data
                    pulse_reasons = []
                    if last_seen:
                        try:
                            last_seen_date = datetime.fromisoformat(last_seen).date() if isinstance(last_seen, str) else last_seen
                            days_ago = (datetime.utcnow().date() - last_seen_date).days
                            pulse_reasons.append(f"Last seen {days_ago} days ago")
                        except:
                            pulse_reasons.append("Last seen recently")
                    else:
                        pulse_reasons.append("No attendance recorded")
                    
                    pulse_reasons.append(f"Services: {len(attendance_log)} in attendance log")
                    pulse_reasons.append(f"Overall engagement: {int(overall_engagement)}/100")
                    
                    engagement_data = {
                        'pulse_status': pulse_status,
                        'last_seen': last_seen,
                        'pulse_reasons': pulse_reasons,
                        'attendance_frequency': attendance_frequency,
                        'serving_frequency': serving_frequency,
                        'overall_engagement': overall_engagement
                    }
            except Exception as e:
                # If raw SQL fails, just use defaults
                logger.warning(f"Error fetching engagement profile for {person.id}: {e}")
                engagement_data = None
            
            if engagement_data:
                person_data['pulse_status'] = engagement_data.get('pulse_status', 'red')
                person_data['last_seen'] = engagement_data.get('last_seen')
                person_data['pulse_reasons'] = engagement_data.get('pulse_reasons', ['No engagement data'])
                person_data['attendance_frequency'] = engagement_data.get('attendance_frequency', 0.0)
                person_data['serving_frequency'] = engagement_data.get('serving_frequency', 0.0)
                person_data['overall_engagement'] = engagement_data.get('overall_engagement', 0.0)
                
                # Calculate heartbeat score (0-100) from pulse_status and engagement
                pulse_status = person_data['pulse_status']
                overall_engagement = person_data['overall_engagement']
                
                # Base score from pulse status
                if pulse_status == 'green':
                    base_score = 85
                elif pulse_status == 'amber':
                    base_score = 65
                else:  # red
                    base_score = 35
                
                # Adjust based on overall engagement (weighted average)
                heartbeat_score = int((base_score * 0.7) + (overall_engagement * 0.3))
                person_data['heartbeat_score'] = max(0, min(100, heartbeat_score))
            else:
                person_data['pulse_status'] = 'red'
                person_data['last_seen'] = None
                person_data['pulse_reasons'] = ['No engagement data']
                person_data['attendance_frequency'] = 0.0
                person_data['serving_frequency'] = 0.0
                person_data['overall_engagement'] = 0.0
                person_data['heartbeat_score'] = 35  # Default for red status
            
            # Get connect group name if connect_group ID exists
            if person.connect_group:
                try:
                    # Try to find by ID first
                    connect_group = ConnectGroup.query.filter_by(id=person.connect_group, is_active=True).first()
                    if connect_group:
                        person_data['connect_group_name'] = connect_group.name
                    else:
                        # If not found by ID, use the stored value as name
                        person_data['connect_group_name'] = person.connect_group
                except Exception as e:
                    logger.warning(f"Error fetching connect group for person {person.id}: {e}")
                    person_data['connect_group_name'] = person.connect_group
            else:
                person_data['connect_group_name'] = None
            
            # Get heartbeat status from HeartbeatSnapshot if available
            heartbeat_status = None
            heartbeat_score = person_data.get('heartbeat_score', 0)
            try:
                from models import HeartbeatSnapshot
                snapshot = HeartbeatSnapshot.query.filter_by(
                    person_id=person.id
                ).order_by(HeartbeatSnapshot.calculated_at.desc()).first()
                if snapshot:
                    heartbeat_status = snapshot.status  # 'healthy', 'watch', 'at_risk', 'critical'
                    heartbeat_score = snapshot.total_score
                    person_data['heartbeat_score'] = heartbeat_score
                    person_data['heartbeat_status'] = heartbeat_status
            except Exception as e:
                logger.warning(f"Error fetching heartbeat snapshot for {person.id}: {e}")
            
            # If no heartbeat snapshot, infer status from pulse_status and score
            if not heartbeat_status:
                if heartbeat_score >= 80:
                    heartbeat_status = 'healthy'
                elif heartbeat_score >= 60:
                    heartbeat_status = 'watch'
                elif heartbeat_score >= 40:
                    heartbeat_status = 'at_risk'
                else:
                    heartbeat_status = 'critical'
                person_data['heartbeat_status'] = heartbeat_status
            
            # Apply pulse filter if specified (map heartbeat status to pulse_status for backward compatibility)
            if pulse_filter:
                # Map heartbeat status to pulse_status for filtering
                status_mapping = {
                    'healthy': 'green',
                    'watch': 'amber',
                    'at_risk': 'amber',
                    'critical': 'red'
                }
                mapped_pulse = status_mapping.get(heartbeat_status, person_data.get('pulse_status', 'red'))
                
                # Also support direct heartbeat status filtering
                if pulse_filter in ['healthy', 'watch', 'at_risk', 'critical']:
                    if heartbeat_status != pulse_filter:
                        continue
                elif pulse_filter in ['green', 'amber', 'red']:
                    if mapped_pulse != pulse_filter and person_data.get('pulse_status') != pulse_filter:
                        continue
            
            result.append(person_data)
        
        return jsonify({
            'persons': result,
            'total': len(result),
            'filters': {
                'campus': campus_filter,
                'pulse_status': pulse_filter,
                'department': department_filter,
                'search': search
            }
        })
        
    except Exception as e:
        import traceback
        error_traceback = traceback.format_exc()
        logger.error(f"Error fetching persons: {e}\n{error_traceback}")
        return jsonify({'error': f'Failed to fetch persons: {str(e)}'}), 500


@app.route('/api/persons', methods=['POST'])
@login_required
def create_person():
    """Create new person with engagement profile (admin only)"""
    try:
        if not current_user.has_permission('query_access'):
            return jsonify({'error': 'Insufficient permissions'}), 403
        
        data = request.get_json()
        
        # Validate required fields
        required_fields = ['full_name', 'campus']
        for field in required_fields:
            if not data.get(field):
                return jsonify({'error': f'Missing required field: {field}'}), 400
        
        # Normalize email - convert empty string to None
        email = data.get('email', '').strip() or None
        
        # Note: Multiple people can share the same email (e.g., family members, kids)
        # No uniqueness check performed
        
        # Normalize department before creating person
        department_raw = data.get('department', '').strip() if data.get('department') else None
        department_normalized = None
        if department_raw:
            dept_lower = department_raw.lower()
            if dept_lower == 'kids':
                department_normalized = 'Kids'
            elif dept_lower == 'youth':
                department_normalized = 'Youth'
            elif dept_lower in ['young adults', 'youngadults', 'young_adults']:
                department_normalized = 'Young Adults'
            elif dept_lower == 'families':
                department_normalized = 'Families'
            elif dept_lower == 'adults':
                department_normalized = 'Adults'
            elif dept_lower == 'seniors':
                department_normalized = 'Seniors'
            else:
                department_normalized = department_raw.title()
        
        # Create person and engagement profile
        person, engagement = create_person_with_engagement(
            full_name=data['full_name'],
            email=email,
            campus=data['campus'],
            preferred_name=data.get('preferred_name'),
            phone=data.get('phone'),
            department=department_normalized,
            connect_group=data.get('connect_group'),
            dream_team_roles=data.get('dream_team_roles', []),
            birthday=datetime.strptime(data['birthday'], '%Y-%m-%d').date() if data.get('birthday') else None,
            pastoral_notes=data.get('pastoral_notes'),
            tags=data.get('tags', [])
        )
        
        # Add discipleship milestones if provided
        milestone_fields = ['dna_completed', 'baptised_on', 'filled_holy_spirit', 'rise_attended', 'first_served_on']
        for field in milestone_fields:
            if data.get(field):
                setattr(person, field, datetime.strptime(data[field], '%Y-%m-%d').date())
        
        db.session.commit()
        
        # Return created person with engagement data
        person_data = person.to_dict()
        # Safely serialize last_seen
        last_seen_val = engagement.last_seen
        if last_seen_val:
            if isinstance(last_seen_val, str):
                last_seen_str = last_seen_val
            elif hasattr(last_seen_val, 'isoformat'):
                last_seen_str = last_seen_val.isoformat()
            else:
                last_seen_str = str(last_seen_val)
        else:
            last_seen_str = None
        
        person_data.update({
            'pulse_status': engagement.pulse_status,
            'last_seen': last_seen_str,
            'pulse_reasons': engagement.get_pulse_reasons()
        })
        
        return jsonify(person_data), 201
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error creating person: {e}")
        return jsonify({'error': 'Failed to create person'}), 500


@app.route('/api/persons/export', methods=['GET'])
@login_required
def export_persons_csv():
    """Export filtered persons to CSV"""
    try:
        if not current_user.has_permission('query_access'):
            return jsonify({'error': 'Insufficient permissions'}), 403
        
        # Get query parameters (same as get_persons)
        campus_filter = request.args.get('campus', None)
        pulse_filter = request.args.get('pulse_status', None)
        department_filter = request.args.get('department', None)
        search = request.args.get('search', '').strip()
        # Archive filter: 'active', 'archived', 'all' (defaults to 'active' for backward compatibility)
        archive_filter = request.args.get('archive_filter', None)
        if archive_filter is None:
            # Support old 'include_archived' parameter for backward compatibility
            include_archived = request.args.get('include_archived', 'false').lower() == 'true'
            archive_filter = 'all' if include_archived else 'active'
        
        # Build query (same logic as get_persons)
        if archive_filter == 'archived':
            query = Person.query.filter_by(is_active=False)
        elif archive_filter == 'all':
            query = Person.query
        else:  # 'active' or default
            query = Person.query.filter_by(is_active=True)
        
        if campus_filter and campus_filter != 'all_campuses':
            query = query.filter(Person.campus == campus_filter)
        
        if department_filter and department_filter != 'all':
            query = query.filter(
                db.func.lower(Person.department) == db.func.lower(department_filter)
            )
        
        if search:
            search_term = f"%{search}%"
            query = query.filter(
                db.or_(
                    Person.full_name.ilike(search_term),
                    Person.email.ilike(search_term),
                    Person.preferred_name.ilike(search_term)
                )
            )
        
        persons = query.order_by(Person.full_name).all()
        
        # Build CSV
        import csv
        import io
        
        output = io.StringIO()
        writer = csv.writer(output)
        
        # Write header
        writer.writerow([
            'ID', 'Full Name', 'Preferred Name', 'Email', 'Phone',
            'Campus', 'Department', 'Connect Group', 'Dream Team Roles',
            'Birthday', 'Tags', 'Pulse Status', 'Last Seen',
            'Attendance Frequency', 'Serving Frequency', 'Overall Engagement',
            'DNA Completed', 'Baptised On', 'Filled Holy Spirit',
            'RISE Attended', 'First Served On', 'Pastoral Notes',
            'Is Active', 'Created At', 'Updated At'
        ])
        
        # Write data rows
        for person in persons:
            # Get engagement profile data
            pulse_status = 'red'
            last_seen = None
            attendance_frequency = 0.0
            serving_frequency = 0.0
            overall_engagement = 0.0
            
            if person.engagement_profile:
                pulse_status = person.engagement_profile.pulse_status or 'red'
                # Safely serialize last_seen
                last_seen_raw = person.engagement_profile.last_seen
                if last_seen_raw:
                    if isinstance(last_seen_raw, str):
                        last_seen = last_seen_raw
                    elif hasattr(last_seen_raw, 'isoformat'):
                        last_seen = last_seen_raw.isoformat()
                    else:
                        last_seen = str(last_seen_raw)
                else:
                    last_seen = None
                attendance_frequency = person.engagement_profile.attendance_frequency or 0.0
                serving_frequency = person.engagement_profile.serving_frequency or 0.0
                overall_engagement = person.engagement_profile.overall_engagement or 0.0
            
            # Parse JSON fields
            dream_team_roles = ''
            tags = ''
            try:
                if person.dream_team_roles:
                    dream_team_roles = ', '.join(json.loads(person.dream_team_roles))
            except:
                dream_team_roles = person.dream_team_roles or ''
            
            try:
                if person.tags:
                    tags = ', '.join(json.loads(person.tags))
            except:
                tags = person.tags or ''
            
            writer.writerow([
                person.id,
                person.full_name or '',
                person.preferred_name or '',
                person.email or '',
                person.phone or '',
                person.campus or '',
                person.department or '',
                person.connect_group or '',
                dream_team_roles,
                person.birthday.isoformat() if person.birthday else '',
                tags,
                pulse_status,
                last_seen or '',
                attendance_frequency,
                serving_frequency,
                overall_engagement,
                person.dna_completed.isoformat() if person.dna_completed else '',
                person.baptised_on.isoformat() if person.baptised_on else '',
                person.filled_holy_spirit.isoformat() if person.filled_holy_spirit else '',
                person.rise_attended.isoformat() if person.rise_attended else '',
                person.first_served_on.isoformat() if person.first_served_on else '',
                person.pastoral_notes or '',
                person.is_active,
                person.created_at.isoformat() if person.created_at else '',
                person.updated_at.isoformat() if person.updated_at else ''
            ])
        
        # Create response
        output.seek(0)
        response = Response(
            output.getvalue(),
            mimetype='text/csv',
            headers={
                'Content-Disposition': f'attachment; filename=people-export-{datetime.now().strftime("%Y%m%d")}.csv'
            }
        )
        return response
        
    except Exception as e:
        logger.error(f"Error exporting persons CSV: {e}", exc_info=True)
        return jsonify({'error': 'Failed to export CSV'}), 500


@app.route('/api/persons/<person_id>', methods=['GET'])
@login_required
def get_person_detail(person_id):
    """Get detailed person info with full engagement profile (admin only)"""
    try:
        if not current_user.has_permission('query_access'):
            return jsonify({'error': 'Insufficient permissions'}), 403
        
        # Force fresh query
        db.session.expire_all()
        db_uri = app.config.get('SQLALCHEMY_DATABASE_URI', '')
        logger.info(f"GET /api/persons/{person_id} - Using database: {db_uri}")
        
        person = Person.query.filter_by(id=person_id, is_active=True).first()
        if not person:
            logger.warning(f"GET /api/persons/{person_id} - Person not found in database")
            # Check if person exists but is inactive
            inactive_person = Person.query.filter_by(id=person_id).first()
            if inactive_person:
                logger.warning(f"  Person exists but is inactive (is_active={inactive_person.is_active})")
            return jsonify({'error': 'Person not found'}), 404
        
        logger.info(f"GET /api/persons/{person_id} - Found: '{person.full_name}' ({person.email})")
        
        # Get person data
        person_data = person.to_dict()
        
        # Add full engagement profile (handle schema mismatch gracefully)
        try:
            if hasattr(person, 'engagement_profile') and person.engagement_profile:
                try:
                    engagement_data = person.engagement_profile.to_dict()
                    person_data['engagement'] = engagement_data
                except Exception as e:
                    logger.warning(f"Error serializing engagement profile for {person_id}: {e}")
                    person_data['engagement'] = None
            else:
                # Create engagement profile if it doesn't exist
                try:
                    engagement = EngagementProfile(person_id=person.id)
                    db.session.add(engagement)
                    db.session.commit()
                    person_data['engagement'] = engagement.to_dict()
                except Exception as e:
                    logger.warning(f"Error creating engagement profile for {person_id}: {e}")
                    person_data['engagement'] = None
        except Exception as e:
            # Schema mismatch - engagement_profiles table structure doesn't match model
            logger.warning(f"Error accessing engagement profile (schema mismatch): {e}")
            person_data['engagement'] = None
        
        return jsonify(person_data)
        
    except Exception as e:
        logger.error(f"Error fetching person detail: {e}", exc_info=True)
        return jsonify({'error': 'Failed to fetch person details'}), 500


def calculate_streaks_and_next_steps(person):
    """Calculate attendance streaks and recommend next steps for a person"""
    # Import models that may not exist, handle gracefully
    try:
        from models import DiscipleshipStep, TVUserEpisodeProgress, TVEpisode
    except ImportError:
        DiscipleshipStep = None
        TVUserEpisodeProgress = None
        TVEpisode = None
    
    streaks = []
    next_steps = []
    
    try:
        # Get attendance log from engagement profile
        if person.engagement_profile:
            attendance_log_str = person.engagement_profile.attendance_log or '[]'
            try:
                attendance_log = json.loads(attendance_log_str) if isinstance(attendance_log_str, str) else attendance_log_str
            except:
                attendance_log = []
            
            # Calculate Sunday attendance streak
            if attendance_log:
                # Parse dates and find consecutive Sundays
                from datetime import date, timedelta
                sundays = []
                for entry in attendance_log:
                    if isinstance(entry, dict) and 'date' in entry:
                        try:
                            entry_date = date.fromisoformat(entry['date'].split('T')[0]) if 'T' in entry['date'] else date.fromisoformat(entry['date'])
                            # Check if it's a Sunday (Monday=0, Sunday=6)
                            if entry_date.weekday() == 6:
                                sundays.append(entry_date)
                        except:
                            continue
                
                if sundays:
                    sundays = sorted(set(sundays), reverse=True)
                    # Calculate current streak
                    today = date.today()
                    last_sunday = today - timedelta(days=(today.weekday() + 1) % 7)
                    if last_sunday > today:
                        last_sunday -= timedelta(days=7)
                    
                    current_streak = 0
                    expected_date = last_sunday
                    for sunday in sundays:
                        if sunday == expected_date or sunday == expected_date - timedelta(days=7):
                            current_streak += 1
                            expected_date = sunday - timedelta(days=7)
                        elif sunday > expected_date:
                            # Gap in streak
                            break
                    
                    if current_streak > 0:
                        sunday_text = "s" if current_streak != 1 else ""
                        streaks.append({
                            'type': 'sunday_attendance',
                            'label': 'Sunday Attendance',
                            'count': current_streak,
                            'emoji': '⛪',
                            'message': f'{current_streak} Sunday{sunday_text} in a row!' if current_streak > 0 else None
                        })
    except Exception as e:
        logger.warning(f"Error calculating attendance streak: {e}")
    
    # Check for completed discipleship steps (milestones)
    try:
        completed_steps = []
        try:
            if DiscipleshipStep:
                completed_steps = DiscipleshipStep.query.filter_by(person_id=person.id).all()
            if completed_steps:
                milestones = []
                if any(s.type == 'baptism' for s in completed_steps):
                    milestones.append('Baptized')
                if any(s.type == 'filled_holy_spirit' for s in completed_steps):
                    milestones.append('Filled with Holy Spirit')
                if any(s.type == 'dna_completion' for s in completed_steps):
                    milestones.append('DNA Completed')
                if any(s.type == 'tv_series_completion' for s in completed_steps):
                    series_completed = len([s for s in completed_steps if s.type == 'tv_series_completion'])
                    milestones.append(f'{series_completed} Series Completed')
                
                if milestones:
                    streaks.append({
                        'type': 'milestones',
                        'label': 'Milestones',
                        'count': len(milestones),
                        'emoji': '🏆',
                        'message': ', '.join(milestones)
                    })
        except Exception as e:
            logger.warning(f"Error calculating milestones: {e}")
        
        # Generate next steps recommendations
        completed_steps_list = []
        try:
            if DiscipleshipStep:
                completed_steps_list = DiscipleshipStep.query.filter_by(person_id=person.id).all()
        except:
            pass
        
        try:
            # Check if person needs to complete pathway steps
            pathway_progress = PersonPathwayProgress.query.filter_by(person_id=person.id, is_active=True).first()
            if pathway_progress and pathway_progress.next_step:
                next_steps.append({
                    'type': 'pathway_step',
                    'title': pathway_progress.next_step.step_name,
                    'description': f'Complete your next pathway step: {pathway_progress.next_step.step_name}',
                    'action': 'pathway',
                    'priority': 'high'
                })
            
            # Check if person hasn't been baptized
            if not any(s.type == 'baptism' for s in completed_steps_list):
                next_steps.append({
                    'type': 'baptism',
                    'title': 'Get Baptized',
                    'description': 'Take the next step in your faith journey',
                    'action': 'contact',
                    'priority': 'medium'
                })
            
            # Check if person hasn't joined a connect group
            if not person.connect_group:
                next_steps.append({
                    'type': 'connect_group',
                    'title': 'Join a Connect Group',
                    'description': 'Connect with others and grow in community',
                    'action': 'groups',
                    'priority': 'high'
                })
            
            # Check if person hasn't completed any TV series
            try:
                tv_progress = TVUserEpisodeProgress.query.filter_by(person_id=person.id, completed=True).join(TVEpisode).filter(TVEpisode.is_published==True).first()
                if not tv_progress:
                    next_steps.append({
                        'type': 'tv_series',
                        'title': 'Watch a Discipleship Course',
                        'description': 'Start your first Pulse TV course',
                        'action': 'tv',
                        'priority': 'medium'
                    })
            except:
                pass
            
        except Exception as e:
            logger.warning(f"Error generating next steps: {e}")
    
    except Exception as e:
        logger.error(f"Error in calculate_streaks_and_next_steps: {e}", exc_info=True)
    
    return {
        'streaks': streaks,
        'next_steps': next_steps[:5]  # Limit to 5 recommendations
    }


@app.route('/api/persons/email/<email>', methods=['GET'])
def get_person_by_email(email):
    """Get person profile by email - public endpoint for mobile app"""
    import sqlite3
    
    # Initialize variables
    conn = None
    cursor = None
    
    try:
        # Helper functions
        def safe_str(val):
            """Convert value to string safely"""
            if val is None:
                return None
            return str(val)
        
        def safe_json_load(val):
            """Parse JSON string safely"""
            if not val:
                return []
            try:
                if isinstance(val, str):
                    return json.loads(val)
                return val
            except:
                return []
        
        # Get database path
        db_path = get_db_path()
        if not db_path or not os.path.exists(db_path):
            return jsonify({'error': 'Database not found'}), 500
        
        # Connect to database
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()
        
        # Query person by email
        cursor.execute("""
            SELECT id, full_name, preferred_name, email, phone, campus, department,
                   connect_group, dream_team_roles, birthday, pastoral_notes, tags,
                   is_active, created_at, updated_at, dna_completed, baptised_on,
                   filled_holy_spirit, rise_attended, first_served_on
            FROM persons 
            WHERE lower(email) = ? AND is_active = 1 
            LIMIT 1
        """, (email.lower(),))
        
        result = cursor.fetchone()
        
        # Close database connection
        cursor.close()
        conn.close()
        
        # Check if person was found
        if not result:
            return jsonify({'error': 'Person not found'}), 404
        
        # Build person data dictionary
        person_data = {
            'id': safe_str(result[0]),
            'full_name': safe_str(result[1]) or '',
            'preferred_name': safe_str(result[2]),
            'email': safe_str(result[3]),
            'phone': safe_str(result[4]),
            'campus': safe_str(result[5]),
            'department': safe_str(result[6]),
            'connect_group': safe_str(result[7]),
            'dream_team_roles': safe_json_load(result[8]),
            'birthday': safe_str(result[9]),
            'pastoral_notes': safe_str(result[10]),
            'tags': safe_json_load(result[11]),
            'is_active': bool(result[12]) if result[12] is not None else True,
            'created_at': safe_str(result[13]),
            'updated_at': safe_str(result[14]),
            'dna_completed': safe_str(result[15]),
            'baptised_on': safe_str(result[16]),
            'filled_holy_spirit': safe_str(result[17]),
            'rise_attended': safe_str(result[18]),
            'first_served_on': safe_str(result[19]),
            # Default values for optional fields
            'family_id': None,
            'is_new_christian': False,
            'new_christian_date': None,
            'follow_up_status': None,
            'service_attended': None,
            'is_new_person': False,
            'new_person_date': None,
            'engagement': None,
            'pathway': None,
            'streaks': [],
            'next_steps': []
        }
        
        return jsonify(person_data), 200
        
    except Exception as e:
        # Clean up database connection if open
        if cursor:
            try:
                cursor.close()
            except:
                pass
        if conn:
            try:
                conn.close()
            except:
                pass
        
        # Log error (without traceback formatting that might cause issues)
        print(f"ERROR in get_person_by_email: {type(e).__name__}")
        
        return jsonify({'error': 'Internal server error'}), 500


@app.route('/api/people/profile', methods=['PUT'])
def update_profile():
    """Update person profile by email - public endpoint for mobile app"""
    try:
        data = request.get_json()
        email = data.get('email', '').strip()
        
        if not email:
            return jsonify({'error': 'Email parameter required'}), 400
        
        # Find person by email (case-insensitive)
        person = Person.query.filter(
            db.func.lower(Person.email) == email.lower(),
            Person.is_active == True
        ).first()
        
        if not person:
            return jsonify({'error': 'Person not found. Please ensure your profile exists in Pulse.'}), 404
        
        # Log which database we're using
        db_uri = app.config.get('SQLALCHEMY_DATABASE_URI', '')
        db_path = get_db_path()
        logger.info(f"PUT /api/people/profile - Using database: {db_uri}")
        logger.info(f"PUT /api/people/profile - Database path: {db_path}")
        logger.info(f"PUT /api/people/profile - Person ID: {person.id}")
        
        # Log what we're updating
        logger.info(f"Updating profile for {email} - Before: full_name='{person.full_name}', preferred_name='{person.preferred_name}', phone='{person.phone}'")
        
        # Update allowed fields
        if 'full_name' in data and data['full_name']:
            old_name = person.full_name
            person.full_name = data['full_name'].strip()
            logger.info(f"  Updating full_name: '{old_name}' -> '{person.full_name}'")
        if 'preferred_name' in data:
            old_pref = person.preferred_name
            person.preferred_name = data['preferred_name'].strip() if data.get('preferred_name') else None
            logger.info(f"  Updating preferred_name: '{old_pref}' -> '{person.preferred_name}'")
        if 'phone' in data:
            old_phone = person.phone
            person.phone = data['phone'].strip() if data.get('phone') else None
            logger.info(f"  Updating phone: '{old_phone}' -> '{person.phone}'")
        
        # Force commit and flush to ensure data is written to disk
        db.session.flush()
        db.session.commit()
        logger.info(f"  Committed changes to database: {db_path}")
        
        # Verify the update was actually saved by querying directly from database
        import sqlite3
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()
        cursor.execute("SELECT full_name, preferred_name, phone FROM persons WHERE id = ?", (person.id,))
        db_row = cursor.fetchone()
        conn.close()
        if db_row:
            logger.info(f"  Verified in database: full_name='{db_row[0]}', preferred_name='{db_row[1]}', phone='{db_row[2]}'")
        else:
            logger.error(f"  ERROR: Person not found in database after commit!")
        
        # Expire and re-query to get absolutely fresh data
        db.session.expire_all()
        person_id = person.id  # Save ID before expire
        
        # Close and reopen session to ensure fresh connection
        db.session.close()
        
        # Re-query using the ID to ensure we get fresh data
        person = Person.query.filter_by(id=person_id, is_active=True).first()
        if person:
            db.session.refresh(person)
            logger.info(f"  After re-query: full_name='{person.full_name}', preferred_name='{person.preferred_name}', phone='{person.phone}'")
        else:
            logger.error(f"  ERROR: Person not found after re-query with id={person_id}")
        
        # Return updated person data
        person_data = person.to_dict()
        if person_data.get('campus'):
            campus_name = person_data['campus']
            if '_' in campus_name:
                campus_name = ' '.join(word.capitalize() for word in campus_name.split('_'))
            else:
                campus_name = campus_name.title()
            person_data['campus_display'] = campus_name
            person_data['campus'] = campus_name
        
        response = jsonify({
            'success': True,
            'message': 'Profile updated successfully',
            'profile': person_data
        })
        # Add cache-busting headers
        response.headers['Cache-Control'] = 'no-cache, no-store, must-revalidate'
        response.headers['Pragma'] = 'no-cache'
        response.headers['Expires'] = '0'
        return response
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error updating profile: {e}", exc_info=True)
        return jsonify({'error': 'Failed to update profile'}), 500


@app.route('/api/journeys/my-journey', methods=['GET'])
def get_my_pathway():
    """Get journey data for a person by email - public endpoint for mobile app"""
    try:
        email = request.args.get('email', '').strip()
        if not email:
            return jsonify({'error': 'Email parameter required'}), 400
        
        # Find person by email (case-insensitive)
        person = Person.query.filter(
            db.func.lower(Person.email) == email.lower(),
            Person.is_active == True
        ).first()
        
        if not person:
            return jsonify({'journey': None, 'pathway': None, 'error': 'Person not found'}), 404
        
        # Get the person's ACTUAL assigned pathway from database (not hardcoded)
        try:
            # Get the person's active pathway progress (assigned by staff)
            pathway_progress = PersonPathwayProgress.query.filter_by(
                person_id=person.id,
                is_active=True
            ).first()
            
            if pathway_progress:
                # Person has an assigned pathway - return it!
                pathway_dict = pathway_progress.to_dict()
                logger.info(f"Found assigned pathway for {person.email}: {pathway_dict.get('pathway_name')}")
                return jsonify({'journey': pathway_dict, 'pathway': pathway_dict})  # Backward compatibility
            else:
                # No pathway assigned - return None (staff needs to assign one)
                logger.info(f"No pathway assigned to {person.email}")
                return jsonify({'journey': None, 'pathway': None})  # Backward compatibility
                
        except Exception as e:
            logger.error(f"Error loading assigned pathway: {e}", exc_info=True)
            return jsonify({'journey': None, 'pathway': None, 'error': 'Failed to load journey'}), 500
        
    except Exception as e:
        logger.error(f"Error fetching pathway for email {email}: {e}", exc_info=True)
        return jsonify({'journey': None, 'pathway': None, 'error': 'Failed to fetch journey data'}), 500


@app.route('/api/journeys/complete-step', methods=['POST'])
def complete_pathway_step():
    """Mark a journey step as complete (public endpoint for mobile app)"""
    try:
        data = request.get_json()
        email = data.get('email', '').strip()
        step_id = data.get('step_id')
        
        if not email:
            return jsonify({'error': 'Email is required'}), 400
        if not step_id:
            return jsonify({'error': 'Step ID is required'}), 400
        
        # Find person by email
        person = Person.query.filter(
            db.func.lower(Person.email) == email.lower(),
            Person.is_active == True
        ).first()
        
        if not person:
            return jsonify({'error': 'Person not found'}), 404
        
        # Get person's active pathway progress
        pathway_progress = PersonPathwayProgress.query.filter_by(
            person_id=person.id,
            is_active=True
        ).first()
        
        if not pathway_progress:
            return jsonify({'error': 'No active pathway found'}), 404
        
        # Verify step belongs to this pathway
        step = PathwayStep.query.filter_by(id=step_id).first()
        if not step or step.pathway_id != pathway_progress.pathway_id:
            return jsonify({'error': 'Step not found in your pathway'}), 404
        
        # Check if already completed
        existing_completion = PersonPathwayStepCompletion.query.filter_by(
            person_pathway_progress_id=pathway_progress.id,
            pathway_step_id=step_id
        ).first()
        
        if existing_completion:
            return jsonify({
                'message': 'Step already completed',
                'journey': pathway_progress.to_dict(),
                'pathway': pathway_progress.to_dict()  # Backward compatibility
            }), 200
        
        # Mark step as complete
        completion = PersonPathwayStepCompletion(
            person_pathway_progress_id=pathway_progress.id,
            pathway_step_id=step_id,
            completed_by_person_id=person.id,
            notes=data.get('notes')
        )
        db.session.add(completion)
        
        # Update current_step_id to next uncompleted step
        next_step = pathway_progress.get_next_step()
        if next_step:
            pathway_progress.current_step_id = next_step.id
        else:
            # All steps completed!
            pathway_progress.completed_at = datetime.utcnow()
            pathway_progress.current_step_id = None
        
        # Update started_at if this is the first step
        if not pathway_progress.started_at:
            pathway_progress.started_at = datetime.utcnow()
        
        pathway_progress.updated_at = datetime.utcnow()
        db.session.commit()
        
        logger.info(f"Step {step_id} marked complete for {email}")
        
        # Return updated journey
        return jsonify({
            'message': 'Step completed successfully!',
            'journey': pathway_progress.to_dict(),
            'pathway': pathway_progress.to_dict(),  # Backward compatibility
            'completed_step': {
                'id': step.id,
                'name': step.step_name,
                'completed_at': completion.completed_at.isoformat()
            }
        }), 200
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error completing pathway step: {e}", exc_info=True)
        return jsonify({'error': 'Failed to complete step'}), 500


@app.route('/api/persons/<person_id>', methods=['PUT'])
@login_required
def update_person(person_id):
    """Update person details (admin only) - person_id can be PCO ID or email"""
    try:
        if not current_user.has_permission('query_access'):
            return jsonify({'error': 'Insufficient permissions'}), 403
        
        # Log which database we're using
        db_uri = app.config.get('SQLALCHEMY_DATABASE_URI', '')
        db_path = get_db_path()
        logger.info(f"PUT /api/persons/{person_id} - Using database: {db_uri}")
        logger.info(f"PUT /api/persons/{person_id} - Database path: {db_path}")
        
        # Force fresh query
        db.session.expire_all()
        
        # Try to find person by ID first (PCO ID like pco_33559749)
        person = Person.query.filter_by(id=person_id, is_active=True).first()
        
        # If not found and person_id looks like an email, try by email
        # This ensures both apps can update the same person
        if not person and '@' in person_id:
            logger.info(f"  Person not found by ID '{person_id}', trying by email")
            person = Person.query.filter(
                db.func.lower(Person.email) == person_id.lower(),
                Person.is_active == True
            ).first()
        
        if not person:
            logger.error(f"  Person not found by ID '{person_id}' or email")
            return jsonify({'error': 'Person not found'}), 404
        
        logger.info(f"  Found person: ID={person.id}, Email={person.email}, Name={person.full_name}")
        
        data = request.get_json()
        if not data:
            return jsonify({'error': 'No data provided'}), 400
        
        # Update basic information
        if 'full_name' in data:
            # full_name is required, so ensure it's not empty
            full_name_value = data['full_name'].strip() if data.get('full_name') else ''
            if not full_name_value:
                return jsonify({'error': 'Full name is required'}), 400
            person.full_name = full_name_value
        if 'preferred_name' in data:
            # Normalize preferred_name - convert empty string to None
            preferred_name_value = data['preferred_name'].strip() if data.get('preferred_name') else None
            person.preferred_name = preferred_name_value if preferred_name_value else None
        if 'email' in data:
            # Normalize email - convert empty string to None
            email_value = data['email'].strip() if data.get('email') else None
            email_value = email_value if email_value else None
            
            # Note: Multiple people can share the same email (e.g., family members, kids)
            # No uniqueness check performed
            
            person.email = email_value
        if 'campus' in data:
            # campus is required, so ensure it's not empty
            campus_value = data['campus'].strip() if data.get('campus') else ''
            if not campus_value or campus_value == 'all_campuses':
                return jsonify({'error': 'Campus is required'}), 400
            person.campus = campus_value
        if 'department' in data:
            # Normalize department - convert empty string to None and standardize case
            dept_value = data['department'].strip() if data.get('department') else None
            if dept_value:
                # Normalize department to standard format (Title Case for multi-word, capital for single)
                dept_value = dept_value.strip()
                # Handle standard department names
                dept_lower = dept_value.lower()
                if dept_lower == 'kids':
                    dept_value = 'Kids'
                elif dept_lower == 'youth':
                    dept_value = 'Youth'
                elif dept_lower in ['young adults', 'youngadults', 'young_adults']:
                    dept_value = 'Young Adults'
                elif dept_lower == 'families':
                    dept_value = 'Families'
                elif dept_lower == 'adults':
                    dept_value = 'Adults'
                elif dept_lower == 'seniors':
                    dept_value = 'Seniors'
                else:
                    # For other values, use Title Case
                    dept_value = dept_value.title()
            person.department = dept_value if dept_value else None
        if 'phone' in data:
            person.phone = data['phone'].strip() if data.get('phone') else None
        
        # Commit changes
        db.session.commit()
        logger.info(f"  Committed changes to database")
        
        # Refresh the person object to get updated data
        db.session.refresh(person)
        logger.info(f"  Person refreshed: {person.full_name}")
        
        if 'connect_group' in data:
            # Normalize connect_group - convert empty string to None
            connect_group_value = data['connect_group'].strip() if data.get('connect_group') else None
            old_connect_group = person.connect_group
            connect_group_just_assigned = not old_connect_group and connect_group_value  # Newly assigned (was None, now has value)
            person.connect_group = connect_group_value if connect_group_value else None
            
            # Auto-unmark logic: When assigned to connect group, unmark as new person/new Christian
            if connect_group_just_assigned and hasattr(person, 'is_new_person') and hasattr(person, 'is_new_christian'):
                if person.is_new_person:
                    logger.info(f"Auto-unmarking {person.id} as new person (assigned to connect group)")
                    person.is_new_person = False
                    person.new_person_date = None
                if person.is_new_christian:
                    logger.info(f"Auto-unmarking {person.id} as new Christian (assigned to connect group)")
                    person.is_new_christian = False
                    person.new_christian_date = None
            
            # Auto-complete the "Joined Connect Group" pathway step if person has a connect group assigned
            # Always check (regardless of old value) to ensure step is completed if person has a group
            if connect_group_value:  # Person has a connect group assigned
                try:
                    # Find active pathway progress for this person
                    active_progress = PersonPathwayProgress.query.filter_by(
                        person_id=person_id,
                        is_active=True
                    ).first()
                    
                    if active_progress:
                        # Find the "Joined Connect Group" step (milestone_type = "group_join")
                        connect_step = PathwayStep.query.filter_by(
                            pathway_id=active_progress.pathway_id,
                            milestone_type='group_join'
                        ).first()
                        
                        if connect_step:
                            # Check if already completed
                            existing_completion = PersonPathwayStepCompletion.query.filter_by(
                                person_pathway_progress_id=active_progress.id,
                                pathway_step_id=connect_step.id
                            ).first()
                            
                            if not existing_completion:
                                # Auto-complete the step
                                completion = PersonPathwayStepCompletion(
                                    person_pathway_progress_id=active_progress.id,
                                    pathway_step_id=connect_step.id,
                                    completed_by_person_id=getattr(current_user, 'id', None),
                                    completed_at=datetime.utcnow(),
                                    notes=f'Auto-completed when assigned to connect group: {connect_group_value}'
                                )
                                db.session.add(completion)
                                
                                # Update current step to next uncompleted step
                                next_step = active_progress.get_next_step()
                                active_progress.current_step_id = next_step.id if next_step else None
                                
                                # Mark as started if not already
                                if not active_progress.started_at:
                                    active_progress.started_at = datetime.utcnow()
                                
                                # Check if pathway is complete
                                if not next_step:
                                    active_progress.completed_at = datetime.utcnow()
                                
                                active_progress.updated_at = datetime.utcnow()
                                
                                logger.info(f"Auto-completed 'Joined Connect Group' step for person {person_id} with connect group: {connect_group_value}")
                                
                                # Flush to ensure completion is saved before committing
                                db.session.flush()
                                
                                # Commit pathway completion
                                db.session.commit()
                                
                                # Refresh to ensure latest data is available
                                db.session.refresh(active_progress)
                                _ = active_progress.step_completions.all()  # Force reload of relationship
                                
                                # Trigger Heartbeat recalculation since spiritual score may have changed
                                try:
                                    from heartbeat_engine import HeartbeatEngine
                                    engine = HeartbeatEngine()
                                    engine.calculate_heartbeat(person_id)
                                    logger.info(f"Recalculated Heartbeat for person {person_id} after auto-completing pathway step")
                                except Exception as hb_error:
                                    logger.warning(f"Failed to recalculate Heartbeat after auto-completing pathway step: {hb_error}")
                                    # Don't fail the request if recalculation fails
                    else:
                        logger.warning(f"No active pathway progress found for person {person_id} - cannot auto-complete connect group step")
                except Exception as pathway_error:
                    logger.warning(f"Error auto-completing pathway step when assigning connect group: {pathway_error}", exc_info=True)
                    db.session.rollback()
                    # Don't fail the person update if pathway step completion fails
        if 'dream_team_roles' in data:
            # Convert array to JSON string for storage
            try:
                person.dream_team_roles = json.dumps(data['dream_team_roles']) if data['dream_team_roles'] and len(data['dream_team_roles']) > 0 else None
            except (TypeError, ValueError) as e:
                logger.error(f"Error encoding dream_team_roles: {e}")
                person.dream_team_roles = None
        if 'tags' in data:
            # Convert array to JSON string for storage
            try:
                person.tags = json.dumps(data['tags']) if data['tags'] and len(data['tags']) > 0 else None
            except (TypeError, ValueError) as e:
                logger.error(f"Error encoding tags: {e}")
                person.tags = None
        if 'pastoral_notes' in data:
            # Normalize pastoral_notes - convert empty string to None
            notes_value = data['pastoral_notes'].strip() if data.get('pastoral_notes') else None
            person.pastoral_notes = notes_value if notes_value else None
        if 'phone' in data:
            # Normalize phone - convert empty string to None
            phone_value = data['phone'].strip() if data.get('phone') else None
            person.phone = phone_value if phone_value else None
        if 'birthday' in data:
            if data['birthday']:
                try:
                    person.birthday = datetime.strptime(data['birthday'], '%Y-%m-%d').date()
                except ValueError:
                    return jsonify({'error': 'Invalid birthday format'}), 400
            else:
                person.birthday = None
        
        # Update new people tracking fields
        if 'follow_up_status' in data:
            # Normalize follow_up_status - convert empty string to None
            status_value = data['follow_up_status'].strip() if data.get('follow_up_status') else None
            # Only set if column exists (use getattr to check safely)
            if hasattr(person, 'follow_up_status'):
                person.follow_up_status = status_value if status_value else None
        
        if 'service_attended' in data:
            # Normalize service_attended - convert empty string to None
            service_value = data['service_attended'].strip() if data.get('service_attended') else None
            if hasattr(person, 'service_attended'):
                person.service_attended = service_value if service_value else None
        
        if 'is_new_christian' in data:
            if hasattr(person, 'is_new_christian'):
                person.is_new_christian = bool(data['is_new_christian'])
        
        if 'new_christian_date' in data:
            if hasattr(person, 'new_christian_date'):
                value = data['new_christian_date']
                if value == '' or value is None:
                    person.new_christian_date = None
                else:
                    try:
                        if isinstance(value, str):
                            parsed_date = datetime.strptime(value, '%Y-%m-%d').date()
                            person.new_christian_date = parsed_date
                        else:
                            person.new_christian_date = value
                    except ValueError:
                        return jsonify({'error': 'Invalid date format for new_christian_date'}), 400
        
        # Update new person tracking fields
        if 'is_new_person' in data:
            if hasattr(person, 'is_new_person'):
                person.is_new_person = bool(data['is_new_person'])
        
        if 'new_person_date' in data:
            if hasattr(person, 'new_person_date'):
                value = data['new_person_date']
                if value == '' or value is None:
                    person.new_person_date = None
                else:
                    try:
                        if isinstance(value, str):
                            parsed_date = datetime.strptime(value, '%Y-%m-%d').date()
                            person.new_person_date = parsed_date
                        else:
                            person.new_person_date = value
                    except ValueError:
                        return jsonify({'error': 'Invalid date format for new_person_date'}), 400
        
        # Update discipleship milestones (convert empty strings to None)
        milestone_fields = [
            'dna_completed', 'baptised_on', 'rise_attended', 
            'filled_holy_spirit', 'first_served_on'
        ]
        
        # Track if baptism or first serving is being set for the first time
        baptised_just_set = False
        first_served_just_set = False
        
        for field in milestone_fields:
            if field in data:
                value = data[field]
                old_value = getattr(person, field, None)
                if value == '' or value is None:
                    setattr(person, field, None)
                else:
                    # Try to parse the date
                    try:
                        if isinstance(value, str):
                            # Parse date string
                            parsed_date = datetime.strptime(value, '%Y-%m-%d').date()
                            setattr(person, field, parsed_date)
                            # Check if this is a new milestone (was None, now has a date)
                            if field == 'baptised_on' and old_value is None:
                                baptised_just_set = True
                            elif field == 'first_served_on' and old_value is None:
                                first_served_just_set = True
                        else:
                            setattr(person, field, value)
                            # Check if this is a new milestone
                            if field == 'baptised_on' and old_value is None:
                                baptised_just_set = True
                            elif field == 'first_served_on' and old_value is None:
                                first_served_just_set = True
                    except ValueError:
                        return jsonify({'error': f'Invalid date format for {field}'}), 400
        
        # Auto-unmark logic: When milestones are reached, automatically unmark
        if hasattr(person, 'is_new_christian') and hasattr(person, 'is_new_person'):
            # If someone gets baptized, they're no longer a "new Christian" (they've progressed)
            if baptised_just_set and person.is_new_christian:
                logger.info(f"Auto-unmarking {person.id} as new Christian (baptized)")
                person.is_new_christian = False
                person.new_christian_date = None
            
            # If someone starts serving, they're no longer a "new person" (they're engaged)
            if first_served_just_set and person.is_new_person:
                logger.info(f"Auto-unmarking {person.id} as new person (started serving)")
                person.is_new_person = False
                person.new_person_date = None
        
        # Update engagement profile pulse status if attendance/serving changed
        # (Pulse will be recalculated automatically on next access)
        
        # Commit changes
        db.session.commit()
        
        # Expire all to force fresh queries
        db.session.expire_all()
        
        # Re-query to get absolutely fresh data - but avoid loading engagement_profile relationship
        # to prevent schema mismatch errors
        person = Person.query.filter_by(id=person_id, is_active=True).first()
        if not person:
            return jsonify({'error': 'Person not found after update'}), 404
        
        # Refresh person without loading relationships
        db.session.refresh(person)
        
        # Return updated person data
        person_data = person.to_dict()
        
        # Try to get engagement data using raw SQL to avoid schema issues
        try:
            from sqlalchemy import text
            engagement_row = db.session.execute(
                text("""
                    SELECT pulse_status, last_seen, attendance_frequency, serving_frequency, 
                           overall_engagement, attendance_log, serving_log
                    FROM engagement_profiles 
                    WHERE person_id = :person_id
                """),
                {'person_id': person.id}
            ).fetchone()
            
            if engagement_row:
                pulse_status = engagement_row[0] or 'red'
                # Handle last_seen - might be date object or string
                last_seen_raw = engagement_row[1]
                if last_seen_raw:
                    if isinstance(last_seen_raw, str):
                        # Already a string, might be ISO format or SQLite format
                        try:
                            if 'T' in last_seen_raw or len(last_seen_raw) == 10:
                                last_seen = last_seen_raw
                            else:
                                # SQLite format like '2025-12-17 00:00:00.000000'
                                dt = datetime.fromisoformat(last_seen_raw.replace(' ', 'T').split('.')[0])
                                last_seen = dt.isoformat()
                        except:
                            last_seen = last_seen_raw  # Use as-is if parsing fails
                    elif hasattr(last_seen_raw, 'isoformat'):
                        last_seen = last_seen_raw.isoformat()
                    else:
                        last_seen = str(last_seen_raw)
                else:
                    last_seen = None
                attendance_frequency = float(engagement_row[2] or 0.0)
                serving_frequency = float(engagement_row[3] or 0.0)
                overall_engagement = float(engagement_row[4] or 0.0)
                
                person_data['engagement'] = {
                    'pulse_status': pulse_status,
                    'last_seen': last_seen,
                    'attendance_frequency': attendance_frequency,
                    'serving_frequency': serving_frequency,
                    'overall_engagement': overall_engagement
                }
        except Exception as e:
            logger.warning(f"Error fetching engagement profile for {person.id}: {e}")
            person_data['engagement'] = None
        
        response = jsonify({
            'message': 'Person updated successfully',
            'person': person_data
        })
        
        # Add cache-control headers to prevent caching
        response.headers['Cache-Control'] = 'no-cache, no-store, must-revalidate'
        response.headers['Pragma'] = 'no-cache'
        response.headers['Expires'] = '0'
        
        return response
        
    except Exception as e:
        db.session.rollback()
        import traceback
        error_traceback = traceback.format_exc()
        logger.error(f"Error updating person {person_id}: {e}\n{error_traceback}")
        return jsonify({'error': f'Failed to update person: {str(e)}'}), 500


@app.route('/api/persons/<person_id>/archive', methods=['POST'])
@login_required
def archive_person(person_id):
    """Archive a person (soft delete - sets is_active to False)"""
    try:
        if not current_user.has_permission('query_access'):
            return jsonify({'error': 'Insufficient permissions'}), 403
        
        # Check if person exists using raw SQL to avoid column issues
        from sqlalchemy import text
        from sqlalchemy.exc import OperationalError
        
        # First, check if the person exists
        try:
            result = db.session.execute(
                text("SELECT id FROM persons WHERE id = :person_id"),
                {'person_id': person_id}
            ).first()
            
            if not result:
                return jsonify({'error': 'Person not found'}), 404
            
            # Update using raw SQL to avoid column issues
            db.session.execute(
                text("UPDATE persons SET is_active = 0 WHERE id = :person_id"),
                {'person_id': person_id}
            )
            db.session.commit()
            
            # Fetch the updated person using raw SQL to build response
            person_row = db.session.execute(
                text("SELECT id, full_name, preferred_name, email, phone, campus, department, is_active FROM persons WHERE id = :person_id"),
                {'person_id': person_id}
            ).first()
            
            if person_row:
                person_dict = {
                    'id': person_row[0],
                    'full_name': person_row[1],
                    'preferred_name': person_row[2],
                    'email': person_row[3],
                    'phone': person_row[4],
                    'campus': person_row[5],
                    'department': person_row[6],
                    'is_active': bool(person_row[7])
                }
            else:
                person_dict = {'id': person_id, 'is_active': False}
            
            logger.info(f"Person {person_id} archived by user {current_user.id}")
            return jsonify({
                'message': 'Person archived successfully',
                'person': person_dict
            })
            
        except OperationalError as e:
            error_str = str(e).lower()
            if 'no such column' in error_str or 'no such table' in error_str:
                logger.warning(f"Database schema issue when archiving person: {e}")
                # Fallback: try simple update without column checks
                db.session.execute(
                    text("UPDATE persons SET is_active = 0 WHERE id = :person_id"),
                    {'person_id': person_id}
                )
                db.session.commit()
                return jsonify({
                    'message': 'Person archived successfully',
                    'person': {'id': person_id, 'is_active': False}
                })
            else:
                raise
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error archiving person {person_id}: {e}", exc_info=True)
        return jsonify({'error': f'Failed to archive person: {str(e)}'}), 500


