@app.route('/api/connect-groups', methods=['GET'])
def get_connect_groups():
    """Get list of connect groups (campus-scoped) - public endpoint for mobile app"""
    try:
        campus_filter = request.args.get('campus', None)
        is_active = request.args.get('is_active', 'true').lower() == 'true'
        
        # Build query
        query = ConnectGroup.query
        
        # Apply campus scoping if user is logged in (optional for mobile app)
        try:
            if hasattr(current_user, 'is_authenticated') and current_user.is_authenticated:
                try:
                    if not current_user.has_permission('groups', 'view'):
                        return jsonify({'error': 'Insufficient permissions'}), 403
                except AttributeError:
                    # User object doesn't have has_permission, skip permission check
                    pass
                
                # Apply campus scoping
                try:
                    from utils.campus_scope import apply_campus_filter
                    query = apply_campus_filter(query, 'groups')
                except Exception as filter_error:
                    logger.warning(f"Campus filter failed: {filter_error}")
        except Exception as scope_error:
            # If scoping fails, just continue without it (for mobile app access)
            logger.warning(f"Campus scoping failed: {scope_error}")
        
        if campus_filter and campus_filter != 'all_campuses':
            query = query.filter(ConnectGroup.campus == campus_filter)
        
        if is_active:
            query = query.filter(ConnectGroup.is_active == True)
        
        groups = query.order_by(ConnectGroup.name).all()
        
        # Convert to dicts safely
        groups_data = []
        for g in groups:
            try:
                groups_data.append(g.to_dict())
            except Exception as e:
                logger.warning(f"Error serializing group {g.id}: {e}")
                # Include basic info even if to_dict fails
                groups_data.append({
                    'id': getattr(g, 'id', ''),
                    'name': getattr(g, 'name', ''),
                    'campus': getattr(g, 'campus', ''),
                })
        
        return jsonify({
            'groups': groups_data,
            'total': len(groups_data)
        })
        
    except Exception as e:
        logger.error(f"Error fetching connect groups: {e}", exc_info=True)
        # Return empty array instead of 500 error for mobile app
        return jsonify({'groups': [], 'total': 0}), 200


@app.route('/api/connect-groups', methods=['POST'])
@login_required
def create_connect_group():
    """Create new connect group"""
    try:
        if not current_user.has_permission('groups', 'create'):
            return jsonify({'error': 'Insufficient permissions'}), 403
        
        data = request.get_json()
        
        # Validate required fields
        required_fields = ['name', 'campus', 'leader_id']
        for field in required_fields:
            if not data.get(field):
                return jsonify({'error': f'Missing required field: {field}'}), 400
        
        # Generate group ID
        import uuid
        group_id = f"cg_{data['campus'].lower().replace(' ', '_')}_{str(uuid.uuid4())[:8]}"
        
        # Verify leader exists
        leader = Person.query.filter_by(id=data['leader_id'], is_active=True).first()
        if not leader:
            return jsonify({'error': 'Leader not found'}), 404
        
        # Handle leader_emails (JSON array of additional leader emails)
        leader_emails_json = None
        if data.get('leader_emails'):
            if isinstance(data['leader_emails'], list):
                leader_emails_json = json.dumps(data['leader_emails'])
            else:
                leader_emails_json = data['leader_emails']
        
        # Create group
        group = ConnectGroup(
            id=group_id,
            name=data['name'],
            campus=data['campus'],
            leader_id=data['leader_id'],
            co_leader_id=data.get('co_leader_id'),
            meeting_day=data.get('meeting_day'),
            meeting_time=data.get('meeting_time'),
            meeting_frequency=data.get('meeting_frequency', 'weekly'),
            location=data.get('location'),
            leader_access_code=data.get('leader_access_code'),  # Simple password for leader portal
            leader_emails=leader_emails_json  # Additional leader emails
        )
        
        db.session.add(group)
        db.session.commit()
        
        return jsonify({
            'message': 'Connect group created successfully',
            'group': group.to_dict()
        }), 201
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error creating connect group: {e}")
        return jsonify({'error': 'Failed to create connect group'}), 500


@app.route('/api/connect-groups/my-groups', methods=['GET'])
def get_my_groups():
    """Get connect groups for a person by email - public endpoint for mobile app"""
    try:
        email = request.args.get('email', '').strip()
        if not email:
            return jsonify({'error': 'Email parameter required'}), 400
        
        # Find person by email (case-insensitive)
        person = Person.query.filter(
            db.func.lower(Person.email) == email.lower(),
            Person.is_active == True
        ).first()
        
        if not person:
            return jsonify({'groups': [], 'total': 0}), 200
        
        groups_data = []
        
        # Check if person has a connect_group assigned (from Pulse)
        # Note: Pulse stores the group NAME, not ID, so we match by name
        if person.connect_group:
            try:
                # Use raw SQL query to avoid SQLAlchemy loading columns that don't exist
                from sqlalchemy import text
                
                # First try by ID (in case it is an ID)
                group_result = db.session.execute(
                    text("SELECT id, name, campus FROM connect_groups WHERE id = :group_id AND is_active = 1"),
                    {'group_id': person.connect_group}
                ).fetchone()
                
                # If not found by ID, try by name (Pulse stores names like "Roma and Yuvi" or "Roma & Yuvi")
                if not group_result:
                    group_name = person.connect_group.strip()
                    group_result = db.session.execute(
                        text("SELECT id, name, campus FROM connect_groups WHERE LOWER(name) = LOWER(:group_name) AND is_active = 1"),
                        {'group_name': group_name}
                    ).fetchone()
                
                # Also try with "&" instead of "and" (variations)
                if not group_result:
                    group_name_variant = group_name.replace(' and ', ' & ').replace(' And ', ' & ')
                    if group_name_variant != group_name:
                        group_result = db.session.execute(
                            text("SELECT id, name, campus FROM connect_groups WHERE LOWER(name) = LOWER(:group_name) AND is_active = 1"),
                            {'group_name': group_name_variant}
                        ).fetchone()
                
                # Try partial match (in case name is slightly different)
                if not group_result and group_name:
                    first_word = group_name.split()[0] if group_name else ''
                    if first_word:
                        group_result = db.session.execute(
                            text("SELECT id, name, campus FROM connect_groups WHERE LOWER(name) LIKE LOWER(:search) AND is_active = 1 LIMIT 1"),
                            {'search': f"%{first_word}%"}
                        ).fetchone()
                
                if group_result:
                    # Get full group object (but handle to_dict() errors gracefully)
                    group = ConnectGroup.query.filter_by(id=group_result[0]).first()
                else:
                    group = None
                
                if group:
                    try:
                        group_dict = group.to_dict()
                        # Add member count
                        try:
                            group_dict['member_count'] = group.get_member_count()
                        except:
                            group_dict['member_count'] = 0
                        groups_data.append(group_dict)
                    except Exception as e:
                        logger.warning(f"Error serializing group {group.id}: {e}")
                        # Include basic info
                        groups_data.append({
                            'id': group.id,
                            'name': group.name,
                            'campus': group.campus,
                        })
            except Exception as e:
                logger.warning(f"Error fetching assigned group {person.connect_group}: {e}")
        
        # Also check if person is a leader or co-leader (use raw SQL to avoid column issues)
        try:
            from sqlalchemy import text
            
            # Check as leader using raw SQL
            led_groups_result = db.session.execute(
                text("SELECT id FROM connect_groups WHERE leader_id = :person_id AND is_active = 1"),
                {'person_id': person.id}
            ).fetchall()
            
            for row in led_groups_result:
                group_id = row[0]
                if group_id not in [g.get('id') for g in groups_data]:
                    group = ConnectGroup.query.filter_by(id=group_id).first()
                    if group:
                        try:
                            group_dict = group.to_dict()
                            try:
                                group_dict['member_count'] = group.get_member_count()
                            except:
                                group_dict['member_count'] = 0
                            group_dict['role'] = 'leader'
                            groups_data.append(group_dict)
                        except Exception as e:
                            logger.warning(f"Error serializing leader group {group.id}: {e}")
                            groups_data.append({
                                'id': group.id,
                                'name': group.name,
                                'campus': group.campus,
                                'role': 'leader',
                            })
            
            # Check as co-leader using raw SQL
            co_led_groups_result = db.session.execute(
                text("SELECT id FROM connect_groups WHERE co_leader_id = :person_id AND is_active = 1"),
                {'person_id': person.id}
            ).fetchall()
            
            for row in co_led_groups_result:
                group_id = row[0]
                if group_id not in [g.get('id') for g in groups_data]:
                    group = ConnectGroup.query.filter_by(id=group_id).first()
                    if group:
                        try:
                            group_dict = group.to_dict()
                            try:
                                group_dict['member_count'] = group.get_member_count()
                            except:
                                group_dict['member_count'] = 0
                            group_dict['role'] = 'co_leader'
                            groups_data.append(group_dict)
                        except Exception as e:
                            logger.warning(f"Error serializing co-leader group {group.id}: {e}")
                            groups_data.append({
                                'id': group.id,
                                'name': group.name,
                                'campus': group.campus,
                                'role': 'co_leader',
                            })
        except Exception as e:
            logger.warning(f"Error checking leadership groups: {e}")
        
        return jsonify({
            'groups': groups_data,
            'total': len(groups_data)
        })
        
    except Exception as e:
        logger.error(f"Error fetching my groups for email {email}: {e}", exc_info=True)
        # Return empty array instead of 500 error for mobile app
        return jsonify({'groups': [], 'total': 0}), 200


@app.route('/api/connect-groups/<group_id>', methods=['GET'])
def get_connect_group(group_id):
    """Get connect group details with members (allows leader access via email + access code)"""
    try:
        group = ConnectGroup.query.filter_by(id=group_id).first()
        if not group:
            return jsonify({'error': 'Connect group not found'}), 404
        
        # Check permissions - either logged-in admin/staff OR leader via email + access code
        is_leader = False
        is_authenticated_user = False
        
        # Check if user is logged in
        try:
            if current_user and hasattr(current_user, 'email'):
                all_leader_emails = group.get_leader_emails()
                is_leader = current_user.email.lower() in all_leader_emails
                is_authenticated_user = current_user.has_permission('groups', 'view')
        except:
            pass  # Not logged in, check email + access code
        
        # If not authenticated user, check email + access code
        if not is_authenticated_user and not is_leader:
            all_leader_emails = group.get_leader_emails()
            provided_email = request.args.get('leader_email', '').lower()
            provided_code = request.args.get('access_code', '')
            
            if provided_email and provided_email in all_leader_emails:
                # Verify access code if set
                if group.leader_access_code:
                    if provided_code != group.leader_access_code:
                        return jsonify({'error': 'Invalid access code'}), 403
                is_leader = True
            else:
                # If no email provided or not a leader, require login
                try:
                    if not (current_user and hasattr(current_user, 'has_permission')):
                        return jsonify({'error': 'Authentication required'}), 401
                    if not current_user.has_permission('groups', 'view'):
                        return jsonify({'error': 'Insufficient permissions'}), 403
                    is_authenticated_user = True
                except:
                    return jsonify({'error': 'Authentication required'}), 401
        
        if not (is_authenticated_user or is_leader):
            return jsonify({'error': 'Insufficient permissions'}), 403
        
        # Get members
        members = group.get_members()
        logger.info(f"get_connect_group - Group {group_id} ({group.name}): Found {len(members)} members via get_members()")
        
        # Get meetings (sorted by date, most recent first)
        meetings = ConnectGroupMeeting.query.filter_by(group_id=group_id).order_by(ConnectGroupMeeting.meeting_date.desc()).all()
        
        group_data = group.to_dict()
        group_data['members'] = [m.to_dict() for m in members]
        group_data['meetings'] = [m.to_dict() for m in meetings]
        
        return jsonify(group_data)
        
    except Exception as e:
        logger.error(f"Error fetching connect group: {e}", exc_info=True)
        return jsonify({'error': 'Failed to fetch connect group'}), 500


@app.route('/api/connect-groups/<group_id>', methods=['PUT'])
@login_required
def update_connect_group(group_id):
    """Update connect group"""
    try:
        if not current_user.has_permission('groups', 'edit'):
            return jsonify({'error': 'Insufficient permissions'}), 403
        
        group = ConnectGroup.query.filter_by(id=group_id).first()
        if not group:
            return jsonify({'error': 'Connect group not found'}), 404
        
        data = request.get_json()
        
        # Update fields
        if 'name' in data:
            group.name = data['name']
        if 'leader_id' in data:
            leader = Person.query.filter_by(id=data['leader_id'], is_active=True).first()
            if not leader:
                return jsonify({'error': 'Leader not found'}), 404
            group.leader_id = data['leader_id']
        if 'co_leader_id' in data:
            if data['co_leader_id']:
                co_leader = Person.query.filter_by(id=data['co_leader_id'], is_active=True).first()
                if not co_leader:
                    return jsonify({'error': 'Co-leader not found'}), 404
            group.co_leader_id = data['co_leader_id']
        if 'meeting_day' in data:
            group.meeting_day = data['meeting_day']
        if 'meeting_time' in data:
            group.meeting_time = data['meeting_time']
        if 'meeting_frequency' in data:
            group.meeting_frequency = data['meeting_frequency']
        if 'location' in data:
            group.location = data['location']
        if 'leader_access_code' in data:
            group.leader_access_code = data['leader_access_code']
        if 'leader_emails' in data:
            if isinstance(data['leader_emails'], list):
                group.leader_emails = json.dumps(data['leader_emails'])
            elif data['leader_emails'] is None:
                group.leader_emails = None
            else:
                group.leader_emails = data['leader_emails']
        if 'is_active' in data:
            group.is_active = data['is_active']
        
        group.updated_at = datetime.utcnow()
        db.session.commit()
        
        return jsonify({
            'message': 'Connect group updated successfully',
            'group': group.to_dict()
        })
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error updating connect group: {e}")
        return jsonify({'error': 'Failed to update connect group'}), 500


