def create_group_meeting(group_id):
    """Create a connect group meeting (allows leader access via email + access code)"""
    try:
        group = ConnectGroup.query.filter_by(id=group_id).first()
        if not group:
            return jsonify({'error': 'Connect group not found'}), 404
        
        data = request.get_json()
        
        # Check permissions - either logged-in admin/staff OR leader via email + access code
        is_leader = False
        is_authenticated_user = False
        
        # Check if user is logged in
        try:
            if current_user and hasattr(current_user, 'email'):
                all_leader_emails = group.get_leader_emails()
                is_leader = current_user.email.lower() in all_leader_emails
                is_authenticated_user = current_user.has_permission('groups', 'edit')
        except:
            pass  # Not logged in, check email + access code
        
        # If not authenticated user, check email + access code
        if not is_authenticated_user and not is_leader:
            all_leader_emails = group.get_leader_emails()
            provided_email = data.get('leader_email', '').lower()
            provided_code = data.get('access_code', '')
            
            if provided_email and provided_email in all_leader_emails:
                # Verify access code if set
                if group.leader_access_code:
                    if provided_code != group.leader_access_code:
                        return jsonify({'error': 'Invalid access code'}), 403
                is_leader = True
            else:
                return jsonify({'error': 'Insufficient permissions'}), 403
        
        if not (is_authenticated_user or is_leader):
            return jsonify({'error': 'Insufficient permissions'}), 403
        
        # Parse meeting date
        meeting_date = datetime.now().date()
        if data.get('meeting_date'):
            try:
                meeting_date = datetime.fromisoformat(data['meeting_date']).date()
            except (ValueError, AttributeError):
                try:
                    meeting_date = datetime.strptime(data['meeting_date'], '%Y-%m-%d').date()
                except ValueError:
                    return jsonify({'error': 'Invalid date format. Use YYYY-MM-DD'}), 400
        
        # Create meeting
        meeting = ConnectGroupMeeting(
            group_id=group_id,
            meeting_date=meeting_date,
            notes=data.get('notes')
        )
        
        db.session.add(meeting)
        db.session.flush()  # Get meeting ID
        
        # Create attendance records for all group members
        members = group.get_members()
        for member in members:
            attendance = ConnectGroupAttendance(
                meeting_id=meeting.id,
                person_id=member.id,
                present=False  # Default to absent, leader will mark present
            )
            db.session.add(attendance)
        
        db.session.commit()
        
        return jsonify({
            'message': 'Meeting created successfully',
            'meeting': meeting.to_dict()
        }), 201
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error creating group meeting: {e}")
        return jsonify({'error': 'Failed to create meeting'}), 500


@app.route('/api/connect-groups/health', methods=['GET'])
@login_required
def get_connect_groups_health():
    """Get connect groups health/attendance data for the last 3 months"""
    try:
        if not current_user.has_permission('groups', 'view'):
            return jsonify({'error': 'Insufficient permissions'}), 403
        
        from models import ConnectAttendance, HeartbeatConnectGroup
        from datetime import date, timedelta
        from collections import defaultdict
        
        # Get date range (last 3 months)
        end_date = date.today()
        start_date = end_date - timedelta(days=90)
        
        # Get all connect attendance records in the date range
        attendance_records = ConnectAttendance.query.filter(
            ConnectAttendance.date >= start_date,
            ConnectAttendance.date <= end_date
        ).all()
        
        # Group by date and status
        daily_stats = defaultdict(lambda: {'present': 0, 'absent': 0, 'total': 0})
        
        for record in attendance_records:
            date_key = record.date.isoformat()
            if record.status == 'present':
                daily_stats[date_key]['present'] += 1
            elif record.status == 'absent':
                daily_stats[date_key]['absent'] += 1
            daily_stats[date_key]['total'] += 1
        
        # Convert to list sorted by date
        attendance_data = []
        current_date = start_date
        while current_date <= end_date:
            date_key = current_date.isoformat()
            stats = daily_stats.get(date_key, {'present': 0, 'absent': 0, 'total': 0})
            attendance_data.append({
                'date': date_key,
                'present': stats['present'],
                'absent': stats['absent'],
                'total': stats['total'],
                'attendance_rate': (stats['present'] / stats['total'] * 100) if stats['total'] > 0 else 0
            })
            current_date += timedelta(days=1)
        
        # Get group-level stats
        group_stats = []
        groups = HeartbeatConnectGroup.query.filter_by(is_active=True).all()
        
        for group in groups:
            group_attendance = ConnectAttendance.query.filter(
                ConnectAttendance.connect_group_id == group.id,
                ConnectAttendance.date >= start_date,
                ConnectAttendance.date <= end_date
            ).all()
            
            present_count = len([a for a in group_attendance if a.status == 'present'])
            absent_count = len([a for a in group_attendance if a.status == 'absent'])
            total_count = present_count + absent_count
            
            group_stats.append({
                'group_id': group.id,
                'group_name': group.name,
                'campus': group.campus.name if group.campus else None,
                'present': present_count,
                'absent': absent_count,
                'total': total_count,
                'attendance_rate': (present_count / total_count * 100) if total_count > 0 else 0
            })
        
        # Sort groups by attendance rate (lowest first to highlight issues)
        group_stats.sort(key=lambda x: x['attendance_rate'])
        
        return jsonify({
            'date_range': {
                'start': start_date.isoformat(),
                'end': end_date.isoformat()
            },
            'daily_attendance': attendance_data,
            'group_stats': group_stats,
            'summary': {
                'total_meetings': len([d for d in attendance_data if d['total'] > 0]),
                'total_present': sum(d['present'] for d in attendance_data),
                'total_absent': sum(d['absent'] for d in attendance_data),
                'overall_attendance_rate': (
                    sum(d['present'] for d in attendance_data) / 
                    sum(d['total'] for d in attendance_data) * 100
                ) if sum(d['total'] for d in attendance_data) > 0 else 0
            }
        }), 200
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error getting connect groups health: {e}", exc_info=True)
        return jsonify({'error': 'Failed to get connect groups health data'}), 500


@app.route('/api/connect-groups/<group_id>/health', methods=['GET'])
@login_required
def get_connect_group_health(group_id):
    """Get health data for a specific connect group (average heartbeat + attendance chart)"""
    try:
        if not current_user.has_permission('groups', 'view'):
            return jsonify({'error': 'Insufficient permissions'}), 403
        
        from models import ConnectAttendance, HeartbeatConnectGroup, HeartbeatSnapshot
        from datetime import date, timedelta
        from collections import defaultdict
        
        # Get the connect group
        try:
            group = ConnectGroup.query.filter_by(id=group_id).first()
            if not group:
                return jsonify({'error': 'Connect group not found'}), 404
        except Exception as e:
            logger.error(f"Error querying ConnectGroup {group_id}: {e}", exc_info=True)
            return jsonify({'error': f'Failed to load connect group: {str(e)}'}), 500
        
        # Get all members (including leaders)
        try:
            members = group.get_members() if hasattr(group, 'get_members') else []
        except Exception as e:
            logger.warning(f"Error getting members for group {group_id}: {e}")
            members = []
        
        leader_ids = []
        try:
            if hasattr(group, 'leader_id') and group.leader_id:
                leader_ids.append(group.leader_id)
            if hasattr(group, 'co_leader_id') and group.co_leader_id:
                leader_ids.append(group.co_leader_id)
        except Exception as e:
            logger.warning(f"Error getting leader IDs for group {group_id}: {e}")
        
        # Get all person IDs (members + leaders)
        try:
            all_person_ids = [m.id for m in members if hasattr(m, 'id')] + leader_ids
            all_person_ids = list(set(all_person_ids))  # Remove duplicates
        except Exception as e:
            logger.warning(f"Error processing person IDs for group {group_id}: {e}")
            all_person_ids = []
        
        # Calculate average heartbeat for all members and leaders
        heartbeat_scores = []
        heartbeat_data = {
            'average_total_score': 0,
            'average_engagement_score': 0,
            'average_gather_score': 0,
            'average_spiritual_score': 0,
            'average_care_score': 0,
            'member_count': 0,
            'status_breakdown': {}
        }
        
        try:
            for person_id in all_person_ids:
                try:
                    snapshot = HeartbeatSnapshot.query.filter_by(
                        person_id=person_id
                    ).order_by(HeartbeatSnapshot.calculated_at.desc()).first()
                    
                    if snapshot:
                        heartbeat_scores.append({
                            'person_id': person_id,
                            'total_score': snapshot.total_score or 0,
                            'engagement_score': snapshot.engagement_score or 0,
                            'gather_score': snapshot.gather_score or 0,
                            'spiritual_score': snapshot.spiritual_score or 0,
                            'care_score': snapshot.care_score or 0,
                            'status': snapshot.status or 'unknown'
                        })
                        # Track status breakdown
                        status = snapshot.status or 'unknown'
                        heartbeat_data['status_breakdown'][status] = heartbeat_data['status_breakdown'].get(status, 0) + 1
                except Exception as e:
                    logger.warning(f"Error getting heartbeat for person {person_id}: {e}")
                    continue
            
            if heartbeat_scores:
                heartbeat_data['average_total_score'] = sum(s['total_score'] for s in heartbeat_scores) / len(heartbeat_scores)
                heartbeat_data['average_engagement_score'] = sum(s['engagement_score'] for s in heartbeat_scores) / len(heartbeat_scores)
                heartbeat_data['average_gather_score'] = sum(s['gather_score'] for s in heartbeat_scores) / len(heartbeat_scores)
                heartbeat_data['average_spiritual_score'] = sum(s['spiritual_score'] for s in heartbeat_scores) / len(heartbeat_scores)
                heartbeat_data['average_care_score'] = sum(s['care_score'] for s in heartbeat_scores) / len(heartbeat_scores)
                heartbeat_data['member_count'] = len(heartbeat_scores)
        except Exception as e:
            logger.error(f"Error calculating heartbeat data for group {group_id}: {e}", exc_info=True)
            # Continue with empty heartbeat data
        
        # Get the HeartbeatConnectGroup to match attendance records
        heartbeat_group = None
        try:
            group_name = getattr(group, 'name', '')
            group_campus = getattr(group, 'campus', '')
            if group_name and group_campus:
                heartbeat_group = HeartbeatConnectGroup.query.filter_by(
                    name=group_name,
                    campus_id=group_campus
                ).first()
            
            # If not found by name, try to find by leader
            if not heartbeat_group and hasattr(group, 'leader_id') and group.leader_id:
                heartbeat_group = HeartbeatConnectGroup.query.filter_by(
                    leader_id=group.leader_id
                ).first()
        except Exception as e:
            logger.warning(f"Error finding HeartbeatConnectGroup for group {group_id}: {e}")
        
        # Get date range (last 3 months)
        try:
            end_date = date.today()
            start_date = end_date - timedelta(days=90)
        except Exception as e:
            logger.error(f"Error calculating date range: {e}")
            end_date = date.today()
            start_date = end_date - timedelta(days=90)
        
        # Get attendance records for this specific group
        attendance_records = []
        try:
            if heartbeat_group and hasattr(heartbeat_group, 'id'):
                attendance_records = ConnectAttendance.query.filter(
                    ConnectAttendance.connect_group_id == heartbeat_group.id,
                    ConnectAttendance.date >= start_date,
                    ConnectAttendance.date <= end_date
                ).all()
            elif all_person_ids:
                # Fallback: try to match by person IDs if we can't find the heartbeat group
                # This handles cases where the group exists but hasn't been synced to HeartbeatConnectGroup
                attendance_records = ConnectAttendance.query.filter(
                    ConnectAttendance.person_id.in_(all_person_ids),
                    ConnectAttendance.date >= start_date,
                    ConnectAttendance.date <= end_date
                ).all()
        except Exception as e:
            logger.error(f"Error querying attendance records for group {group_id}: {e}", exc_info=True)
            attendance_records = []
        
        # Group by date and status
        daily_stats = defaultdict(lambda: {'present': 0, 'absent': 0, 'total': 0})
        
        try:
            for record in attendance_records:
                try:
                    if not hasattr(record, 'date') or not record.date:
                        continue
                    date_key = record.date.isoformat() if hasattr(record.date, 'isoformat') else str(record.date)
                    status = getattr(record, 'status', None)
                    if status == 'present':
                        daily_stats[date_key]['present'] += 1
                    elif status == 'absent':
                        daily_stats[date_key]['absent'] += 1
                    daily_stats[date_key]['total'] += 1
                except Exception as e:
                    logger.warning(f"Error processing attendance record: {e}")
                    continue
        except Exception as e:
            logger.error(f"Error processing attendance records: {e}", exc_info=True)
        
        # Convert to list sorted by date
        attendance_data = []
        try:
            current_date = start_date
            while current_date <= end_date:
                try:
                    date_key = current_date.isoformat() if hasattr(current_date, 'isoformat') else str(current_date)
                    stats = daily_stats.get(date_key, {'present': 0, 'absent': 0, 'total': 0})
                    attendance_data.append({
                        'date': date_key,
                        'present': stats.get('present', 0),
                        'absent': stats.get('absent', 0),
                        'total': stats.get('total', 0),
                        'attendance_rate': (stats.get('present', 0) / stats.get('total', 1) * 100) if stats.get('total', 0) > 0 else 0
                    })
                    current_date += timedelta(days=1)
                except Exception as e:
                    logger.warning(f"Error processing date {current_date}: {e}")
                    current_date += timedelta(days=1)
        except Exception as e:
            logger.error(f"Error building attendance_data: {e}", exc_info=True)
            attendance_data = []
        
        # Calculate summary stats
        try:
            total_meetings = len([d for d in attendance_data if d.get('total', 0) > 0])
            total_present = sum(d.get('present', 0) for d in attendance_data)
            total_absent = sum(d.get('absent', 0) for d in attendance_data)
            total_attendance = total_present + total_absent
        except Exception as e:
            logger.error(f"Error calculating summary stats: {e}", exc_info=True)
            total_meetings = 0
            total_present = 0
            total_absent = 0
            total_attendance = 0
        
        # Build detailed attendance breakdown (wrap in try-catch to not fail entire endpoint)
        detailed_attendance = []
        try:
            # Get all group members with their info (including leaders)
            all_members_dict = {}
            for member in members:
                all_members_dict[member.id] = {
                    'person_id': member.id,
                    'person_name': member.full_name
                }
            # Add leaders
            for leader_id in leader_ids:
                if leader_id and leader_id not in all_members_dict:
                    leader = Person.query.get(leader_id)
                    if leader:
                        all_members_dict[leader_id] = {
                            'person_id': leader_id,
                            'person_name': leader.full_name
                        }
            
            # Get all meetings for this group (from ConnectGroupMeeting)
            try:
                all_meetings = ConnectGroupMeeting.query.filter_by(
                    group_id=group_id
                ).filter(
                    ConnectGroupMeeting.meeting_date >= start_date,
                    ConnectGroupMeeting.meeting_date <= end_date
                ).order_by(ConnectGroupMeeting.meeting_date.desc()).all()
            except Exception as e:
                logger.warning(f"Error querying ConnectGroupMeeting for group {group_id}: {e}")
                all_meetings = []
            
            # Build a map of attendance by date and person
            attendance_by_date_person = defaultdict(dict)  # {date: {person_id: status}}
            
            for record in attendance_records:
                try:
                    if not record.date:
                        continue
                    date_key = record.date.isoformat() if hasattr(record.date, 'isoformat') else str(record.date)
                    attendance_by_date_person[date_key][record.person_id] = record.status
                except Exception as e:
                    logger.warning(f"Error processing attendance record {record.id if hasattr(record, 'id') else 'unknown'}: {e}")
                    continue
            
            # Process all meetings
            for meeting in all_meetings:
                if not meeting or not meeting.meeting_date:
                    continue
                    
                try:
                    # Handle both date objects and strings
                    if isinstance(meeting.meeting_date, str):
                        from datetime import datetime
                        meeting_date = datetime.strptime(meeting.meeting_date, '%Y-%m-%d').date()
                    else:
                        meeting_date = meeting.meeting_date
                    
                    date_key = meeting_date.isoformat()
                    present_list = []
                    absent_list = []
                    
                    # Check each member's attendance status
                    for person_id, person_info in all_members_dict.items():
                        status = attendance_by_date_person.get(date_key, {}).get(person_id)
                        
                        if status == 'present':
                            present_list.append(person_info)
                        elif status == 'absent':
                            absent_list.append(person_info)
                        else:
                            # No record = absent (they should have been marked)
                            absent_list.append(person_info)
                    
                    detailed_attendance.append({
                        'date': date_key,
                        'present': present_list,
                        'absent': absent_list,
                        'total_present': len(present_list),
                        'total_absent': len(absent_list),
                        'total': len(present_list) + len(absent_list)
                    })
                except Exception as e:
                    logger.warning(f"Error processing meeting {meeting.id if meeting else 'unknown'}: {e}")
                    continue
            
            # Also include dates that have attendance records but no meeting record
            # (in case meetings weren't created in ConnectGroupMeeting)
            for date_key in attendance_by_date_person.keys():
                # Check if we already have this date from meetings
                if not any(m['date'] == date_key for m in detailed_attendance):
                    present_list = []
                    absent_list = []
                    
                    # Check each member's attendance status
                    for person_id, person_info in all_members_dict.items():
                        status = attendance_by_date_person[date_key].get(person_id)
                        
                        if status == 'present':
                            present_list.append(person_info)
                        elif status == 'absent':
                            absent_list.append(person_info)
                        else:
                            # No record = absent
                            absent_list.append(person_info)
                    
                    detailed_attendance.append({
                        'date': date_key,
                        'present': present_list,
                        'absent': absent_list,
                        'total_present': len(present_list),
                        'total_absent': len(absent_list),
                        'total': len(present_list) + len(absent_list)
                    })
            
            # Sort by date (most recent first)
            detailed_attendance.sort(key=lambda x: x['date'], reverse=True)
        except Exception as e:
            logger.error(f"Error building detailed attendance breakdown for group {group_id}: {e}", exc_info=True)
            # Continue with empty detailed_attendance - at least return other data
            detailed_attendance = []
        
        # Build response safely
        try:
            group_id_str = str(getattr(group, 'id', group_id))
            group_name_str = str(getattr(group, 'name', 'Unknown Group'))
            
            response_data = {
                'group_id': group_id_str,
                'group_name': group_name_str,
                'date_range': {
                    'start': start_date.isoformat() if hasattr(start_date, 'isoformat') else str(start_date),
                    'end': end_date.isoformat() if hasattr(end_date, 'isoformat') else str(end_date)
                },
                'heartbeat': heartbeat_data,
                'daily_attendance': attendance_data,
                'detailed_attendance': detailed_attendance,
                'summary': {
                    'total_meetings': total_meetings,
                    'total_present': total_present,
                    'total_absent': total_absent,
                    'total_attendance': total_attendance,
                    'attendance_rate': (total_present / total_attendance * 100) if total_attendance > 0 else 0
                }
            }
            return jsonify(response_data), 200
        except Exception as e:
            logger.error(f"Error building response for group {group_id}: {e}", exc_info=True)
            # Return minimal response
            return jsonify({
                'group_id': str(group_id),
                'group_name': 'Unknown',
                'error': 'Partial data available',
                'heartbeat': heartbeat_data,
                'summary': {
                    'total_meetings': 0,
                    'total_present': 0,
                    'total_absent': 0,
                    'total_attendance': 0,
                    'attendance_rate': 0
                }
            }), 200
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error getting connect group health for {group_id}: {e}", exc_info=True)
        return jsonify({'error': 'Failed to get connect group health data'}), 500


@app.route('/api/connect-groups/meetings/<meeting_id>', methods=['GET'])
def get_group_meeting(meeting_id):
    """Get meeting details with attendance"""
    try:
        meeting = ConnectGroupMeeting.query.filter_by(id=meeting_id).first()
        if not meeting:
            return jsonify({'error': 'Meeting not found'}), 404
        
        group = meeting.group
        
        # Get attendance records
        attendance_records = ConnectGroupAttendance.query.filter_by(meeting_id=meeting_id).all()
        
        meeting_data = meeting.to_dict()
        meeting_data['attendance'] = [att.to_dict() for att in attendance_records]
        
        return jsonify(meeting_data)
        
    except Exception as e:
        logger.error(f"Error fetching meeting: {e}")
        return jsonify({'error': 'Failed to fetch meeting'}), 500


@app.route('/api/connect-groups/<group_id>/chat', methods=['GET'])
def get_group_chat(group_id):
    """Get chat messages for a connect group"""
    try:
        group = ConnectGroup.query.filter_by(id=group_id).first()
        if not group:
            return jsonify({'error': 'Group not found'}), 404
        
        # Get messages ordered by creation date
        messages = ConnectGroupMessage.query.filter_by(
            group_id=group_id
        ).order_by(ConnectGroupMessage.created_at.desc()).limit(100).all()
        
        return jsonify({
            'messages': [msg.to_dict() for msg in reversed(messages)],  # Reverse to show oldest first
            'total': len(messages)
        })
        
    except Exception as e:
        logger.error(f"Error fetching group chat: {e}")
        return jsonify({'error': 'Failed to fetch chat messages'}), 500


@app.route('/api/connect-groups/<group_id>/chat', methods=['POST'])
def send_group_message(group_id):
    """Send a message to group chat"""
    try:
        data = request.get_json()
        email = data.get('email', '').strip()
        message = data.get('message', '').strip()
        
        if not email:
            return jsonify({'error': 'Email is required'}), 400
        if not message:
            return jsonify({'error': 'Message cannot be empty'}), 400
        
        # Find person by email
        person = Person.query.filter(
            db.func.lower(Person.email) == email.lower(),
            Person.is_active == True
        ).first()
        
        if not person:
            return jsonify({'error': 'Person not found'}), 404
        
        # Verify person is a member of the group
        group = ConnectGroup.query.filter_by(id=group_id).first()
        if not group:
            return jsonify({'error': 'Group not found'}), 404
        
        # Check if person is a member or leader
        is_member = person.connect_group == group_id
        is_leader = person.id == group.leader_id or person.id == group.co_leader_id
        all_leader_emails = group.get_leader_emails()
        is_leader_by_email = person.email and person.email.lower() in all_leader_emails
        
        if not (is_member or is_leader or is_leader_by_email):
            return jsonify({'error': 'You must be a member of this group to send messages'}), 403
        
        # Create message
        chat_message = ConnectGroupMessage(
            group_id=group_id,
            person_id=person.id,
            message=message
        )
        db.session.add(chat_message)
        db.session.commit()
        
        logger.info(f"Group chat message sent: {person.email} -> {group_id}")
        
        return jsonify({
            'message': 'Message sent successfully',
            'chat_message': chat_message.to_dict()
        }), 201
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error sending group message: {e}", exc_info=True)
        return jsonify({'error': 'Failed to send message'}), 500


@app.route('/api/connect-groups/<group_id>/leader-portal', methods=['GET'])
def get_leader_portal(group_id):
    """Get leader portal data - members, meetings, attendance (for connect leaders)"""
    try:
        email = request.args.get('email', '').strip()
        access_code = request.args.get('access_code', '')
        
        if not email:
            return jsonify({'error': 'Email is required'}), 400
        
        group = ConnectGroup.query.filter_by(id=group_id).first()
        if not group:
            return jsonify({'error': 'Group not found'}), 404
        
        # Verify leader access
        all_leader_emails = group.get_leader_emails()
        if email.lower() not in all_leader_emails:
            return jsonify({'error': 'You are not a leader of this group'}), 403
        
        # For mobile app users, skip access code requirement since email is already verified
        # Mobile app authenticates via email + Bearer token (already passed leader verification)
        # Access code is only required for web portal direct access (not logged in, no token)
        # If access code is provided but incorrect, reject it
        # If no access code is provided but email is verified as leader, allow access
        if group.leader_access_code and access_code:
            # Access code was provided - verify it
            if access_code != group.leader_access_code:
                return jsonify({'error': 'Invalid access code'}), 403
        # If no access code provided but email verified as leader, allow (mobile app case)
        
        # Get all members (handles both ID and name matching)
        members = group.get_members()
        members_data = [m.to_dict() for m in members]
        
        # Log for debugging
        logger.info(f"Leader portal - Group {group_id} ({group.name}): Found {len(members_data)} members")
        if len(members_data) == 0:
            # Check what's actually in the database
            from sqlalchemy import text
            sample_persons = db.session.execute(
                text("SELECT id, full_name, connect_group FROM persons WHERE is_active = 1 AND connect_group IS NOT NULL LIMIT 10")
            ).fetchall()
            logger.info(f"Sample persons with connect_group: {[dict(p) for p in sample_persons]}")
            logger.info(f"Looking for group ID: {group_id}, group name: {group.name}")
        
        # Get recent meetings (last 10)
        recent_meetings = ConnectGroupMeeting.query.filter_by(
            group_id=group_id
        ).order_by(ConnectGroupMeeting.meeting_date.desc()).limit(10).all()
        
        meetings_data = []
        for meeting in recent_meetings:
            meeting_dict = meeting.to_dict()
            # Get attendance for this meeting
            attendance = ConnectGroupAttendance.query.filter_by(meeting_id=meeting.id).all()
            meeting_dict['attendance'] = [att.to_dict() for att in attendance]
            meetings_data.append(meeting_dict)
        
        # Also include members in the group dict (for compatibility with web portal)
        group_dict = group.to_dict()
        group_dict['members'] = members_data
        
        response_data = {
            'group': group_dict,
            'members': members_data,
            'member_count': len(members_data),
            'recent_meetings': meetings_data
        }
        
        # Enhanced logging
        logger.info(f"Leader portal response for {group_id}: {len(members_data)} members, {len(meetings_data)} meetings")
        if len(members_data) == 0:
            logger.warning(f"No members found for group '{group.name}' (ID: {group_id}). Group leader emails: {all_leader_emails}")
            # Log what get_members() actually found
            logger.warning(f"get_members() returned: {[m.id for m in group.get_members()]}")
        
        return jsonify(response_data)
        
    except Exception as e:
        logger.error(f"Error fetching leader portal: {e}", exc_info=True)
        return jsonify({'error': 'Failed to fetch leader portal data'}), 500


@app.route('/api/connect-groups/<group_id>/leader-portal/attendance', methods=['POST'])
def mark_leader_attendance(group_id):
    """Mark attendance for a meeting (leader only)"""
    try:
        data = request.get_json()
        email = data.get('email', '').strip()
        access_code = data.get('access_code', '')
        meeting_date = data.get('meeting_date')  # ISO date string
        attendance_list = data.get('attendance', [])  # [{person_id, present, notes?}]
        
        if not email:
            return jsonify({'error': 'Email is required'}), 400
        if not meeting_date:
            return jsonify({'error': 'Meeting date is required'}), 400
        if not attendance_list:
            return jsonify({'error': 'Attendance data is required'}), 400
        
        group = ConnectGroup.query.filter_by(id=group_id).first()
        if not group:
            return jsonify({'error': 'Group not found'}), 404
        
        # Verify leader access
        all_leader_emails = group.get_leader_emails()
        if email.lower() not in all_leader_emails:
            return jsonify({'error': 'You are not a leader of this group'}), 403
        
        # For mobile app users, skip access code requirement since email is already verified
        # Mobile app authenticates via email + Bearer token (already passed leader verification)
        # Access code is only required for web portal direct access (not logged in, no token)
        # If access code is provided but incorrect, reject it
        # If no access code is provided but email is verified as leader, allow access
        if group.leader_access_code and access_code:
            # Access code was provided - verify it
            if access_code != group.leader_access_code:
                return jsonify({'error': 'Invalid access code'}), 403
        # If no access code provided but email verified as leader, allow (mobile app case)
        
        # Parse meeting date - handle various formats
        from datetime import datetime
        try:
            # Try ISO format first (YYYY-MM-DD or YYYY-MM-DDTHH:MM:SS)
            if 'T' in meeting_date or '+' in meeting_date or 'Z' in meeting_date:
                # Has time component
                meeting_date_obj = datetime.fromisoformat(meeting_date.replace('Z', '+00:00')).date()
            else:
                # Just date (YYYY-MM-DD)
                meeting_date_obj = datetime.strptime(meeting_date, '%Y-%m-%d').date()
        except (ValueError, AttributeError) as e:
            logger.error(f"Error parsing meeting date '{meeting_date}': {e}")
            return jsonify({'error': f'Invalid date format: {meeting_date}. Expected YYYY-MM-DD'}), 400
        
        # Find or create meeting
        meeting = ConnectGroupMeeting.query.filter_by(
            group_id=group_id,
            meeting_date=meeting_date_obj
        ).first()
        
        if not meeting:
            meeting = ConnectGroupMeeting(
                group_id=group_id,
                meeting_date=meeting_date_obj,
                notes=data.get('notes')
            )
            db.session.add(meeting)
            db.session.flush()
        
        # Update attendance records
        logger.info(f"Processing {len(attendance_list)} attendance records for meeting {meeting.id}")
        for att_data in attendance_list:
            person_id = att_data.get('person_id')
            present = att_data.get('present', False)
            
            if not person_id:
                logger.warning(f"Skipping attendance record with no person_id: {att_data}")
                continue
            
            try:
                # Find or create attendance record
                attendance = ConnectGroupAttendance.query.filter_by(
                    meeting_id=meeting.id,
                    person_id=person_id
                ).first()
                
                if attendance:
                    attendance.present = present
                    attendance.notes = att_data.get('notes')
                    logger.info(f"Updated attendance for person {person_id}: present={present}")
                else:
                    attendance = ConnectGroupAttendance(
                        meeting_id=meeting.id,
                        person_id=person_id,
                        present=present,
                        notes=att_data.get('notes')
                    )
                    db.session.add(attendance)
                    logger.info(f"Created attendance for person {person_id}: present={present}")
                
                # Update engagement profile (optional - don't fail if this fails)
                person = Person.query.filter_by(id=person_id, is_active=True).first()
                if person:
                    # Ensure engagement profile exists
                    if not person.engagement_profile:
                        # Create engagement profile if it doesn't exist
                        engagement = EngagementProfile(person_id=person_id)
                        db.session.add(engagement)
                        db.session.flush()
                        # Refresh person to get the relationship
                        db.session.refresh(person)
                        logger.info(f"Created engagement profile for person {person_id}")
                    
                    try:
                        person.engagement_profile.add_group_attendance(
                            group_id=group_id,
                            attendance_date=meeting_date_obj,
                            present=present
                        )
                        logger.info(f"Updated engagement profile for person {person_id}")
                    except Exception as e:
                        logger.error(f"Error adding group attendance for person {person_id}: {e}", exc_info=True)
                        # Don't fail the whole request if engagement profile update fails
                        # Continue with the rest of the attendance records
                    
                    # Also create ConnectAttendance record for heartbeat engine
                    # The heartbeat engine reads from ConnectAttendance table, not ConnectGroupAttendance
                    try:
                        from models import ConnectAttendance, HeartbeatConnectGroup, Campus
                        
                        # Find or create corresponding HeartbeatConnectGroup
                        heartbeat_group = None
                        person_campus = person.campus if person else None
                        
                        if person_campus:
                            # Try to find heartbeat campus by name
                            from models import Campus
                            heartbeat_campus = Campus.query.filter_by(
                                name=person_campus
                            ).first()
                            
                            if heartbeat_campus:
                                # Try to find existing heartbeat group by name and campus
                                heartbeat_group = HeartbeatConnectGroup.query.filter_by(
                                    name=group.name,
                                    campus_id=heartbeat_campus.id,
                                    is_active=True
                                ).first()
                                
                                # If not found, create one using group's leader_id
                                if not heartbeat_group and group.leader_id:
                                    heartbeat_group = HeartbeatConnectGroup(
                                        campus_id=heartbeat_campus.id,
                                        name=group.name,
                                        leader_person_id=group.leader_id,  # ConnectGroup has leader_id
                                        type='home',  # Default
                                        is_active=True
                                    )
                                    db.session.add(heartbeat_group)
                                    db.session.flush()
                                    logger.info(f"Created new HeartbeatConnectGroup: {heartbeat_group.id} for {group.name}")
                        
                        # Now create ConnectAttendance record if heartbeat_group exists
                        if heartbeat_group:
                            # Check if ConnectAttendance already exists for this person, group, and date
                            existing_heartbeat_attendance = ConnectAttendance.query.filter_by(
                                person_id=person_id,
                                connect_group_id=heartbeat_group.id,
                                date=meeting_date_obj
                            ).first()
                            
                            if existing_heartbeat_attendance:
                                # Update status
                                existing_heartbeat_attendance.status = 'present' if present else 'absent'
                                logger.info(f"Updated ConnectAttendance for person {person_id}, group {heartbeat_group.id}, date {meeting_date_obj}")
                            else:
                                # Create new ConnectAttendance
                                heartbeat_attendance = ConnectAttendance(
                                    person_id=person_id,
                                    connect_group_id=heartbeat_group.id,
                                    date=meeting_date_obj,
                                    status='present' if present else 'absent'
                                )
                                db.session.add(heartbeat_attendance)
                                logger.info(f"Created ConnectAttendance for person {person_id}, group {heartbeat_group.id}, date {meeting_date_obj} - this will be visible to heartbeat engine")
                        else:
                            logger.warning(f"Could not find or create HeartbeatConnectGroup for {group.name}, skipping ConnectAttendance creation")
                    except Exception as e:
                        logger.error(f"Error creating ConnectAttendance record for person {person_id}: {e}", exc_info=True)
                        # Don't fail the whole request if ConnectAttendance creation fails
                        # The ConnectGroupAttendance and engagement profile updates are more important
                else:
                    logger.warning(f"Person {person_id} not found or inactive")
            except Exception as e:
                logger.error(f"Error processing attendance for person {person_id}: {e}", exc_info=True)
                # Continue with next person instead of failing entire request
                continue
        
        # Commit all changes
        try:
            db.session.commit()
            logger.info(f"Attendance marked for group {group_id} on {meeting_date_obj} by {email}: {len([a for a in attendance_list if a.get('person_id')])} records")
        except Exception as commit_error:
            db.session.rollback()
            logger.error(f"Error committing attendance: {commit_error}", exc_info=True)
            import traceback
            logger.error(f"Commit traceback: {traceback.format_exc()}")
            return jsonify({'error': f'Failed to save attendance: {str(commit_error)}'}), 500
        
        # Recalculate heartbeat for all people whose attendance was updated
        # This ensures engagement scores are updated immediately
        try:
            from heartbeat_engine import HeartbeatEngine
            engine = HeartbeatEngine()
            
            # Get unique person IDs from attendance list
            person_ids_updated = set([a.get('person_id') for a in attendance_list if a.get('person_id')])
            
            for person_id in person_ids_updated:
                try:
                    snapshot = engine.calculate_heartbeat(person_id)
                    logger.info(f"✅ Heartbeat recalculated for person {person_id} after group attendance: "
                              f"engagement={snapshot.engagement_score}, total={snapshot.total_score}")
                except Exception as hb_error:
                    logger.warning(f"⚠️ Could not recalculate heartbeat for person {person_id}: {hb_error}", exc_info=True)
                    # Don't fail the whole request if heartbeat recalculation fails for one person
                    continue
            
            db.session.commit()  # Commit heartbeat snapshots
            logger.info(f"✅ Heartbeat recalculated for {len(person_ids_updated)} people after group attendance")
        except Exception as hb_batch_error:
            logger.warning(f"⚠️ Error during batch heartbeat recalculation: {hb_batch_error}", exc_info=True)
            # Don't fail the request if heartbeat recalculation fails - attendance is already saved
        
        # Get updated meeting with attendance
        try:
            meeting_dict = meeting.to_dict()
            attendance_records = ConnectGroupAttendance.query.filter_by(meeting_id=meeting.id).all()
            meeting_dict['attendance'] = [att.to_dict() for att in attendance_records]
        except Exception as dict_error:
            logger.error(f"Error serializing meeting data: {dict_error}", exc_info=True)
            # Return basic success even if serialization fails
            meeting_dict = {'id': meeting.id, 'meeting_date': meeting_date_obj.isoformat()}
        
        return jsonify({
            'message': 'Attendance marked successfully. Heartbeat scores updated.',
            'meeting': meeting_dict
        }), 200
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error marking attendance: {e}", exc_info=True)
        import traceback
        logger.error(f"Traceback: {traceback.format_exc()}")
        return jsonify({'error': f'Failed to mark attendance: {str(e)}'}), 500


# Regular Groups API Endpoints
@app.route('/api/groups', methods=['GET'])
@login_required
def get_groups():
    """Get list of regular groups"""
    try:
        if not current_user.has_permission('groups', 'view'):
            return jsonify({'error': 'Insufficient permissions'}), 403
        
        campus_filter = request.args.get('campus', 'all_campuses')
        status_filter = request.args.get('status', None)
        
        # Build query
        query = Group.query
        
        # Apply campus scoping
        try:
            from utils.campus_scope import apply_campus_filter
            query = apply_campus_filter(query, 'groups')
        except Exception as filter_error:
            logger.warning(f"Campus filter failed: {filter_error}")
        
        if campus_filter and campus_filter != 'all_campuses':
            query = query.filter(Group.campus == campus_filter)
        
        if status_filter:
            query = query.filter(Group.status == status_filter)
        
        groups = query.order_by(Group.name).all()
        
        groups_data = [g.to_dict() for g in groups]
        
        return jsonify({
            'groups': groups_data,
            'total': len(groups_data)
        })
        
    except Exception as e:
        logger.error(f"Error fetching groups: {e}", exc_info=True)
        return jsonify({'error': 'Failed to fetch groups'}), 500


@app.route('/api/groups', methods=['POST'])
@login_required
def create_group():
    """Create new regular group"""
    try:
        if not current_user.has_permission('groups', 'create'):
            return jsonify({'error': 'Insufficient permissions'}), 403
        
        data = request.get_json()
        
        # Validate required fields
        if not data.get('name'):
            return jsonify({'error': 'Missing required field: name'}), 400
        
        # Generate group ID
        import uuid
        campus_slug = (data.get('campus', 'all_campuses') or 'all_campuses').lower().replace(' ', '_')
        group_id = f"grp_{campus_slug}_{str(uuid.uuid4())[:8]}"
        
        # Verify leader exists if provided
        leader_id = data.get('leader_id')
        if leader_id:
            leader = Person.query.filter_by(id=leader_id, is_active=True).first()
            if not leader:
                return jsonify({'error': 'Leader not found'}), 404
        
        # Create group
        group = Group(
            id=group_id,
            name=data['name'],
            campus=data.get('campus', 'all_campuses'),
            leader_id=leader_id,
            description=data.get('description'),
            status=data.get('status', 'active')
        )
        
        db.session.add(group)
        db.session.commit()
        
        return jsonify(group.to_dict()), 201
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error creating group: {e}", exc_info=True)
        return jsonify({'error': 'Failed to create group'}), 500


@app.route('/api/groups/<group_id>', methods=['GET'])
@login_required
def get_group(group_id):
    """Get a single regular group"""
    try:
        if not current_user.has_permission('groups', 'view'):
            return jsonify({'error': 'Insufficient permissions'}), 403
        
        group = Group.query.filter_by(id=group_id).first()
        if not group:
            return jsonify({'error': 'Group not found'}), 404
        
        return jsonify(group.to_dict())
        
    except Exception as e:
        logger.error(f"Error fetching group: {e}", exc_info=True)
        return jsonify({'error': 'Failed to fetch group'}), 500


@app.route('/api/groups/<group_id>', methods=['PUT'])
@login_required
def update_group(group_id):
    """Update a regular group"""
    try:
        if not current_user.has_permission('groups', 'edit'):
            return jsonify({'error': 'Insufficient permissions'}), 403
        
        group = Group.query.filter_by(id=group_id).first()
        if not group:
            return jsonify({'error': 'Group not found'}), 404
        
        data = request.get_json()
        
        # Update fields
        if 'name' in data:
            group.name = data['name']
        if 'campus' in data:
            group.campus = data['campus']
        if 'leader_id' in data:
            leader_id = data['leader_id']
            if leader_id:
                leader = Person.query.filter_by(id=leader_id, is_active=True).first()
                if not leader:
                    return jsonify({'error': 'Leader not found'}), 404
            group.leader_id = leader_id
        if 'description' in data:
            group.description = data['description']
        if 'status' in data:
            group.status = data['status']
        
        group.updated_at = datetime.utcnow()
        db.session.commit()
        
        return jsonify(group.to_dict())
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error updating group: {e}", exc_info=True)
        return jsonify({'error': 'Failed to update group'}), 500


@app.route('/api/groups/<group_id>', methods=['DELETE'])
@login_required
def delete_group(group_id):
    """Delete a regular group"""
    try:
        if not current_user.has_permission('groups', 'delete'):
            return jsonify({'error': 'Insufficient permissions'}), 403
        
        group = Group.query.filter_by(id=group_id).first()
        if not group:
            return jsonify({'error': 'Group not found'}), 404
        
        db.session.delete(group)
        db.session.commit()
        
        return jsonify({'message': 'Group deleted successfully'}), 200
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error deleting group: {e}", exc_info=True)
        return jsonify({'error': 'Failed to delete group'}), 500


@app.route('/api/connect-groups/meetings/<meeting_id>/attendance', methods=['POST'])
def submit_meeting_attendance(meeting_id):
    """Submit attendance for a meeting (allows leader access via email + access code)"""
    try:
        # Handle meeting_id as both string and integer
        try:
            meeting_id_int = int(meeting_id)
        except (ValueError, TypeError):
            meeting_id_int = meeting_id
        
        meeting = ConnectGroupMeeting.query.filter_by(id=meeting_id_int).first()
        if not meeting:
            logger.error(f"Meeting not found: {meeting_id} (tried as int: {meeting_id_int})")
            return jsonify({'error': 'Meeting not found'}), 404
        
        group = meeting.group
        if not group:
            logger.error(f"Group not found for meeting {meeting_id}")
            return jsonify({'error': 'Group not found for this meeting'}), 404
        
        data = request.get_json()
        if not data:
            logger.error("No JSON data provided in request")
            return jsonify({'error': 'No data provided'}), 400
        
        # Check permissions - either logged-in admin/staff OR leader via email + access code
        is_leader = False
        is_authenticated_user = False
        
        # Check if user is logged in
        try:
            if current_user and hasattr(current_user, 'email'):
                all_leader_emails = group.get_leader_emails()
                is_leader = current_user.email.lower() in all_leader_emails
                is_authenticated_user = current_user.has_permission('groups', 'edit')
        except Exception as auth_error:
            logger.debug(f"Auth check failed (expected for leader portal): {auth_error}")
            pass  # Not logged in, check email + access code
        
        # If not authenticated user, check email + access code
        if not is_authenticated_user and not is_leader:
            all_leader_emails = group.get_leader_emails()
            provided_email = data.get('leader_email', '').lower()
            provided_code = data.get('access_code', '')
            
            if provided_email and provided_email in all_leader_emails:
                # Verify access code if set
                if group.leader_access_code:
                    if provided_code != group.leader_access_code:
                        return jsonify({'error': 'Invalid access code'}), 403
                is_leader = True
            else:
                return jsonify({'error': 'Insufficient permissions'}), 403
        
        if not (is_authenticated_user or is_leader):
            return jsonify({'error': 'Insufficient permissions'}), 403
        
        attendance_list = data.get('attendance', [])  # [{person_id, present, notes?}]
        
        if not attendance_list:
            return jsonify({'error': 'No attendance data provided'}), 400
        
        # Update attendance records
        logger.error(f"🔍 DIAGNOSTIC: Processing attendance for {len(attendance_list)} people in meeting {meeting_id}")
        for att_data in attendance_list:
            person_id = att_data.get('person_id')
            present = att_data.get('present', False)
            logger.error(f"🔍 DIAGNOSTIC: Processing person_id={person_id}, present={present}")
            
            if not person_id:
                logger.warning(f"  Skipping entry with no person_id: {att_data}")
                continue
            
            # Find or create attendance record
            # Use the same meeting_id_int we found earlier
            attendance = ConnectGroupAttendance.query.filter_by(
                meeting_id=meeting_id_int,
                person_id=person_id
            ).first()
            
            if attendance:
                attendance.present = present
                attendance.notes = att_data.get('notes')
            else:
                # Create new attendance record
                attendance = ConnectGroupAttendance(
                    meeting_id=meeting_id_int,
                    person_id=person_id,
                    present=present,
                    notes=att_data.get('notes')
                )
                db.session.add(attendance)
            
            # Update engagement profile and heartbeat records (for both present and absent)
            person = Person.query.filter_by(id=person_id, is_active=True).first()
            if not person:
                logger.warning(f"  Person not found or not active: {person_id}")
            if person:
                logger.error(f"🔍 DIAGNOSTIC: Found person: {person.full_name} (ID: {person_id})")
                # Get or create engagement profile (needed for both present and absent tracking)
                # Handle case where relationship might fail due to date parsing issues
                engagement = None
                engagement_available = False
                try:
                    engagement = person.engagement_profile
                    engagement_available = True
                    logger.debug(f"Successfully loaded engagement profile for {person.full_name}")
                except (ValueError, AttributeError) as profile_error:
                    logger.warning(f"Error accessing engagement_profile via relationship for {person.full_name}: {profile_error}")
                    # Try to query directly with raw SQL to avoid date parsing issues
                    try:
                        from sqlalchemy import text
                        result = db.session.execute(
                            text("SELECT person_id FROM engagement_profiles WHERE person_id = :person_id"),
                            {'person_id': person_id}
                        ).fetchone()
                        if result:
                            # Profile exists, but don't try to load it via ORM if date parsing will fail
                            # We'll skip engagement profile updates for people with corrupted date fields
                            # ConnectAttendance records will still be created for heartbeat tracking
                            logger.warning(f"Engagement profile exists for {person.full_name} but cannot be loaded due to date parsing issues. Skipping engagement profile updates, but ConnectAttendance will still be created.")
                            engagement_available = False
                            engagement = None
                        else:
                            # Profile doesn't exist, create it
                            try:
                                engagement = EngagementProfile(person_id=person.id)
                                db.session.add(engagement)
                                db.session.flush()
                                engagement_available = True
                                logger.info(f"Created engagement profile for person {person_id} ({person.full_name})")
                            except Exception as create_error:
                                logger.error(f"Error creating engagement profile: {create_error}", exc_info=True)
                                engagement_available = False
                    except Exception as query_error:
                        logger.error(f"Error querying engagement profile directly: {query_error}", exc_info=True)
                        engagement_available = False
                except Exception as profile_error:
                    logger.error(f"Unexpected error accessing engagement_profile for {person.full_name}: {profile_error}", exc_info=True)
                    engagement_available = False
                
                if not engagement and engagement_available:
                    try:
                        engagement = EngagementProfile(person_id=person.id)
                        db.session.add(engagement)
                        db.session.flush()  # Flush to get the ID
                        logger.info(f"Created engagement profile for person {person_id} ({person.full_name})")
                    except Exception as create_error:
                        logger.error(f"Error creating engagement profile: {create_error}", exc_info=True)
                        engagement_available = False
                
                # Track attendance (present or absent) in Heartbeat system
                # ALWAYS create ConnectAttendance records, even if engagement profile access fails
                # This ensures attendance shows up in heartbeat regardless of date parsing issues
                logger.error(f"🔍 DIAGNOSTIC: 🎯 Starting heartbeat tracking for {person.full_name} (ID: {person_id}, present={present})")
                try:
                    from models import ConnectAttendance, HeartbeatConnectGroup, Campus as HeartbeatCampus
                    logger.info(f"  Successfully imported heartbeat models for {person.full_name}")
                    
                    # Get or create Heartbeat campus
                    campus_normalized = group.campus.lower().replace(' ', '_')
                    heartbeat_campus = HeartbeatCampus.query.filter_by(id=campus_normalized).first()
                    if not heartbeat_campus:
                        heartbeat_campus = HeartbeatCampus(
                            id=campus_normalized,
                            name=group.campus,
                            timezone='Australia/Adelaide',
                            is_active=True
                        )
                        db.session.add(heartbeat_campus)
                        db.session.flush()
                        logger.info(f"Created Heartbeat campus: {campus_normalized}")
                    
                    # Find or create HeartbeatConnectGroup
                    heartbeat_group = HeartbeatConnectGroup.query.filter_by(
                        name=group.name,
                        leader_person_id=group.leader_id,
                        campus_id=heartbeat_campus.id
                    ).first()
                    
                    if not heartbeat_group:
                        # Try matching by name and campus only (in case leader changed)
                        heartbeat_group = HeartbeatConnectGroup.query.filter_by(
                            name=group.name,
                            campus_id=heartbeat_campus.id,
                            is_active=True
                        ).first()
                        if heartbeat_group:
                            logger.info(f"Found HeartbeatConnectGroup by name/campus (leader may have changed): {heartbeat_group.id}")
                    
                    if not heartbeat_group:
                        heartbeat_group = HeartbeatConnectGroup(
                            campus_id=heartbeat_campus.id,
                            name=group.name,
                            leader_person_id=group.leader_id,
                            type='home',
                            day_of_week=group.meeting_day,
                            is_active=group.is_active if hasattr(group, 'is_active') else True
                        )
                        db.session.add(heartbeat_group)
                        db.session.flush()
                        logger.info(f"Created NEW HeartbeatConnectGroup: {heartbeat_group.id} for {group.name}")
                    else:
                        logger.info(f"Found existing HeartbeatConnectGroup: {heartbeat_group.id} for {group.name}")
                    
                    # Ensure meeting_date is a date object
                    attendance_date = meeting.meeting_date
                    if isinstance(attendance_date, str):
                        from datetime import datetime as dt
                        attendance_date = dt.fromisoformat(attendance_date).date()
                    elif isinstance(attendance_date, datetime):
                        attendance_date = attendance_date.date()
                    
                    # CRITICAL FIX: If meeting date is in the future, use today's date in local timezone instead
                    # Use Australia/Adelaide timezone to get the correct local date
                    from zoneinfo import ZoneInfo
                    adelaide_tz = ZoneInfo('Australia/Adelaide')
                    today_local = datetime.now(adelaide_tz).date()
                    if attendance_date > today_local:
                        logger.warning(f"Meeting date {attendance_date} is in the future. Using today's date {today_local} for attendance record.")
                        attendance_date = today_local
                    
                    # Determine status: 'present' or 'absent'
                    attendance_status = 'present' if present else 'absent'
                    logger.error(f"🔍 DIAGNOSTIC: About to create/update ConnectAttendance: person={person.full_name}, group={heartbeat_group.id}, date={attendance_date}, status={attendance_status}")
                    
                    # Create or update ConnectAttendance record (for both present and absent)
                    existing_attendance = ConnectAttendance.query.filter_by(
                        person_id=person_id,
                        connect_group_id=heartbeat_group.id,
                        date=attendance_date
                    ).first()
                    
                    if existing_attendance:
                        existing_attendance.status = attendance_status
                        logger.error(f"🔍 DIAGNOSTIC: ✅ UPDATED ConnectAttendance record for {person.full_name} - person_id={person_id}, group_id={heartbeat_group.id}, Status={attendance_status}, Date={attendance_date}")
                    else:
                        connect_attendance = ConnectAttendance(
                            person_id=person_id,
                            connect_group_id=heartbeat_group.id,
                            date=attendance_date,
                            status=attendance_status
                        )
                        db.session.add(connect_attendance)
                        db.session.flush()
                        logger.error(f"🔍 DIAGNOSTIC: ✅ CREATED ConnectAttendance record for {person.full_name} - person_id={person_id}, group_id={heartbeat_group.id}, Status={attendance_status}, Date={attendance_date}")
                    
                    # Recalculate heartbeat for both present and absent (attendance affects engagement)
                    try:
                        from heartbeat_engine import HeartbeatEngine
                        engine = HeartbeatEngine()
                        snapshot = engine.calculate_heartbeat(person_id)
                        logger.error(f"🔍 DIAGNOSTIC: ✅ Recalculated heartbeat for {person.full_name} after attendance update (status: {attendance_status}) - engagement={snapshot.engagement_score if snapshot else 'N/A'}%, total={snapshot.total_score if snapshot else 'N/A'}%")
                    except ImportError as import_error:
                        logger.error(f"Cannot import HeartbeatEngine - {import_error}")
                    except Exception as hb_recalc_error:
                        logger.error(f"Error recalculating heartbeat for {person.full_name}: {hb_recalc_error}", exc_info=True)
                
                except Exception as heartbeat_error:
                    logger.error(f"Error updating Heartbeat system for {person.full_name}: {heartbeat_error}", exc_info=True)
                
                # Update EngagementProfile (legacy system) - only if present and engagement is available
                # Note: engagement should already be loaded above, don't try to load it again
                if present and engagement_available and engagement:
                    try:
                        # Engagement profile is already loaded above, use it directly
                        # If it's None, create it
                        if not engagement:
                            engagement = EngagementProfile(person_id=person.id)
                            db.session.add(engagement)
                            db.session.flush()  # Flush to get the ID
                            logger.info(f"Created engagement profile for person {person_id} ({person.full_name})")
                        
                        # Add group attendance to engagement profile (feeds to heartbeat)
                        try:
                            # Ensure meeting_date is a date object
                            attendance_date = meeting.meeting_date
                            if isinstance(attendance_date, str):
                                from datetime import datetime as dt
                                # Handle both ISO format and SQLite datetime format
                                try:
                                    # Try ISO format first
                                    attendance_date = dt.fromisoformat(attendance_date.replace('Z', '+00:00')).date()
                                except ValueError:
                                    # Try SQLite datetime format: '2025-11-19 00:00:00.000000'
                                    try:
                                        attendance_date = dt.strptime(attendance_date.split('.')[0], '%Y-%m-%d %H:%M:%S').date()
                                    except ValueError:
                                        # Try just date format
                                        attendance_date = dt.strptime(attendance_date.split(' ')[0], '%Y-%m-%d').date()
                            elif isinstance(attendance_date, datetime):
                                attendance_date = attendance_date.date()
                            
                            # CRITICAL FIX: If meeting date is in the future, use today's date in local timezone instead
                            # Heartbeat calculation only looks at past dates, so future dates won't be counted
                            from zoneinfo import ZoneInfo
                            adelaide_tz = ZoneInfo('Australia/Adelaide')
                            today_local = datetime.now(adelaide_tz).date()
                            if attendance_date > today_local:
                                logger.warning(f"Meeting date {attendance_date} is in the future. Using today's local date {today_local} for attendance record.")
                                attendance_date = today_local
                            
                            logger.info(f"Adding group attendance for {person.full_name} (ID: {person_id}) - Group: {group.id}, Date: {attendance_date}, Type: {type(attendance_date)}")
                            
                            # Update EngagementProfile (legacy system)
                            engagement.add_group_attendance(
                                group_id=group.id,
                                attendance_date=attendance_date,
                                present=True
                            )
                            
                            # NOTE: ConnectAttendance records are already created in the heartbeat tracking section above
                            # (lines 18557-18577), so we don't need to create them again here to avoid duplicates
                            
                            # Flush to ensure changes are in the session
                            db.session.flush()
                            
                            # Log the group attendance log after adding (from milestones_log, not group_attendance_log)
                            milestones_log = engagement._load_json(engagement.milestones_log or '[]')
                            group_log = [log for log in milestones_log if log.get('type') == 'group_attendance']
                            logger.info(f"Group attendance log after add: {group_log}")
                            logger.info(f"Engagement profile updated - overall_engagement: {engagement.overall_engagement}, pulse_status: {engagement.pulse_status}, last_seen: {engagement.last_seen}")
                        
                        except Exception as group_attendance_error:
                            logger.error(f"Error adding group attendance for {person.full_name}: {group_attendance_error}", exc_info=True)
                            # Don't fail the whole operation if group attendance logging fails
                    
                    except Exception as e:
                        logger.error(f"Error updating engagement profile for {person.full_name}: {e}", exc_info=True)
                        # Don't fail the whole operation if engagement profile update fails
                elif present and not engagement_available:
                    logger.warning(f"Skipping engagement profile update for {person.full_name} - profile not available due to date parsing issues")
        
        # Commit all attendance changes at once (more efficient and atomic)
        try:
            logger.error(f"🔍 DIAGNOSTIC: About to commit attendance for meeting {meeting_id} for {len(attendance_list)} people")
            db.session.commit()
            logger.error(f"🔍 DIAGNOSTIC: ✅✅✅ Successfully committed attendance for meeting {meeting_id} for {len(attendance_list)} people")
        except Exception as commit_error:
            logger.error(f"Error committing attendance: {commit_error}", exc_info=True)
            db.session.rollback()
            return jsonify({
                'error': 'Failed to commit attendance changes',
                'details': str(commit_error)
            }), 500
        
        # Recalculate heartbeat for ALL affected people (both present and absent - attendance affects engagement)
        recalculated_people = []
        person_ids_updated = set([att.get('person_id') for att in attendance_list if att.get('person_id')])
        
        for person_id in person_ids_updated:
            person = Person.query.filter_by(id=person_id, is_active=True).first()
            if person:
                try:
                    # Try to refresh engagement profile if it exists (but don't fail if it has date issues)
                    try:
                        if person.engagement_profile:
                            db.session.refresh(person.engagement_profile)
                            logger.info(f"Refreshed engagement profile for {person.full_name} - engagement: {person.engagement_profile.overall_engagement}, pulse: {person.engagement_profile.pulse_status}")
                    except (ValueError, AttributeError) as refresh_error:
                        logger.warning(f"Could not refresh engagement profile for {person.full_name} (date parsing issue): {refresh_error}")
                        # Continue anyway - heartbeat calculation doesn't need engagement profile
                    
                    # Recalculate Heartbeat snapshot for this person (for both present and absent)
                    from heartbeat_engine import HeartbeatEngine
                    engine = HeartbeatEngine()
                    logger.info(f"Starting Heartbeat recalculation for {person.full_name} (ID: {person_id})")
                    snapshot = engine.calculate_heartbeat(person_id)
                    recalculated_people.append(person.full_name)
                    logger.info(f"✅ Successfully recalculated Heartbeat for {person.full_name} - Score: {snapshot.total_score}, Status: {snapshot.status}, Engagement: {snapshot.engagement_score}")
                except ImportError as import_error:
                    logger.error(f"CRITICAL: Cannot import HeartbeatEngine - {import_error}. Heartbeat system may not be available.")
                except Exception as hb_recalc_error:
                    logger.error(f"Error recalculating heartbeat for {person.full_name}: {hb_recalc_error}", exc_info=True)
                    # Don't fail the whole operation if recalculation fails
        
        # Commit heartbeat recalculations
        try:
            db.session.commit()
            logger.info(f"✅ Committed heartbeat recalculations for {len(recalculated_people)} people")
        except Exception as commit_error:
            logger.error(f"Error committing heartbeat recalculations: {commit_error}", exc_info=True)
            db.session.rollback()
        
        if recalculated_people:
            logger.info(f"✅ Successfully recalculated heartbeat for {len(recalculated_people)} people: {', '.join(recalculated_people)}")
        
        # Get the latest heartbeat scores for the recalculated people to show in response
        heartbeat_results = []
        recalculated_person_ids = set()  # Track person IDs that were recalculated
        for person_id in person_ids_updated:
            person = Person.query.filter_by(id=person_id, is_active=True).first()
            if person and person.full_name in recalculated_people:
                recalculated_person_ids.add(person_id)
                try:
                    from models import HeartbeatSnapshot
                    snapshot = HeartbeatSnapshot.query.filter_by(
                        person_id=person_id
                    ).order_by(HeartbeatSnapshot.calculated_at.desc()).first()
                    if snapshot:
                        heartbeat_results.append({
                            'person_id': person_id,
                            'person_name': person.full_name,
                            'total_score': snapshot.total_score,
                            'engagement_score': snapshot.engagement_score,
                            'gather_score': snapshot.gather_score,
                            'spiritual_score': snapshot.spiritual_score,
                            'care_score': snapshot.care_score,
                            'status': snapshot.status,
                            'calculated_at': snapshot.calculated_at.isoformat() if snapshot.calculated_at else None
                        })
                        logger.info(f"Added heartbeat result for {person.full_name}: engagement={snapshot.engagement_score}, total={snapshot.total_score}")
                    else:
                        logger.warning(f"No HeartbeatSnapshot found for {person.full_name} after recalculation")
                except Exception as e:
                    logger.error(f"Error getting heartbeat snapshot for {person.full_name}: {e}", exc_info=True)
        
        # Get meeting dict safely
        try:
            meeting_dict = meeting.to_dict() if hasattr(meeting, 'to_dict') else {
                'id': meeting.id,
                'meeting_date': str(meeting.meeting_date) if hasattr(meeting, 'meeting_date') else None,
                'group_id': meeting.group_id if hasattr(meeting, 'group_id') else None
            }
        except Exception as meeting_dict_error:
            logger.warning(f"Error getting meeting dict: {meeting_dict_error}")
            meeting_dict = {'id': meeting.id if hasattr(meeting, 'id') else meeting_id_int}
        
        return jsonify({
            'message': f'Attendance submitted successfully. Heartbeat recalculated for {len(recalculated_people)} people.',
            'meeting': meeting_dict,
            'heartbeat_recalculated': len(recalculated_people),
            'people': recalculated_people,
            'heartbeat_scores': heartbeat_results
        })
        
    except Exception as e:
        db.session.rollback()
        import traceback
        error_traceback = traceback.format_exc()
        error_type = type(e).__name__
        error_message = str(e)
        logger.error(f"Error submitting attendance: {error_type}: {error_message}")
        logger.error(f"Full traceback: {error_traceback}")
        # Return more detailed error for debugging
        return jsonify({
            'error': 'Failed to submit attendance',
            'error_type': error_type,
            'details': error_message,
            'meeting_id': meeting_id if 'meeting_id' in locals() else 'unknown'
        }), 500


@app.route('/api/pulse/<person_id>', methods=['GET'])
@login_required
def get_pulse_status(person_id):
    """Get pulse status and reasons for a person (admin only)"""
    try:
        if not current_user.has_permission('pulse', 'read'):
            return jsonify({'error': 'Insufficient permissions'}), 403
        
        person = Person.query.filter_by(id=person_id, is_active=True).first()
        if not person:
            return jsonify({'error': 'Person not found'}), 404
        
        engagement = person.engagement_profile
        if not engagement:
            return jsonify({
                'person_id': person_id,
                'pulse_status': 'red',
                'pulse_reasons': ['No engagement data'],
                'last_calculated': None
            })
        
        return jsonify({
            'person_id': person_id,
            'pulse_status': engagement.pulse_status,
            'pulse_reasons': engagement.get_pulse_reasons(),
            # Note: pulse_last_calculated column removed - not in database schema
            'metrics': {
                'attendance_frequency': engagement.attendance_frequency,
                'serving_frequency': engagement.serving_frequency,
                'overall_engagement': engagement.overall_engagement,
                'last_seen': engagement.last_seen.isoformat() if (engagement.last_seen and hasattr(engagement.last_seen, 'isoformat')) else (str(engagement.last_seen) if engagement.last_seen else None)
            }
        })
        
    except Exception as e:
        logger.error(f"Error fetching pulse status: {e}")
        return jsonify({'error': 'Failed to fetch pulse status'}), 500


@app.route('/api/beacon_zones', methods=['GET'])
@login_required
def get_beacon_zones():
    """Get all beacon zones (admin only)"""
    try:
        # Check for beacons permission or admin role
        has_permission = (
            current_user.has_permission('beacons', 'read') or
            current_user.has_permission('beacons', '*') or
            current_user.role in ['admin', 'senior_leadership', 'senior_leader', 'senior_pastor', 'lead_pastor']
        )
        if not has_permission:
            return jsonify({'error': 'Insufficient permissions'}), 403
        
        campus_filter = request.args.get('campus', None)
        
        query = BeaconZone.query.filter_by(is_active=True)
        if campus_filter and campus_filter != 'all_campuses':
            query = query.filter(BeaconZone.campus == campus_filter)
        
        zones = query.order_by(BeaconZone.campus, BeaconZone.zone_name).all()
        
        return jsonify({
            'zones': [zone.to_dict() for zone in zones],
            'total': len(zones)
        })
        
    except Exception as e:
        logger.error(f"Error fetching beacon zones: {e}")
        return jsonify({'error': 'Failed to fetch beacon zones'}), 500


@app.route('/api/passport/<person_email>', methods=['GET'])
def get_passport_data(person_email):
    """Get passport/discipleship data for a user (public endpoint)"""
    try:
        # Find person by email
        person = Person.query.filter_by(email=person_email, is_active=True).first()
        if not person:
            return jsonify({'error': 'Person not found'}), 404
        
        # Return only positive, step-focused data (no attendance or pulse status)
        passport_data = {
            'person': {
                'full_name': person.full_name,
                'preferred_name': person.preferred_name,
                'campus': person.campus
            },
            'milestones': {
                'dna_completed': person.dna_completed.isoformat() if person.dna_completed else None,
                'baptised_on': person.baptised_on.isoformat() if person.baptised_on else None,
                'filled_holy_spirit': person.filled_holy_spirit.isoformat() if person.filled_holy_spirit else None,
                'rise_attended': person.rise_attended.isoformat() if person.rise_attended else None,
                'first_served_on': person.first_served_on.isoformat() if person.first_served_on else None
            },
            'current_involvement': {
                'connect_group': person.connect_group,
                'dream_team_roles': person.dream_team_roles or []
            },
            'next_steps': []
        }
        
        # Calculate suggested next steps
        next_steps = []
        if not person.dna_completed:
            next_steps.append({
                'title': 'Complete DNA',
                'description': 'Discover your purpose and calling',
                'priority': 'high',
                'category': 'discipleship'
            })
        elif not person.baptised_on:
            next_steps.append({
                'title': 'Get Baptised',
                'description': 'Take the next step in your faith journey',
                'priority': 'high',
                'category': 'discipleship'
            })
        elif not person.rise_attended:
            next_steps.append({
                'title': 'Attend RISE',
                'description': 'Deepen your relationship with the Holy Spirit',
                'priority': 'medium',
                'category': 'discipleship'
            })
        
        if not person.connect_group:
            next_steps.append({
                'title': 'Join a Connect Group',
                'description': 'Build meaningful relationships and grow together',
                'priority': 'high',
                'category': 'community'
            })
        
        if not person.dream_team_roles or len(person.dream_team_roles) == 0:
            next_steps.append({
                'title': 'Join the Dream Team',
                'description': 'Use your gifts to serve others',
                'priority': 'medium',
                'category': 'serving'
            })
        
        passport_data['next_steps'] = next_steps
        
        return jsonify(passport_data)
        
    except Exception as e:
        logger.error(f"Error fetching passport data: {e}")
        return jsonify({'error': 'Failed to fetch passport data'}), 500


