# Events API endpoints
@app.route('/api/events', methods=['GET'])
def get_events():
    """Get all events with optional filtering"""
    try:
        # Get query parameters
        campus = request.args.get('campus', 'all_campuses')
        category = request.args.get('category', 'all')
        status = request.args.get('status', 'all')
        upcoming = request.args.get('upcoming', 'true')
        cancelled = request.args.get('cancelled', 'false')
        search = request.args.get('search', '')
        public_only = request.args.get('public_only', 'false')
        
        logger.info(f"[EVENTS] Fetching events - campus: {campus}, upcoming: {upcoming}, status: {status}")
        
        # Build query - handle schema mismatches gracefully
        # Pulse database uses start_datetime/end_datetime, not start_time/end_time
        use_raw_sql = False
        from sqlalchemy import text
        
        # Always check Pulse schema first (start_datetime exists)
        try:
            test_result = db.session.execute(text("SELECT start_datetime FROM events LIMIT 1"))
            test_result.fetchone()
            logger.info("[EVENTS] Pulse schema detected (start_datetime exists), using raw SQL")
            use_raw_sql = True
            # Count using raw SQL
            result = db.session.execute(text("SELECT COUNT(*) FROM events WHERE is_active = 1"))
            total_active = result.scalar()
            logger.info(f"[EVENTS] Total active events (Pulse schema): {total_active}")
        except Exception as pulse_schema_error:
            # Check if old schema (start_time) exists
            try:
                test_result = db.session.execute(text("SELECT start_time FROM events LIMIT 1"))
                test_result.fetchone()
                logger.info("[EVENTS] Old schema detected (start_time exists), using ORM query")
                use_raw_sql = False
            except Exception:
                logger.warning("[EVENTS] Neither schema detected, defaulting to raw SQL")
                use_raw_sql = True
        
        # Build ORM query (only if old schema with start_time)
        query = None
        if not use_raw_sql:
            try:
                query = Event.query.filter_by(is_active=True)
                total_active = query.count()
                logger.info(f"[EVENTS] Total active events in database: {total_active}")
            except Exception as orm_error:
                logger.warning(f"[EVENTS] ORM query failed, falling back to raw SQL: {orm_error}")
                use_raw_sql = True
        
        # If schema mismatch, use raw SQL for entire query
        if use_raw_sql:
            try:
                from sqlalchemy import text
                # Build raw SQL query using ACTUAL Pulse database schema
                sql = """
                    SELECT id, title, description, short_description, category_id, campus, 
                           location, virtual_link, start_datetime, end_datetime, is_all_day,
                           registration_required, registration_opens, registration_closes,
                           max_capacity, allow_waitlist, is_public, requires_approval,
                           minimum_age, maximum_age, is_active
                    FROM events 
                    WHERE is_active = 1
                """
                params = {}
                
                # Add campus filter
                if campus != 'all_campuses':
                    sql += " AND (campus = :campus OR campus = 'all_campuses')"
                    params['campus'] = campus
                
                # Add upcoming filter using start_datetime
                if upcoming == 'true':
                    sql += " AND (start_datetime > datetime('now') OR start_datetime IS NULL)"
                elif upcoming == 'false':
                    sql += " AND start_datetime < datetime('now') AND start_datetime IS NOT NULL"
                
                # Order by start_datetime
                sql += " ORDER BY start_datetime ASC"
                
                # Execute query
                result = db.session.execute(text(sql), params)
                rows = result.fetchall()
                
                # Convert to dict format matching expected API response
                events = []
                for row in rows:
                    event_dict = {
                        'id': row[0],
                        'title': row[1],
                        'description': row[2],
                        'short_description': row[3],
                        'category_id': row[4],
                        'campus': row[5],
                        'location': row[6],
                        'virtual_link': row[7],
                        'start_time': str(row[8]) if row[8] else None,  # Map start_datetime to start_time for API compatibility
                        'end_time': str(row[9]) if row[9] else None,    # Map end_datetime to end_time
                        'start_datetime': str(row[8]) if row[8] else None,
                        'end_datetime': str(row[9]) if row[9] else None,
                        'is_all_day': bool(row[10]) if row[10] else False,
                        'registration_required': bool(row[11]) if row[11] else False,
                        'registration_opens': str(row[12]) if row[12] else None,
                        'registration_closes': str(row[13]) if row[13] else None,
                        'max_capacity': row[14],
                        'allow_waitlist': bool(row[15]) if row[15] else False,
                        'is_public': bool(row[16]) if row[16] else True,
                        'requires_approval': bool(row[17]) if row[17] else False,
                        'minimum_age': row[18],
                        'maximum_age': row[19],
                        'is_active': bool(row[20]) if row[20] else True,
                    }
                    events.append(event_dict)
                
                logger.info(f"[EVENTS] Returning {len(events)} events via raw SQL (Pulse schema)")
                return jsonify({'events': events})
            except Exception as raw_sql_error:
                logger.error(f"[EVENTS] Raw SQL query failed: {raw_sql_error}")
                return jsonify({'events': [], 'error': 'Failed to fetch events'}), 500
        
        # If we reach here, we're using ORM queries (schema has start_time column)
        # Filter by campus
        if campus != 'all_campuses':
            query = query.filter(Event.campus.in_(['all_campuses', campus]))
        
        # Filter by category (using category_id if provided as number, or name if string)
        if category != 'all':
            try:
                category_id = int(category)
                query = query.filter(Event.category_id == category_id)
            except ValueError:
                # If it's not a number, try to match by category name
                query = query.join(EventCategory).filter(EventCategory.name.ilike(f'%{category}%'))
        
        # Filter by status (now supports: draft, published, cancelled, completed)
        # Note: status column may not exist yet if migration hasn't run
        if status != 'all':
            if hasattr(Event, 'status') and status in ['draft', 'published', 'cancelled', 'completed']:
                query = query.filter(Event.status == status)
            elif status == 'upcoming':
                query = query.filter(
                    db.or_(
                        Event.start_time > datetime.utcnow(),
                        Event.start_time.is_(None)
                    )
                )
        elif status == 'past':
            query = query.filter(
                db.and_(
                    Event.start_time.isnot(None),
                    Event.start_time < datetime.utcnow()
                )
            )
        
        # Filter by upcoming/past
        # If upcoming='all', show all events (no date filtering)
        # For upcoming='true', show events in the future OR events without a start_time (always show those)
        if upcoming == 'all':
            # Show all events, no date filtering
            pass
        elif upcoming == 'true':
            query = query.filter(
                db.or_(
                    Event.start_time > datetime.utcnow(),
                    Event.start_time.is_(None)
                )
            )
        elif upcoming == 'false':
            # For past events, only show events that have a start_time and are in the past
            query = query.filter(
                db.and_(
                    Event.start_time.isnot(None),
                    Event.start_time < datetime.utcnow()
                )
            )
        
        # Note: is_cancelled column doesn't exist in Event model - removed filter
        
        # Filter by ministry
        ministry = request.args.get('ministry', '')
        if ministry:
            # Filter by ministry (only if column exists)
            if hasattr(Event, 'ministry'):
                query = query.filter(Event.ministry == ministry)
        
        # Filter by tags (tags stored as JSON array in TEXT field)
        # Note: tags column may not exist yet if migration hasn't run
        tag = request.args.get('tag', '')
        if tag and hasattr(Event, 'tags'):
            # Search for tag in JSON array
            query = query.filter(Event.tags.contains(tag))
        
        # Search by title or description
        if search:
            search_term = f'%{search}%'
            query = query.filter(
                db.or_(
                    Event.title.ilike(search_term),
                    Event.description.ilike(search_term)
                )
            )
        
        # Order by start date (NULLs last, then by start_time ascending)
        query = query.order_by(
            db.case((Event.start_time.is_(None), 1), else_=0),
            Event.start_time.asc()
        )
        
        # Execute query - handle missing image_url column gracefully
        try:
            events = query.all()
            logger.info(f"[EVENTS] Found {len(events)} events after filtering")
        except Exception as query_error:
            error_str = str(query_error).lower()
            if 'no such column' in error_str and 'image_url' in error_str:
                logger.warning("[EVENTS] image_url column not found - using raw SQL query")
                # Use raw SQL to fetch events without image_url column
                from sqlalchemy import text
                sql_query = """
                    SELECT id, title, description, campus, category_id, start_time, end_time, 
                           location, is_active, created_at, updated_at, price, requires_payment, 
                           stripe_price_id, beacon_zone_id
                    FROM events 
                    WHERE is_active = 1
                    ORDER BY 
                        CASE WHEN start_time IS NULL THEN 1 ELSE 0 END,
                        start_time ASC
                """
                result = db.session.execute(text(sql_query))
                rows = result.fetchall()
                # Convert rows to Event objects manually
                events = []
                for row in rows:
                    event = Event.query.get(row[0])  # Get by ID - this might still fail
                    if event:
                        events.append(event)
                logger.info(f"[EVENTS] Found {len(events)} events using workaround")
            else:
                raise  # Re-raise if it's a different error
        
        # Check if image_url column exists in database
        from sqlalchemy import inspect
        inspector = inspect(db.engine)
        has_image_url_column = False
        try:
            columns = [col['name'] for col in inspector.get_columns('events')]
            has_image_url_column = 'image_url' in columns
        except:
            pass
        
        # Convert to JSON
        events_data = []
        for event in events:
            # Get category info
            category_info = None
            if event.category:
                category_info = {
                    'id': event.category.id,
                    'name': event.category.name,
                    'color': event.category.color,
                    'description': event.category.description
                }
            
            # Calculate registration count from actual registrations
            registration_count = event.get_registration_count()
            
            # Fetch image_url using raw SQL if column exists but not in model
            image_url = None
            if has_image_url_column:
                try:
                    result = db.session.execute(
                        text("SELECT image_url FROM events WHERE id = :event_id"),
                        {'event_id': event.id}
                    ).fetchone()
                    if result and result[0]:
                        image_url = result[0]
                except Exception as img_error:
                    logger.debug(f"Could not fetch image_url for event {event.id}: {img_error}")
            
            # Fallback to event_images mapping if column missing or value empty
            if not image_url:
                mapped_filename = get_event_image(event.id)
                if mapped_filename:
                    image_url = build_image_url(mapped_filename)
            
            events_data.append({
                'id': event.id,
                'title': event.title,
                'description': event.description,
                'short_description': getattr(event, 'short_description', None),
                'category': category_info,
                'campus': event.campus,
                'location': event.location,
                'virtual_link': getattr(event, 'virtual_link', None),  # May not exist
                'start_datetime': event.start_time.isoformat() if event.start_time else None,
                'start_time': event.start_time.isoformat() if event.start_time else None,  # Also include as start_time for compatibility
                'end_datetime': event.end_time.isoformat() if event.end_time else None,
                'end_time': event.end_time.isoformat() if event.end_time else None,  # Also include as end_time for compatibility
                'is_all_day': getattr(event, 'is_all_day', False),  # May not exist
                'registration_required': False,  # Column doesn't exist
                'registration_opens': None,  # Column doesn't exist
                'registration_closes': None,  # Column doesn't exist
                'max_capacity': getattr(event, 'max_capacity', None),  # May not exist
                'allow_waitlist': False,  # Column doesn't exist
                'is_public': True,  # Column doesn't exist - default to public
                'requires_approval': False,  # Column doesn't exist
                'minimum_age': getattr(event, 'minimum_age', None),  # May not exist
                'maximum_age': getattr(event, 'maximum_age', None),  # May not exist
                'required_departments': getattr(event, 'required_departments', None),  # May not exist
                'image_url': image_url,
                'additional_info': event.description,  # Use description as fallback
                'contact_person': getattr(event, 'contact_person', None),  # May not exist
                'contact_email': getattr(event, 'contact_email', None),  # May not exist
                'contact_phone': getattr(event, 'contact_phone', None),  # May not exist
                'price': float(event.price) if hasattr(event, 'price') and event.price else None,
                'requires_payment': getattr(event, 'requires_payment', False),
                'stripe_price_id': getattr(event, 'stripe_price_id', None),
                'registration_count': registration_count,
                'can_register': False,  # Registration not supported
                'is_cancelled': False,  # Column doesn't exist
                'created_at': event.created_at.isoformat(),
                'updated_at': event.updated_at.isoformat()
            })
        
        return jsonify({'events': events_data})
        
    except Exception as e:
        logger.error(f"Error fetching events: {e}", exc_info=True)
        # Return empty events list instead of error to prevent app crashes
        return jsonify({
            'events': [],
            'count': 0,
            'error': str(e)
        }), 200

