@app.route('/api/events/<event_id>/register', methods=['POST'])
def register_for_event(event_id):
    """Register for an event with optional payment"""
    try:
        event = Event.query.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404
        
        data = request.get_json()
        email = data.get('email', '').strip()
        name = data.get('name', '')
        phone = data.get('phone', '')
        guest_count = data.get('guest_count', 0)
        notes = data.get('notes', '')
        payment_intent_id = data.get('payment_intent_id')  # If payment already completed
        
        if not email:
            return jsonify({'error': 'Email is required'}), 400
        
        # Find or create person
        person = Person.query.filter_by(email=email, is_active=True).first()
        if not person:
            # Create person if doesn't exist
            person_id = f"user_{uuid.uuid4().hex[:12]}"
            person = Person(
                id=person_id,
                email=email,
                full_name=name or email.split('@')[0].replace('.', ' ').title(),
                phone=phone,
                campus=event.campus if event.campus != 'all_campuses' else 'Paradise',
                is_active=True
            )
            db.session.add(person)
            db.session.commit()
        else:
            person_id = person.id
        
        # Check if already registered
        existing_registration = EventRegistration.query.filter_by(
            event_id=event_id,
            person_id=person_id
        ).first()
        
        if existing_registration:
            return jsonify({
                'message': 'Already registered for this event',
                'registration': existing_registration.to_dict()
            })
        
        # Check capacity
        status = 'registered'
        if hasattr(event, 'capacity') and event.capacity:
            current_registrations = EventRegistration.query.filter_by(
                event_id=event_id,
                status='registered'
            ).count()
            if current_registrations >= event.capacity:
                status = 'waitlisted'
        
        # Create registration
        registration = EventRegistration(
            event_id=event_id,
            person_id=person_id,
            email=email,
            name=name or person.full_name,
            phone=phone or person.phone,
            status=status,
            guest_count=guest_count,
            notes=notes
        )
        
        # If payment was completed, mark it
        if payment_intent_id:
            registration.notes = (registration.notes or '') + f'\n[Payment Intent: {payment_intent_id}]'
        
        db.session.add(registration)
        db.session.commit()
        
        return jsonify({
            'message': 'Registration successful',
            'registration': registration.to_dict(),
            'event': event.to_dict()
        }), 201
        
    except Exception as e:
        logger.error(f"Error registering for event: {e}", exc_info=True)
        db.session.rollback()
        return jsonify({'error': f'Failed to register: {str(e)}'}), 500

@app.route('/api/events/<event_id>/create-payment-intent', methods=['POST'])
def create_event_payment_intent(event_id):
    """Create Stripe Payment Intent for event registration"""
    try:
        # Import stripe - use same pattern as giving_api
        try:
            import stripe
            if not hasattr(stripe, 'PaymentIntent'):
                logger.error("Stripe.PaymentIntent not available - Stripe module may not be properly loaded")
                raise ImportError("Stripe module not properly loaded")
        except ImportError as e:
            logger.error(f"Failed to import stripe: {e}")
            return jsonify({'error': 'Payment processing unavailable'}), 500
        
        event = Event.query.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404
        
        # Check if event requires payment
        requires_payment = getattr(event, 'requires_payment', False)
        price = getattr(event, 'price', None)
        
        if not requires_payment or not price:
            return jsonify({'error': 'This event does not require payment'}), 400
        
        data = request.get_json()
        email = data.get('email', '').strip()
        guest_count = data.get('guest_count', 0)
        
        if not email:
            return jsonify({'error': 'Email is required'}), 400
        
        # Calculate total amount (price per person * (1 + guest_count))
        total_amount = float(price) * (1 + guest_count)
        amount_cents = int(total_amount * 100)  # Convert to cents
        
        # Get Stripe API key - use same pattern as giving_api
        stripe_key = os.getenv('STRIPE_SECRET_KEY', '').strip()
        if not stripe_key:
            logger.error("STRIPE_SECRET_KEY environment variable not set")
            logger.error("Please set STRIPE_SECRET_KEY in Railway environment variables")
            return jsonify({
                'error': 'Payment processing not configured',
                'details': 'Stripe API key is missing. Please contact support or check server configuration.'
            }), 500
        
        # Always set Stripe API key fresh (in case it got reset) - same as giving_api
        stripe.api_key = stripe_key
        
        # Verify it's set
        if not stripe.api_key:
            logger.error("Stripe API key is None after setting")
            return jsonify({'error': 'Stripe API key configuration failed'}), 500
        
        # Find or create person
        person = Person.query.filter_by(email=email, is_active=True).first()
        customer_email = email
        customer_name = person.full_name if person else email.split('@')[0].replace('.', ' ').title()
        
        # Create payment intent
        try:
            payment_intent = stripe.PaymentIntent.create(
                amount=amount_cents,
                currency='aud',
                description=f'Event Registration: {event.title}',
                metadata={
                    'event_id': str(event_id),
                    'event_title': event.title,
                    'email': email,
                    'guest_count': str(guest_count),
                    'type': 'event_registration'
                },
                receipt_email=email,
                statement_descriptor=f'Event: {event.title[:22]}'  # Max 22 chars
            )
        except stripe.error.StripeError as stripe_error:
            logger.error(f"Stripe API error creating payment intent: {stripe_error}", exc_info=True)
            return jsonify({
                'error': f'Payment processing error: {stripe_error.user_message or str(stripe_error)}',
                'stripe_error_type': stripe_error.__class__.__name__
            }), 500
        
        return jsonify({
            'client_secret': payment_intent.client_secret,
            'payment_intent_id': payment_intent.id,
            'amount': total_amount,
            'amount_cents': amount_cents,
            'currency': 'aud',
            'event': {
                'id': event.id,
                'title': event.title,
                'price': float(price)
            }
        }), 201
        
    except Exception as e:
        logger.error(f"Error creating payment intent: {e}", exc_info=True)
        return jsonify({
            'error': f'Failed to create payment intent: {str(e)}',
            'details': 'Please check server logs for more information'
        }), 500

@app.route('/api/events/<event_id>/registrations', methods=['POST'])
def create_event_registration(event_id):
    """Create a new registration for an event (works with or without login) - Legacy endpoint"""
    # Redirect to new register endpoint
    return register_for_event(event_id)

@app.route('/api/events/<event_id>/rsvp', methods=['POST'])
def rsvp_to_event(event_id):
    """Simple RSVP endpoint for mobile app (Going/Maybe/Not Going) - For free events"""
    try:
        event = Event.query.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404
        
        # Check if event requires payment
        requires_payment = getattr(event, 'requires_payment', False)
        if requires_payment:
            return jsonify({
                'error': 'This event requires payment. Please use /api/events/<event_id>/register endpoint.',
                'requires_payment': True,
                'price': float(getattr(event, 'price', 0))
            }), 400
        
        data = request.get_json()
        rsvp_status = data.get('status', 'going')  # going, maybe, not_going
        
        # Map RSVP status to registration status
        status_map = {
            'going': 'registered',
            'maybe': 'registered',  # Could create a 'maybe' status if needed
            'not_going': 'cancelled'
        }
        registration_status = status_map.get(rsvp_status, 'registered')
        
        # Get person_id from email or person_id in data
        person_id = data.get('person_id')
        email = data.get('email', '').strip()
        
        if not email:
            return jsonify({'error': 'Email is required'}), 400
        
        if not person_id:
            person = Person.query.filter_by(email=email, is_active=True).first()
            if person:
                person_id = person.id
        
        # Check if already registered
        existing_registration = None
        if person_id:
            existing_registration = EventRegistration.query.filter_by(
                event_id=event_id,
                person_id=person_id
            ).first()
        elif email:
            existing_registration = EventRegistration.query.filter_by(
                event_id=event_id,
                email=email
            ).first()
        
        if existing_registration:
            # Update existing registration
            if rsvp_status == 'not_going':
                existing_registration.status = 'cancelled'
            else:
                existing_registration.status = registration_status
            existing_registration.updated_at = datetime.utcnow()
            db.session.commit()
            
            return jsonify({
                'message': 'RSVP updated successfully',
                'registration': existing_registration.to_dict(),
                'rsvp_status': rsvp_status
            })
        
        # Create new registration
        if rsvp_status == 'not_going':
            return jsonify({'message': 'RSVP cancelled', 'rsvp_status': 'not_going'})
        
        # Find or create person
        if not person_id:
            person = Person.query.filter_by(email=email, is_active=True).first()
            if not person:
                person_id = f"user_{uuid.uuid4().hex[:12]}"
                person = Person(
                    id=person_id,
                    email=email,
                    full_name=data.get('name') or email.split('@')[0].replace('.', ' ').title(),
                    phone=data.get('phone', ''),
                    campus=event.campus if event.campus != 'all_campuses' else 'Paradise',
                    is_active=True
                )
                db.session.add(person)
                db.session.commit()
            else:
                person_id = person.id
        
        # Check capacity
        status = registration_status
        if hasattr(event, 'capacity') and event.capacity:
            current_registrations = EventRegistration.query.filter_by(
                event_id=event_id,
                status='registered'
            ).count()
            if current_registrations >= event.capacity:
                status = 'waitlisted'
        
        registration = EventRegistration(
            event_id=event_id,
            person_id=person_id,
            email=email,
            name=data.get('name') or (person.full_name if person else ''),
            phone=data.get('phone') or (person.phone if person else ''),
            status=status,
            guest_count=data.get('guest_count', 0),
            notes=data.get('notes')
        )
        
        db.session.add(registration)
        db.session.commit()
        
        return jsonify({
            'message': 'RSVP successful',
            'registration': registration.to_dict(),
            'rsvp_status': rsvp_status
        }), 201
        
    except Exception as e:
        logger.error(f"Error processing RSVP: {e}", exc_info=True)
        db.session.rollback()
        return jsonify({'error': f'Failed to process RSVP: {str(e)}'}), 500

@app.route('/api/events/registrations/all', methods=['GET'])
@login_required
def get_all_event_registrations():
    """Get all registrations across all events (admin view)"""
    try:
        # Check if user has admin permissions
        if not hasattr(current_user, 'has_permission') or not current_user.has_permission('query_access'):
            return jsonify({'error': 'Insufficient permissions'}), 403
        
        # Get query parameters
        event_id = request.args.get('event_id')
        status = request.args.get('status')
        campus = request.args.get('campus')
        
        query = EventRegistration.query
        
        # Filter by event if specified
        if event_id:
            query = query.filter_by(event_id=event_id)
        
        # Filter by status if specified
        if status:
            query = query.filter_by(status=status)
        
        # Filter by campus if specified
        if campus:
            query = query.join(Event).filter(Event.campus == campus)
        
        registrations = query.order_by(EventRegistration.created_at.desc()).all()
        
        # Build response with event details
        registrations_data = []
        for reg in registrations:
            reg_dict = reg.to_dict()
            event = Event.query.get(reg.event_id)
            if event:
                reg_dict['event'] = {
                    'id': event.id,
                    'title': event.title,
                    'start_time': event.start_time.isoformat() if event.start_time else None,
                    'campus': event.campus,
                    'location': event.location
                }
            registrations_data.append(reg_dict)
        
        return jsonify({
            'registrations': registrations_data,
            'count': len(registrations_data),
            'filters': {
                'event_id': event_id,
                'status': status,
                'campus': campus
            }
        })
        
    except Exception as e:
        logger.error(f"Error fetching all registrations: {e}", exc_info=True)
        return jsonify({'error': f'Failed to fetch registrations: {str(e)}'}), 500

