# ==================== PUSH NOTIFICATIONS ====================

def send_expo_push_notification(push_tokens, title, body, data=None):
    """
    Send push notification via Expo Push Notification Service
    
    Args:
        push_tokens: List of Expo push tokens
        title: Notification title
        body: Notification body
        data: Optional JSON data payload
    
    Returns:
        Tuple of (sent_count, failed_count, errors)
    """
    if not requests:
        logger.error("Requests library not available - cannot send push notifications")
        return 0, len(push_tokens), ["requests library not installed"]
    
    if not push_tokens:
        return 0, 0, []
    
    expo_push_url = "https://exp.host/--/api/v2/push/send"
    
    # Prepare notification payloads
    messages = []
    for token in push_tokens:
        message = {
            "to": token,
            "sound": "default",
            "title": title,
            "body": body,
            "data": data or {},
            "priority": "high",
            "channelId": "default"
        }
        messages.append(message)
    
    try:
        # Send notifications in batches (Expo recommends max 100 per request)
        batch_size = 100
        sent_count = 0
        failed_count = 0
        errors = []
        
        for i in range(0, len(messages), batch_size):
            batch = messages[i:i + batch_size]
            
            response = requests.post(
                expo_push_url,
                headers={
                    "Content-Type": "application/json",
                    "Accept": "application/json",
                    "Accept-Encoding": "gzip, deflate"
                },
                json={"messages": batch},
                timeout=30
            )
            
            if response.status_code == 200:
                result = response.json()
                # Process Expo response
                for receipt in result.get('data', {}).get('results', []):
                    if receipt.get('status') == 'ok':
                        sent_count += 1
                    else:
                        failed_count += 1
                        error_msg = receipt.get('message', 'Unknown error')
                        errors.append(error_msg)
                        logger.warning(f"Push notification failed: {error_msg}")
            else:
                logger.error(f"Expo push API error: {response.status_code} - {response.text}")
                failed_count += len(batch)
                errors.append(f"API error: {response.status_code}")
        
        logger.info(f"Sent {sent_count} push notifications, {failed_count} failed")
        return sent_count, failed_count, errors
        
    except Exception as e:
        logger.error(f"Error sending push notifications: {e}", exc_info=True)
        return 0, len(push_tokens), [str(e)]


@app.route('/api/push-tokens', methods=['POST'])
def save_push_token():
    """Save or update push notification token for a user"""
    try:
        data = request.get_json()
        email = data.get('email')
        push_token = data.get('push_token')
        platform = data.get('platform')
        device_id = data.get('device_id')
        app_version = data.get('app_version')
        
        if not email or not push_token:
            return jsonify({'error': 'Email and push_token are required'}), 400
        
        # Find or create push token record
        token_record = PushNotificationToken.query.filter_by(
            expo_push_token=push_token
        ).first()
        
        # Also try to find by email to update existing token
        if not token_record:
            token_record = PushNotificationToken.query.filter_by(
                email=email.lower(),
                is_active=True
            ).first()
        
        # Get person by email
        person = Person.query.filter_by(email=email.lower()).first()
        if not person:
            return jsonify({'error': 'User not found'}), 404
        
        if token_record:
            # Update existing token
            token_record.person_id = person.id
            token_record.email = email.lower()
            token_record.platform = platform
            token_record.device_id = device_id
            token_record.app_version = app_version
            token_record.is_active = True
            token_record.updated_at = datetime.utcnow()
            logger.info(f"Updated push token for {email}")
        else:
            # Create new token
            token_record = PushNotificationToken(
                person_id=person.id,
                email=email.lower(),
                expo_push_token=push_token,
                platform=platform,
                device_id=device_id,
                app_version=app_version,
                is_active=True
            )
            db.session.add(token_record)
            logger.info(f"Created new push token for {email}")
        
        db.session.commit()
        return jsonify({'success': True, 'message': 'Push token saved successfully'})
        
    except Exception as e:
        logger.error(f"Error saving push token: {e}", exc_info=True)
        db.session.rollback()
        return jsonify({'error': 'Failed to save push token'}), 500


@app.route('/api/notifications/send', methods=['POST'])
@admin_required_json
def send_notification():
    """Send push notification immediately"""
    try:
        data = request.get_json()
        title = data.get('title')
        body = data.get('body')
        notification_data = data.get('data', {})
        target_audience = data.get('target_audience', 'all')
        target_campus = data.get('target_campus')
        target_emails = data.get('target_emails', [])
        target_role = data.get('target_role')
        
        if not title or not body:
            return jsonify({'error': 'Title and body are required'}), 400
        
        # Get push tokens based on target audience
        push_tokens = []
        tokens_query = PushNotificationToken.query.filter_by(is_active=True)
        
        if target_audience == 'all':
            # Send to all active tokens
            tokens = tokens_query.all()
            push_tokens = [t.expo_push_token for t in tokens]
        elif target_audience == 'specific_campus' and target_campus:
            # Send to users from specific campus
            persons = Person.query.filter_by(campus=target_campus, is_active=True).all()
            person_ids = [p.id for p in persons]
            tokens = tokens_query.filter(PushNotificationToken.person_id.in_(person_ids)).all()
            push_tokens = [t.expo_push_token for t in tokens]
        elif target_audience == 'specific_users' and target_emails:
            # Send to specific users
            email_list = [e.lower() for e in target_emails]
            tokens = tokens_query.filter(PushNotificationToken.email.in_(email_list)).all()
            push_tokens = [t.expo_push_token for t in tokens]
        elif target_audience == 'role' and target_role:
            # Get users with specific role (would need to check User model)
            # For now, return error if roles not implemented
            return jsonify({'error': 'Role-based targeting not yet implemented'}), 400
        
        if not push_tokens:
            return jsonify({
                'success': False,
                'error': 'No active push tokens found for target audience',
                'message': 'No users have registered for push notifications yet. Users need to log into the mobile app to register their push tokens.',
                'sent_count': 0,
                'failed_count': 0,
                'total_tokens': 0
            }), 200
        
        # Send notifications
        sent_count, failed_count, errors = send_expo_push_notification(
            push_tokens, title, body, notification_data
        )
        
        # Update last_used_at for successfully sent tokens
        if sent_count > 0:
            tokens = tokens_query.filter(PushNotificationToken.expo_push_token.in_(push_tokens)).all()
            for token in tokens:
                token.last_used_at = datetime.utcnow()
            db.session.commit()
        
        return jsonify({
            'success': True,
            'sent_count': sent_count,
            'failed_count': failed_count,
            'total_tokens': len(push_tokens),
            'errors': errors[:5]  # Return first 5 errors
        })
        
    except Exception as e:
        logger.error(f"Error sending notification: {e}", exc_info=True)
        db.session.rollback()
        return jsonify({'error': 'Failed to send notification'}), 500


@app.route('/api/notifications/schedule', methods=['POST'])
@admin_required_json
def schedule_notification():
    """Schedule a push notification for later"""
    try:
        data = request.get_json()
        title = data.get('title')
        body = data.get('body')
        notification_data = data.get('data', {})
        scheduled_for_str = data.get('scheduled_for')
        target_audience = data.get('target_audience', 'all')
        target_campus = data.get('target_campus')
        target_emails = data.get('target_emails', [])
        target_role = data.get('target_role')
        
        if not title or not body:
            return jsonify({'error': 'Title and body are required'}), 400
        
        if not scheduled_for_str:
            return jsonify({'error': 'scheduled_for is required'}), 400
        
        # Parse scheduled_for datetime
        try:
            scheduled_for = datetime.fromisoformat(scheduled_for_str.replace('Z', '+00:00'))
        except ValueError:
            return jsonify({'error': 'Invalid scheduled_for format. Use ISO 8601 format'}), 400
        
        # Validate scheduled_for is in the future
        if scheduled_for <= datetime.utcnow():
            return jsonify({'error': 'scheduled_for must be in the future'}), 400
        
        # Create scheduled notification
        scheduled_notification = ScheduledNotification(
            title=title,
            body=body,
            data=json.dumps(notification_data) if notification_data else None,
            target_audience=target_audience,
            target_campus=target_campus,
            target_emails=json.dumps(target_emails) if target_emails else None,
            target_role=target_role,
            scheduled_for=scheduled_for,
            status='pending',
            created_by=current_user.email if hasattr(current_user, 'email') else 'unknown'
        )
        
        db.session.add(scheduled_notification)
        db.session.commit()
        
        logger.info(f"Scheduled notification {scheduled_notification.id} for {scheduled_for}")
        
        return jsonify({
            'success': True,
            'notification': scheduled_notification.to_dict()
        }), 201
        
    except Exception as e:
        logger.error(f"Error scheduling notification: {e}", exc_info=True)
        db.session.rollback()
        return jsonify({'error': 'Failed to schedule notification'}), 500


@app.route('/api/notifications/scheduled', methods=['GET'])
@admin_required_json
def get_scheduled_notifications():
    """Get list of scheduled notifications"""
    try:
        status = request.args.get('status', 'all')  # all, pending, sent, failed, cancelled
        limit = request.args.get('limit', 50, type=int)
        
        query = ScheduledNotification.query
        
        if status != 'all':
            query = query.filter_by(status=status)
        
        notifications = query.order_by(ScheduledNotification.scheduled_for.desc()).limit(limit).all()
        
        return jsonify({
            'success': True,
            'notifications': [n.to_dict() for n in notifications]
        })
        
    except Exception as e:
        logger.error(f"Error getting scheduled notifications: {e}", exc_info=True)
        return jsonify({'error': 'Failed to get scheduled notifications'}), 500


@app.route('/api/notifications/scheduled/<int:notification_id>', methods=['DELETE'])
@admin_required_json
def cancel_scheduled_notification(notification_id):
    """Cancel a scheduled notification"""
    try:
        notification = ScheduledNotification.query.get_or_404(notification_id)
        
        if notification.status != 'pending':
            return jsonify({'error': 'Only pending notifications can be cancelled'}), 400
        
        notification.status = 'cancelled'
        db.session.commit()
        
        return jsonify({'success': True, 'message': 'Notification cancelled'})
        
    except Exception as e:
        logger.error(f"Error cancelling notification: {e}", exc_info=True)
        db.session.rollback()
        return jsonify({'error': 'Failed to cancel notification'}), 500


@app.route('/api/notifications/stats', methods=['GET'])
@admin_required_json
def get_notification_stats():
    """Get statistics about push notifications"""
    try:
        total_tokens = PushNotificationToken.query.filter_by(is_active=True).count()
        platform_stats = db.session.query(
            PushNotificationToken.platform,
            db.func.count(PushNotificationToken.id)
        ).filter_by(is_active=True).group_by(PushNotificationToken.platform).all()
        
        scheduled_pending = ScheduledNotification.query.filter_by(status='pending').count()
        scheduled_sent = ScheduledNotification.query.filter_by(status='sent').count()
        
        return jsonify({
            'success': True,
            'stats': {
                'total_active_tokens': total_tokens,
                'platform_breakdown': {platform: count for platform, count in platform_stats if platform},
                'scheduled_pending': scheduled_pending,
                'scheduled_sent': scheduled_sent
            }
        })
        
    except Exception as e:
        logger.error(f"Error getting notification stats: {e}", exc_info=True)
        return jsonify({'error': 'Failed to get notification stats'}), 500


@app.route('/api/notifications/test', methods=['POST'])
@admin_required_json
def test_notification():
    """Test sending a notification to a specific Expo push token"""
    try:
        data = request.get_json()
        expo_push_token = data.get('expo_push_token')
        title = data.get('title', 'Test Notification')
        body = data.get('body', 'This is a test notification from Futures PULSE')
        data_payload = data.get('data', {})
        
        if not expo_push_token:
            return jsonify({'error': 'expo_push_token is required'}), 400
        
        # Validate token format (Expo push tokens start with ExponentPushToken or ExpoPushToken)
        if not (expo_push_token.startswith('ExponentPushToken[') or 
                expo_push_token.startswith('ExpoPushToken[') or
                'ExponentPushToken' in expo_push_token or
                'ExpoPushToken' in expo_push_token):
            return jsonify({
                'error': 'Invalid Expo push token format. Token should start with ExponentPushToken[ or ExpoPushToken['
            }), 400
        
        # Send test notification
        sent_count, failed_count, errors = send_expo_push_notification(
            [expo_push_token], 
            title, 
            body, 
            data_payload
        )
        
        if sent_count > 0:
            return jsonify({
                'success': True,
                'message': 'Test notification sent successfully!',
                'sent_count': sent_count,
                'failed_count': failed_count,
                'token': expo_push_token[:30] + '...'  # Show partial token for confirmation
            })
        else:
            return jsonify({
                'success': False,
                'error': 'Failed to send test notification',
                'failed_count': failed_count,
                'errors': errors[:3]  # Return first 3 errors
            }), 400
        
    except Exception as e:
        logger.error(f"Error sending test notification: {e}", exc_info=True)
        return jsonify({'error': f'Failed to send test notification: {str(e)}'}), 500


# ============================================================================
# PEOPLE SECTION API ENDPOINTS
# ============================================================================

@app.route('/api/people/families', methods=['GET'])
@login_required
def get_families():
    """Get families grouped by household with comprehensive metrics"""
    try:
        if not current_user.has_permission('query_access'):
            return jsonify({'error': 'Insufficient permissions'}), 403
        
        from datetime import datetime, timedelta, date
        from sqlalchemy import text
        from sqlalchemy.exc import OperationalError
        
        # Check if new Person columns exist
        try:
            table_info = db.session.execute(text("PRAGMA table_info(persons)")).fetchall()
            existing_columns = [row[1] for row in table_info]
            has_family_id = 'family_id' in existing_columns
            has_new_christian_fields = all(col in existing_columns for col in ['is_new_christian', 'new_christian_date'])
            # Check for all new columns that might be in the Person model
            required_new_columns = [
                'family_id', 'is_new_christian', 'new_christian_date', 
                'follow_up_status', 'service_attended', 'is_new_person', 'new_person_date'
            ]
            has_all_new_columns = all(col in existing_columns for col in required_new_columns)
        except Exception as e:
            logger.warning(f"Could not check table schema: {e}")
            has_family_id = False
            has_new_christian_fields = False
            has_all_new_columns = False
        
        # Get query parameters
        campus_filter = request.args.get('campus', None)
        search = request.args.get('search', '').strip()
        health_filter = request.args.get('health', None)  # healthy, watch, at_risk, critical
        has_kids = request.args.get('has_kids', None)  # true/false
        has_youth = request.args.get('has_youth', None)  # true/false
        
        # Get all active persons - use raw SQL if columns don't exist to avoid errors
        # Must use raw SQL if ANY new columns are missing, because ORM will try to select all model columns
        if not has_all_new_columns:
            # Use raw SQL to select only existing columns
            base_columns = [
                'id', 'full_name', 'preferred_name', 'email', 'phone', 'campus', 
                'department', 'connect_group', 'dream_team_roles', 'birthday', 
                'pastoral_notes', 'tags', 'is_active', 'created_at', 'updated_at',
                'dna_completed', 'baptised_on', 'filled_holy_spirit', 'rise_attended', 'first_served_on'
            ]
            # Add new columns only if they exist
            optional_columns = ['family_id', 'is_new_christian', 'new_christian_date', 
                               'follow_up_status', 'service_attended', 'is_new_person', 'new_person_date']
            for col in optional_columns:
                if col in existing_columns:
                    base_columns.append(col)
            
            where_clauses = ["is_active = 1"]
            params = {}
            
            if campus_filter and campus_filter != 'all_campuses':
                where_clauses.append("campus = :campus")
                params['campus'] = campus_filter
            
            if search:
                where_clauses.append("(full_name LIKE :search OR email LIKE :search OR preferred_name LIKE :search)")
                params['search'] = f"%{search}%"
            
            sql = f"SELECT {', '.join(base_columns)} FROM persons WHERE {' AND '.join(where_clauses)}"
            rows = db.session.execute(text(sql), params).fetchall()
            
            # Convert rows to Person objects
            persons = []
            for row in rows:
                person_dict = dict(zip(base_columns, row))
                person = Person()
                for key, value in person_dict.items():
                    setattr(person, key, value)
                persons.append(person)
        else:
            # Use normal ORM query if columns exist
            query = Person.query.filter_by(is_active=True)
            if campus_filter and campus_filter != 'all_campuses':
                query = query.filter(Person.campus == campus_filter)
            if search:
                search_term = f"%{search}%"
                query = query.filter(
                    db.or_(
                        Person.full_name.ilike(search_term),
                        Person.email.ilike(search_term),
                        Person.preferred_name.ilike(search_term)
                    )
                )
            
            persons = query.all()
        
        # Group by family/household using family_id if available, otherwise fallback to email/last name
        family_map = {}
        person_id_to_family = {}
        
        for person in persons:
            try:
                # Use family_id if available, otherwise use fallback grouping
                # Always try to get family_id if the column exists (check dynamically)
                family_id = None
                if has_family_id or 'family_id' in existing_columns:
                    family_id = getattr(person, 'family_id', None)
                
                if family_id:
                    family_key = family_id
                else:
                    # Fallback: use email domain or last name
                    if person.email:
                        email_parts = person.email.split('@')
                        if len(email_parts) == 2:
                            family_key = f"{email_parts[0].split('+')[0]}@{email_parts[1]}"
                        else:
                            last_name = person.full_name.split()[-1] if person.full_name else 'unknown'
                            family_key = f"family_{last_name}"
                    else:
                        last_name = person.full_name.split()[-1] if person.full_name else 'unknown'
                        family_key = f"family_{last_name}"
                
                person_id_to_family[person.id] = family_key
                
                if family_key not in family_map:
                    family_map[family_key] = {
                        'id': family_key,
                        'family_name': None,  # Will be set from member names
                        'members': [],
                        'household_heartbeat': 0,
                        'heartbeat_status': 'critical',
                        'attendance_together': 0,
                        'attendance_timeline': [],
                        'attendance_drifting': False,
                        'groups_involvement': [],
                        'serving_patterns': [],
                        'giving_rhythm': 'none',  # none, occasional, regular
                        'parent_giving': False,
                        'new_people_count': 0,
                        'new_christians_count': 0,
                        'care_cases': [],
                        'pastoral_notes': [],
                        'ai_summary': None,
                        'next_steps': [],
                        'assigned_leader': None,
                        'campus': None,
                        'last_attended_together': None
                    }
                
                # Get heartbeat from snapshot
                heartbeat_score = 50
                heartbeat_status = 'critical'
                try:
                    snapshot = HeartbeatSnapshot.query.filter_by(
                        person_id=person.id
                    ).order_by(HeartbeatSnapshot.calculated_at.desc()).first()
                    if snapshot:
                        heartbeat_score = getattr(snapshot, 'total_score', 50)
                        heartbeat_status = getattr(snapshot, 'status', 'critical')
                except OperationalError as e:
                    # Table might not exist
                    logger.warning(f"HeartbeatSnapshot table may not exist: {e}")
                except Exception as e:
                    logger.warning(f"Error getting heartbeat snapshot for {person.id}: {e}")
                
                # Determine role
                department = getattr(person, 'department', '') or ''
                if department:
                    if 'Kids' in department:
                        role = 'child'
                    elif 'Youth' in department:
                        role = 'youth'
                    else:
                        role = 'parent'
                else:
                    # Infer from age if birthday available
                    role = 'parent'  # Default
                
                # Get connect group info
                connect_group_name = None
                person_connect_group = getattr(person, 'connect_group', None)
                if person_connect_group:
                    try:
                        group = ConnectGroup.query.filter_by(id=person_connect_group, is_active=True).first()
                        if group:
                            connect_group_name = group.name
                    except Exception as e:
                        logger.warning(f"Error getting connect group for {person.id}: {e}")
                
                # Safely get engagement profile pulse_status
                pulse_status = 'red'
                try:
                    if hasattr(person, 'engagement_profile') and person.engagement_profile:
                        pulse_status = person.engagement_profile.pulse_status or 'red'
                except Exception as e:
                    logger.warning(f"Error getting engagement profile for {person.id}: {e}")
                
                # Safely serialize dates
                def safe_date_iso(date_val):
                    if not date_val:
                        return None
                    if isinstance(date_val, str):
                        return date_val
                    try:
                        return date_val.isoformat()
                    except:
                        return None
                
                member_data = {
                    'id': person.id,
                    'name': person.preferred_name or person.full_name,
                    'full_name': person.full_name,
                    'email': person.email,
                    'phone': person.phone,
                    'role': role,
                    'department': department,
                    'heartbeat_score': max(0, min(100, heartbeat_score)),
                    'heartbeat_status': heartbeat_status,
                    'pulse_status': pulse_status,
                    'connect_group': connect_group_name or person_connect_group,
                    'is_new_christian': getattr(person, 'is_new_christian', False) if has_new_christian_fields else False,
                    'new_christian_date': safe_date_iso(getattr(person, 'new_christian_date', None)) if has_new_christian_fields else None,
                    'baptised_on': safe_date_iso(getattr(person, 'baptised_on', None)),
                    'created_at': safe_date_iso(getattr(person, 'created_at', None)),
                    'has_family_id': bool(family_id)
                }
                
                family_map[family_key]['members'].append(member_data)
                
                # Set campus from first member
                if not family_map[family_key]['campus']:
                    family_map[family_key]['campus'] = getattr(person, 'campus', None)
            except Exception as e:
                logger.warning(f"Error processing person {person.id} for families: {e}")
                continue
        
        # Calculate comprehensive household metrics
        families = []
        twelve_weeks_ago = date.today() - timedelta(weeks=12)
        
        for family_key, family_data in family_map.items():
            # Only include families with multiple members OR single members with family_id set
            if len(family_data['members']) > 1 or (len(family_data['members']) == 1 and family_data['members'][0].get('has_family_id')):
                # Set family name using last names (e.g., "Turner Family", "Rawlins Family")
                def get_last_name(full_name):
                    """Extract last name from full name"""
                    if not full_name:
                        return None
                    parts = full_name.strip().split()
                    if len(parts) > 1:
                        return parts[-1]  # Last word is typically last name
                    return None
                
                # Get last names from all members
                last_names = []
                for member in family_data['members']:
                    full_name = member.get('full_name') or member.get('name', '')
                    last_name = get_last_name(full_name)
                    if last_name and last_name not in last_names:
                        last_names.append(last_name)
                
                # If we have last names, use them (e.g., "Turner Family" or "Turner-Smith Family")
                if last_names:
                    if len(last_names) == 1:
                        family_data['family_name'] = f"{last_names[0]} Family"
                    else:
                        # Multiple last names (e.g., married couple with different names)
                        family_data['family_name'] = f"{'-'.join(last_names)} Family"
                else:
                    # Fallback: use first names if no last names found
                    parents = [m for m in family_data['members'] if m['role'] == 'parent']
                    if parents:
                        family_data['family_name'] = ', '.join([p['name'] for p in parents]) + ' Family'
                    else:
                        family_data['family_name'] = ', '.join([m['name'] for m in family_data['members'][:2]]) + ' Family'
                
                # Calculate average household heartbeat
                heartbeats = [m['heartbeat_score'] for m in family_data['members']]
                family_data['household_heartbeat'] = int(sum(heartbeats) / len(heartbeats)) if heartbeats else 0
                
                # Determine overall heartbeat status
                if family_data['household_heartbeat'] >= 80:
                    family_data['heartbeat_status'] = 'healthy'
                elif family_data['household_heartbeat'] >= 60:
                    family_data['heartbeat_status'] = 'watch'
                elif family_data['household_heartbeat'] >= 40:
                    family_data['heartbeat_status'] = 'at_risk'
                else:
                    family_data['heartbeat_status'] = 'critical'
                
                # Get all family member IDs
                family_member_ids = [m['id'] for m in family_data['members']]
                
                # Calculate attendance together
                try:
                    # Skip if no family members
                    if not family_member_ids:
                        family_data['attendance_together'] = 0
                        family_data['attendance_timeline'] = []
                    else:
                        # Get attendance events for all family members in last 12 weeks
                        attendance_events = AttendanceEvent.query.filter(
                            AttendanceEvent.person_id.in_(family_member_ids),
                            AttendanceEvent.created_at >= datetime.combine(twelve_weeks_ago, datetime.min.time())
                        ).order_by(AttendanceEvent.created_at.desc()).all()
                    
                        # Group by date
                        attendance_by_date = {}
                        for event in attendance_events:
                            if event and hasattr(event, 'created_at') and event.created_at:
                                event_date = event.created_at.date() if hasattr(event.created_at, 'date') else event.created_at
                                if event_date not in attendance_by_date:
                                    attendance_by_date[event_date] = set()
                                attendance_by_date[event_date].add(event.person_id)
                        
                        # Calculate attendance together percentage
                        total_services = len(attendance_by_date)
                        together_count = sum(1 for attendees in attendance_by_date.values() if len(attendees) > 1)
                        family_data['attendance_together'] = int((together_count / total_services * 100)) if total_services > 0 else 0
                        
                        # Build attendance timeline
                        timeline = []
                        for event_date, attendees in sorted(attendance_by_date.items(), reverse=True)[:20]:  # Last 20 services
                            timeline.append({
                                'date': event_date.isoformat() if hasattr(event_date, 'isoformat') else str(event_date),
                                'members_present': list(attendees),
                                'count': len(attendees),
                                'all_present': len(attendees) == len(family_member_ids)
                            })
                        family_data['attendance_timeline'] = timeline
                        
                        # Find last attended together
                        for event_date, attendees in sorted(attendance_by_date.items(), reverse=True):
                            if len(attendees) > 1:
                                family_data['last_attended_together'] = event_date.isoformat() if hasattr(event_date, 'isoformat') else str(event_date)
                                break
                except OperationalError as e:
                    logger.warning(f"AttendanceEvent table may not exist: {e}")
                    family_data['attendance_together'] = 0
                    family_data['attendance_timeline'] = []
                except Exception as e:
                    logger.warning(f"Error calculating attendance for family {family_key}: {e}")
                    family_data['attendance_together'] = 0
                    family_data['attendance_timeline'] = []
                
                # Get groups involvement
                groups = set()
                for member in family_data['members']:
                    if member.get('connect_group'):
                        groups.add(member['connect_group'])
                family_data['groups_involvement'] = list(groups)
                
                # Get serving patterns
                try:
                    if not family_member_ids:
                        family_data['serving_patterns'] = []
                    else:
                        serving_assignments = ServingAssignment.query.filter(
                            ServingAssignment.person_id.in_(family_member_ids),
                            ServingAssignment.created_at >= datetime.combine(twelve_weeks_ago, datetime.min.time())
                        ).order_by(ServingAssignment.created_at.desc()).limit(20).all()
                    
                        serving_patterns = []
                        for assignment in serving_assignments:
                            if assignment:
                                serving_patterns.append({
                                    'person_id': getattr(assignment, 'person_id', None),
                                    'person_name': next((m['name'] for m in family_data['members'] if m['id'] == getattr(assignment, 'person_id', None)), 'Unknown'),
                                    'role': getattr(assignment, 'role', ''),
                                    'team_name': getattr(assignment, 'team_name', ''),
                                    'date': assignment.created_at.isoformat() if hasattr(assignment, 'created_at') and assignment.created_at else None
                                })
                        family_data['serving_patterns'] = serving_patterns
                except OperationalError as e:
                    logger.warning(f"ServingAssignment table may not exist: {e}")
                    family_data['serving_patterns'] = []
                except Exception as e:
                    logger.warning(f"Error getting serving patterns for family {family_key}: {e}")
                    family_data['serving_patterns'] = []
                
                # Get giving rhythm
                try:
                    if not family_member_ids:
                        family_data['giving_rhythm'] = 'none'
                        family_data['parent_giving'] = False
                    else:
                        giving_transactions = GivingTransaction.query.filter(
                            GivingTransaction.person_id.in_(family_member_ids),
                            GivingTransaction.status == 'completed',
                            GivingTransaction.created_at >= datetime.combine(twelve_weeks_ago, datetime.min.time())
                        ).order_by(GivingTransaction.created_at.desc()).all()
                    
                        if len(giving_transactions) >= 8:
                            family_data['giving_rhythm'] = 'regular'
                            family_data['parent_giving'] = True
                        elif len(giving_transactions) >= 3:
                            family_data['giving_rhythm'] = 'occasional'
                            family_data['parent_giving'] = True
                        elif len(giving_transactions) > 0:
                            family_data['giving_rhythm'] = 'occasional'
                            family_data['parent_giving'] = True
                        else:
                            family_data['giving_rhythm'] = 'none'
                            family_data['parent_giving'] = False
                except OperationalError as e:
                    logger.warning(f"GivingTransaction table may not exist: {e}")
                    family_data['giving_rhythm'] = 'none'
                    family_data['parent_giving'] = False
                except Exception as e:
                    logger.warning(f"Error getting giving data for family {family_key}: {e}")
                    family_data['giving_rhythm'] = 'none'
                    family_data['parent_giving'] = False
                
                # Count new people and new Christians
                try:
                    thirty_days_ago = datetime.utcnow() - timedelta(days=30)
                    two_years_ago = date.today() - timedelta(days=730)
                    
                    new_people = []
                    for m in family_data['members']:
                        try:
                            if m.get('created_at'):
                                created_date = m['created_at']
                                created_dt = None
                                
                                if isinstance(created_date, datetime):
                                    created_dt = created_date
                                elif isinstance(created_date, date):
                                    created_dt = datetime.combine(created_date, datetime.min.time())
                                elif isinstance(created_date, str):
                                    # Handle different date formats
                                    # ISO format: "2024-01-01T05:59:22" or "2024-01-01T05:59:22.071364"
                                    if 'T' in created_date:
                                        created_date = created_date.split('T')[0]
                                    # SQL datetime format: "2024-01-01 05:59:22.071364"
                                    elif ' ' in created_date:
                                        created_date = created_date.split(' ')[0]
                                    # Parse as date
                                    created_dt = datetime.strptime(created_date, '%Y-%m-%d')
                                
                                if created_dt and created_dt >= thirty_days_ago:
                                    new_people.append(m)
                        except Exception as date_error:
                            logger.warning(f"Error parsing created_at for member {m.get('id')}: {date_error}")
                            continue
                    
                    new_christians = []
                    for m in family_data['members']:
                        try:
                            if m.get('is_new_christian'):
                                new_christians.append(m)
                            elif m.get('baptised_on'):
                                baptised_date = m['baptised_on']
                                baptised_d = None
                                
                                if isinstance(baptised_date, date):
                                    baptised_d = baptised_date
                                elif isinstance(baptised_date, datetime):
                                    baptised_d = baptised_date.date()
                                elif isinstance(baptised_date, str):
                                    # Handle different date formats
                                    # ISO format: "2024-01-01T05:59:22"
                                    if 'T' in baptised_date:
                                        baptised_date = baptised_date.split('T')[0]
                                    # SQL datetime format: "2024-01-01 05:59:22.071364"
                                    elif ' ' in baptised_date:
                                        baptised_date = baptised_date.split(' ')[0]
                                    # Parse as date
                                    try:
                                        baptised_d = date.fromisoformat(baptised_date)
                                    except ValueError:
                                        # Fallback to strptime if fromisoformat fails
                                        baptised_d = datetime.strptime(baptised_date, '%Y-%m-%d').date()
                                
                                if baptised_d and baptised_d >= two_years_ago:
                                    new_christians.append(m)
                        except Exception as date_error:
                            logger.warning(f"Error parsing new Christian date for member {m.get('id')}: {date_error}")
                            continue
                except Exception as e:
                    logger.warning(f"Error counting new people/Christians for family {family_key}: {e}")
                    new_people = []
                    new_christians = []
                
                family_data['new_people_count'] = len(new_people)
                family_data['new_christians_count'] = len(new_christians)
                
                # Get care cases
                try:
                    if not family_member_ids:
                        family_data['care_cases'] = []
                    else:
                        care_cases = CareCase.query.filter(
                            CareCase.person_id.in_(family_member_ids),
                            CareCase.status.in_(['open', 'in_progress'])
                        ).all()
                    
                        family_data['care_cases'] = [{
                            'id': getattr(case, 'id', None),
                            'person_id': getattr(case, 'person_id', None),
                            'person_name': next((m['name'] for m in family_data['members'] if m['id'] == getattr(case, 'person_id', None)), 'Unknown'),
                            'priority': getattr(case, 'priority', 'medium'),
                            'status': getattr(case, 'status', 'open'),
                            'notes': (getattr(case, 'notes', '') or '')[:100] if getattr(case, 'notes', None) else None
                        } for case in care_cases]
                except OperationalError as e:
                    logger.warning(f"CareCase table may not exist: {e}")
                    family_data['care_cases'] = []
                except Exception as e:
                    logger.warning(f"Error getting care cases for family {family_key}: {e}")
                    family_data['care_cases'] = []
                
                # Collect pastoral notes
                pastoral_notes = []
                for member in family_data['members']:
                    person_obj = next((p for p in persons if p.id == member['id']), None)
                    if person_obj and person_obj.pastoral_notes:
                        pastoral_notes.append({
                            'person_id': member['id'],
                            'person_name': member['name'],
                            'notes': person_obj.pastoral_notes[:200]  # Truncate for list view
                        })
                family_data['pastoral_notes'] = pastoral_notes
                
                # Generate AI summary (placeholder - can be enhanced later)
                if family_data['household_heartbeat'] >= 80:
                    family_data['ai_summary'] = f"The {family_data['family_name']} family is healthy and engaged. All members are active in church life."
                elif family_data['household_heartbeat'] >= 60:
                    family_data['ai_summary'] = f"The {family_data['family_name']} family is generally stable but may need some encouragement."
                elif family_data['household_heartbeat'] >= 40:
                    family_data['ai_summary'] = f"The {family_data['family_name']} family is showing signs of disengagement and may need pastoral follow-up."
                else:
                    family_data['ai_summary'] = f"The {family_data['family_name']} family requires immediate pastoral attention."
                
                # Generate next steps (placeholder - can be enhanced with AI)
                next_steps = []
                if family_data['new_people_count'] > 0:
                    next_steps.append({
                        'type': 'follow_up',
                        'title': 'Follow up with new family members',
                        'description': f"{family_data['new_people_count']} new member(s) joined in the last 30 days"
                    })
                if family_data['new_christians_count'] > 0:
                    next_steps.append({
                        'type': 'discipleship',
                        'title': 'Support new Christians',
                        'description': f"{family_data['new_christians_count']} new Christian(s) in family need discipleship"
                    })
                if family_data['attendance_together'] < 50:
                    next_steps.append({
                        'type': 'engagement',
                        'title': 'Encourage family attendance',
                        'description': 'Family members are not attending together regularly'
                    })
                if family_data['household_heartbeat'] < 50:
                    next_steps.append({
                        'type': 'care',
                        'title': 'Pastoral check-in needed',
                        'description': 'Family health score is low, consider reaching out'
                    })
                family_data['next_steps'] = next_steps
                
                # Check for attendance drifting
                low_heartbeat_members = [m for m in family_data['members'] if m['heartbeat_score'] < 50]
                family_data['attendance_drifting'] = len(low_heartbeat_members) > 0 or family_data['attendance_together'] < 30
                
                # Apply filters
                if health_filter:
                    if health_filter == 'healthy' and family_data['heartbeat_status'] != 'healthy':
                        continue
                    elif health_filter == 'watch' and family_data['heartbeat_status'] != 'watch':
                        continue
                    elif health_filter == 'at_risk' and family_data['heartbeat_status'] != 'at_risk':
                        continue
                    elif health_filter == 'critical' and family_data['heartbeat_status'] != 'critical':
                        continue
                
                if has_kids == 'true':
                    has_kids_members = any(m['role'] == 'child' or 'Kids' in (m.get('department') or '') for m in family_data['members'])
                    if not has_kids_members:
                        continue
                
                if has_youth == 'true':
                    has_youth_members = any('Youth' in (m.get('department') or '') for m in family_data['members'])
                    if not has_youth_members:
                        continue
                
                families.append(family_data)
        
        # Sort by household heartbeat (highest first)
        families.sort(key=lambda f: f['household_heartbeat'], reverse=True)
        
        return jsonify({
            'families': families,
            'total': len(families)
        })
        
    except Exception as e:
        logger.error(f"Error fetching families: {e}", exc_info=True)
        import traceback
        error_details = traceback.format_exc()
        logger.error(f"Full traceback: {error_details}")
        return jsonify({'error': 'Failed to fetch families', 'details': str(e)}), 500


@app.route('/api/persons/<person_id>/family', methods=['GET'])
@login_required
def get_person_family(person_id):
    """Get family members for a person"""
    try:
        if not current_user.has_permission('query_access'):
            return jsonify({'error': 'Insufficient permissions'}), 403
        
        person = Person.query.get(person_id)
        if not person:
            return jsonify({'error': 'Person not found'}), 404
        
        family_id = getattr(person, 'family_id', None)
        if not family_id:
            return jsonify({
                'person_id': person_id,
                'family_id': None,
                'members': [],
                'has_family': False
            })
        
        # Get all family members
        family_members = Person.query.filter_by(family_id=family_id, is_active=True).all()
        
        # Safely convert members to dict
        members_list = []
        for m in family_members:
            try:
                members_list.append(m.to_dict())
            except Exception as member_error:
                logger.warning(f"Error converting member {m.id} to dict: {member_error}")
                # Fallback: create basic dict
                try:
                    members_list.append({
                        'id': getattr(m, 'id', None),
                        'full_name': getattr(m, 'full_name', 'Unknown'),
                        'preferred_name': getattr(m, 'preferred_name', None),
                        'email': getattr(m, 'email', None),
                        'phone': getattr(m, 'phone', None),
                        'campus': getattr(m, 'campus', None),
                        'department': getattr(m, 'department', None),
                    })
                except Exception as fallback_error:
                    logger.error(f"Error in fallback dict creation for member {m.id}: {fallback_error}")
                    continue
        
        return jsonify({
            'person_id': person_id,
            'family_id': family_id,
            'members': members_list,
            'has_family': True
        })
    except Exception as e:
        logger.error(f"Error fetching person family: {e}", exc_info=True)
        import traceback
        error_details = traceback.format_exc()
        logger.error(f"Full traceback: {error_details}")
        return jsonify({'error': 'Failed to fetch family', 'details': str(e)}), 500


@app.route('/api/persons/<person_id>/family/create', methods=['POST'])
@login_required
def create_family_for_person(person_id):
    """Create a new family and assign person to it"""
    try:
        logger.info(f"Creating family for person_id: {person_id}")
        
        if not current_user.has_permission('edit_access'):
            logger.warning(f"User {current_user.id} does not have edit_access permission")
            return jsonify({'error': 'Insufficient permissions'}), 403
        
        from sqlalchemy import text
        from sqlalchemy.exc import OperationalError
        
        # URL decode person_id in case it was encoded (Flask should handle this, but be safe)
        from urllib.parse import unquote
        person_id_decoded = unquote(person_id)
        if person_id_decoded != person_id:
            logger.info(f"Decoded person_id from '{person_id}' to '{person_id_decoded}'")
            person_id = person_id_decoded
        
        # Check if family_id column exists, and create it if it doesn't
        try:
            table_info = db.session.execute(text("PRAGMA table_info(persons)")).fetchall()
            existing_columns = [row[1] for row in table_info]
            has_family_id = 'family_id' in existing_columns
        except Exception as e:
            logger.warning(f"Could not check table schema: {e}")
            has_family_id = False
        
        # Auto-create all missing columns from migration 035
        # Include ALL columns that might be in the Person model
        columns_to_add = [
            ('family_id', 'TEXT'),
            ('is_new_christian', 'INTEGER DEFAULT 0'),
            ('new_christian_date', 'DATE'),
            ('follow_up_status', 'TEXT'),
            ('service_attended', 'TEXT'),
            ('is_new_person', 'INTEGER DEFAULT 0'),
            ('new_person_date', 'DATE')
        ]
        
        missing_columns = [col for col in columns_to_add if col[0] not in existing_columns]
        
        if missing_columns:
            logger.warning(f"Missing columns detected: {[col[0] for col in missing_columns]} - attempting to create them automatically")
            try:
                for col_name, col_type in missing_columns:
                    try:
                        db.session.execute(text(f"ALTER TABLE persons ADD COLUMN {col_name} {col_type}"))
                        logger.info(f"Successfully added {col_name} column to persons table")
                    except OperationalError as alter_error:
                        error_msg = str(alter_error).lower()
                        if 'duplicate column' in error_msg or 'already exists' in error_msg:
                            logger.info(f"{col_name} column already exists (race condition)")
                        else:
                            logger.error(f"Failed to add {col_name} column: {alter_error}")
                            raise
                
                db.session.commit()
                logger.info("Successfully added all missing columns to persons table")
                # Re-check after adding columns to ensure they all exist
                table_info = db.session.execute(text("PRAGMA table_info(persons)")).fetchall()
                existing_columns = [row[1] for row in table_info]
                has_family_id = 'family_id' in existing_columns
                
                # Verify all required columns now exist
                all_required = all(col[0] in existing_columns for col in columns_to_add)
                if not all_required:
                    missing = [col[0] for col in columns_to_add if col[0] not in existing_columns]
                    logger.error(f"Some columns still missing after creation: {missing}")
            except OperationalError as alter_error:
                error_msg = str(alter_error).lower()
                logger.error(f"Failed to add columns: {alter_error}")
                db.session.rollback()
                return jsonify({
                    'error': 'Database migration needed',
                    'details': 'Some required columns are missing and could not be created automatically. Please run migration 035_add_people_section_fields.sql',
                    'person_id': person_id,
                    'database_error': str(alter_error)
                }), 400
            except Exception as alter_error:
                logger.error(f"Unexpected error adding columns: {alter_error}")
                db.session.rollback()
                return jsonify({
                    'error': 'Database migration needed',
                    'details': 'Some required columns are missing and could not be created. Please run migration 035_add_people_section_fields.sql',
                    'person_id': person_id
                }), 400
        
        if not has_family_id:
            logger.error(f"family_id column still missing after auto-creation attempt")
            return jsonify({
                'error': 'Family feature not available',
                'details': 'The family_id column does not exist and could not be created automatically. Please run migration 035_add_people_section_fields.sql',
                'person_id': person_id
            }), 400
        
        # Verify all required columns exist before querying (to avoid SQLAlchemy errors)
        # Check for ALL columns that might be in the Person model
        required_columns = ['family_id', 'is_new_christian', 'new_christian_date', 'follow_up_status', 'service_attended', 'is_new_person', 'new_person_date']
        missing_required = [col for col in required_columns if col not in existing_columns]
        if missing_required:
            logger.error(f"Required columns still missing: {missing_required}")
            return jsonify({
                'error': 'Database schema incomplete',
                'details': f'Some required columns are missing: {", ".join(missing_required)}. Please run migration 035_add_people_section_fields.sql',
                'person_id': person_id,
                'missing_columns': missing_required
            }), 400
        
        logger.info(f"Looking up person with id: '{person_id}'")
        # Use raw SQL to query person to avoid SQLAlchemy trying to select all model columns
        # This is safer even after creating columns, as there might be other model columns we haven't created yet
        try:
            sql = f"SELECT * FROM persons WHERE id = :person_id"
            result = db.session.execute(text(sql), {'person_id': person_id}).fetchone()
            if not result:
                logger.warning(f"Person not found with id '{person_id}'")
                return jsonify({'error': 'Person not found'}), 404
            
            # Get column names from table info
            table_info = db.session.execute(text("PRAGMA table_info(persons)")).fetchall()
            column_names = [row[1] for row in table_info]
            person_dict = dict(zip(column_names, result))
            
            # Create Person object and set attributes
            person = Person()
            for key, value in person_dict.items():
                if hasattr(person, key):
                    setattr(person, key, value)
        except Exception as query_error:
            logger.error(f"Error querying person with raw SQL: {query_error}", exc_info=True)
            # Fallback to ORM query (might fail if columns missing)
            try:
                person = Person.query.get(person_id)
            except Exception as orm_error:
                logger.error(f"ORM query also failed: {orm_error}", exc_info=True)
                return jsonify({
                    'error': 'Failed to query person',
                    'details': f'Database query error: {str(orm_error)}',
                    'person_id': person_id
                }), 500
        
        if not person:
            logger.warning(f"Person not found with id '{person_id}'")
            return jsonify({
                'error': 'Person not found',
                'person_id': person_id,
                'details': f'No person found with ID: {person_id}'
            }), 404
        
        # Check if person already has a family
        existing_family_id = getattr(person, 'family_id', None)
        if existing_family_id:
            return jsonify({
                'success': True,
                'family_id': existing_family_id,
                'message': 'Person already has a family',
                'already_exists': True
            })
        
        # Generate unique family_id
        import uuid
        family_id = f"family_{uuid.uuid4().hex[:12]}"
        
        # Assign person to family
        try:
            # Use raw SQL UPDATE to ensure the change is persisted
            # This works even if the Person object wasn't loaded via ORM
            update_sql = "UPDATE persons SET family_id = :family_id WHERE id = :person_id"
            result = db.session.execute(text(update_sql), {
                'family_id': family_id,
                'person_id': person_id
            })
            db.session.commit()
            
            if result.rowcount == 0:
                logger.warning(f"No rows updated for person {person_id}")
                return jsonify({
                    'error': 'Person not found or update failed',
                    'person_id': person_id
                }), 404
            
            logger.info(f"Created family {family_id} for person {person_id} (updated {result.rowcount} row(s))")
            
            return jsonify({
                'success': True,
                'family_id': family_id,
                'message': 'Family created successfully',
                'person_id': person_id
            })
        except OperationalError as db_error:
            logger.error(f"Database error creating family: {db_error}", exc_info=True)
            db.session.rollback()
            return jsonify({
                'error': 'Database error',
                'details': str(db_error)
            }), 500
        except Exception as db_error:
            logger.error(f"Error setting family_id: {db_error}", exc_info=True)
            db.session.rollback()
            return jsonify({
                'error': 'Failed to assign family_id',
                'details': str(db_error)
            }), 500
        
    except Exception as e:
        logger.error(f"Error creating family: {e}", exc_info=True)
        db.session.rollback()
        import traceback
        error_details = traceback.format_exc()
        logger.error(f"Full traceback: {error_details}")
        return jsonify({
            'error': 'Failed to create family',
            'details': str(e)
        }), 500


@app.route('/api/persons/<person_id>/family/add-member', methods=['POST'])
@login_required
def add_family_member(person_id):
    """Add another person to the same family"""
    try:
        if not current_user.has_permission('edit_access'):
            return jsonify({'error': 'Insufficient permissions'}), 403
        
        data = request.get_json()
        member_person_id = data.get('member_person_id')
        
        if not member_person_id:
            return jsonify({'error': 'member_person_id is required'}), 400
        
        # URL decode person_id in case it was encoded
        from urllib.parse import unquote
        person_id_decoded = unquote(person_id)
        if person_id_decoded != person_id:
            logger.info(f"Decoded person_id from '{person_id}' to '{person_id_decoded}'")
            person_id = person_id_decoded
        
        # Use raw SQL to query person to avoid ORM issues
        from sqlalchemy import text
        try:
            sql = "SELECT family_id FROM persons WHERE id = :person_id"
            result = db.session.execute(text(sql), {'person_id': person_id}).fetchone()
            if not result:
                return jsonify({'error': 'Person not found'}), 404
            
            family_id = result[0]
            if not family_id:
                return jsonify({'error': 'Person does not have a family. Create one first.'}), 400
        except Exception as query_error:
            logger.error(f"Error querying person: {query_error}", exc_info=True)
            return jsonify({'error': 'Failed to query person', 'details': str(query_error)}), 500
        
        # Check if member exists and get their current family_id
        try:
            member_sql = "SELECT id, family_id FROM persons WHERE id = :member_id"
            member_result = db.session.execute(text(member_sql), {'member_id': member_person_id}).fetchone()
            if not member_result:
                return jsonify({'error': 'Member person not found'}), 404
            
            # Check if member already has a different family
            if member_result[1] and member_result[1] != family_id:
                return jsonify({
                    'error': 'Member already belongs to another family',
                    'details': f'Member is already in family: {member_result[1]}'
                }), 400
        except Exception as query_error:
            logger.error(f"Error querying member: {query_error}", exc_info=True)
            return jsonify({'error': 'Failed to query member', 'details': str(query_error)}), 500
        
        # Add member to family using raw SQL UPDATE
        try:
            update_sql = "UPDATE persons SET family_id = :family_id WHERE id = :member_id"
            result = db.session.execute(text(update_sql), {
                'family_id': family_id,
                'member_id': member_person_id
            })
            db.session.commit()
            
            if result.rowcount == 0:
                logger.warning(f"No rows updated for member {member_person_id}")
                return jsonify({'error': 'Failed to update member'}), 500
            
            logger.info(f"Added member {member_person_id} to family {family_id}")
            
            return jsonify({
                'success': True,
                'message': 'Member added to family successfully'
            })
        except Exception as update_error:
            logger.error(f"Error updating member family_id: {update_error}", exc_info=True)
            db.session.rollback()
            return jsonify({'error': 'Failed to update member', 'details': str(update_error)}), 500
    except Exception as e:
        logger.error(f"Error adding family member: {e}", exc_info=True)
        db.session.rollback()
        return jsonify({'error': 'Failed to add family member'}), 500


