@app.route('/api/persons/<person_id>/family/search-members', methods=['GET'])
@login_required
def search_family_members(person_id):
    """Search for people to add to family"""
    try:
        if not current_user.has_permission('query_access'):
            return jsonify({'error': 'Insufficient permissions'}), 403
        
        search_term = request.args.get('search', '').strip()
        if not search_term or len(search_term) < 2:
            return jsonify({'persons': []})
        
        person = Person.query.get(person_id)
        if not person:
            return jsonify({'error': 'Person not found'}), 404
        
        # Get current family members
        family_id = getattr(person, 'family_id', None)
        exclude_ids = [person_id]
        if family_id:
            family_members = Person.query.filter_by(family_id=family_id).all()
            exclude_ids.extend([m.id for m in family_members])
        
        # Search for people not already in this family
        search_pattern = f"%{search_term}%"
        results = Person.query.filter(
            Person.id.notin_(exclude_ids),
            Person.is_active == True,
            db.or_(
                Person.full_name.ilike(search_pattern),
                Person.preferred_name.ilike(search_pattern),
                Person.email.ilike(search_pattern)
            )
        ).limit(20).all()
        
        return jsonify({
            'persons': [p.to_dict() for p in results]
        })
    except Exception as e:
        logger.error(f"Error searching family members: {e}", exc_info=True)
        return jsonify({'error': 'Failed to search'}), 500


@app.route('/api/heartbeat/dashboard', methods=['GET'])
@login_required
def get_heartbeat_dashboard():
    """Get heartbeat dashboard data with health overview and AI analysis"""
    try:
        if not current_user.has_permission('query_access'):
            return jsonify({'error': 'Insufficient permissions'}), 403
        
        # Get all active persons with engagement profiles
        persons = []
        try:
            persons = Person.query.filter_by(is_active=True).all()
        except Exception as e:
            logger.error(f"Error querying persons for heartbeat dashboard: {e}", exc_info=True)
            # Return empty dashboard data rather than crashing
            return jsonify({
                'health_overview': {
                    'healthy': 0,
                    'watch': 0,
                    'at_risk': 0,
                    'critical': 0,
                    'new_people': 0,
                    'new_christians': 0,
                    'youth_at_risk': 0,
                    'families_drifting': 0
                },
                'ai_analysis': {},
                'pastor_focus_list': [],
                'trends': {},
                'error': 'Unable to load person data'
            }), 200
        
        # Calculate health overview
        health_overview = {
            'healthy': 0,
            'watch': 0,
            'at_risk': 0,
            'critical': 0,
            'new_people': 0,
            'new_christians': 0,
            'youth_at_risk': 0,
            'families_drifting': 0
        }
        
        # Track people for AI analysis
        recent_positive_shifts = []
        health_drops = []
        missing_attendance = []
        
        thirty_days_ago = datetime.utcnow() - timedelta(days=30)
        
        for person in persons:
            try:
                # Get heartbeat snapshot instead of engagement_profile
                snapshot = None
                try:
                    snapshot = HeartbeatSnapshot.query.filter_by(
                        person_id=person.id
                    ).order_by(HeartbeatSnapshot.calculated_at.desc()).first()
                except Exception as e:
                    logger.debug(f"Could not access HeartbeatSnapshot for {person.id}: {e}")
                    snapshot = None
                
                # If no snapshot, count as no_data/critical
                if not snapshot:
                    health_overview['critical'] += 1
                    continue
                
                # Get status from snapshot
                status = snapshot.status or 'critical'
                
                # Count by status
                if status == 'healthy':
                    health_overview['healthy'] += 1
                elif status == 'watch':
                    health_overview['watch'] += 1
                elif status == 'at_risk':
                    health_overview['at_risk'] += 1
                elif status == 'critical':
                    health_overview['critical'] += 1
                else:
                    health_overview['critical'] += 1
                
                # Check for new people (created in last 30 days)
                if person.created_at and person.created_at >= thirty_days_ago:
                    health_overview['new_people'] += 1
                
                # Check for new Christians (has baptism date or new_christian flag)
                is_new_christian = getattr(person, 'is_new_christian', False)
                new_christian_date = getattr(person, 'new_christian_date', None)
                if person.baptised_on or is_new_christian or new_christian_date:
                    health_overview['new_christians'] += 1
                
                # Check youth at risk
                if person.department == 'Youth' and status in ['watch', 'at_risk', 'critical']:
                    health_overview['youth_at_risk'] += 1
                
                # Track attendance issues - try to get from engagement_profile if available
                last_seen = None
                try:
                    engagement_profile = getattr(person, 'engagement_profile', None)
                    if engagement_profile:
                        last_seen = getattr(engagement_profile, 'last_seen', None)
                except Exception:
                    pass
                if last_seen:
                    try:
                        if isinstance(last_seen, str):
                            from datetime import datetime as dt
                            last_seen = dt.fromisoformat(last_seen.replace('Z', '+00:00')).date()
                        elif hasattr(last_seen, 'date'):
                            last_seen = last_seen.date()
                        
                        days_since_seen = (datetime.utcnow().date() - last_seen).days
                        if days_since_seen > 21:  # 3+ weeks
                            missing_attendance.append({
                                'name': person.preferred_name or person.full_name,
                                'days': days_since_seen
                            })
                    except Exception as e:
                        logger.debug(f"Error calculating days_since_seen for {person.id}: {e}")
            except Exception as e:
                logger.warning(f"Error processing person {getattr(person, 'id', 'unknown')} in dashboard: {e}")
                continue
        
        # Generate AI analysis (simplified for now)
        healthy_count = 0
        try:
            for p in persons:
                try:
                    snapshot = HeartbeatSnapshot.query.filter_by(
                        person_id=p.id
                    ).order_by(HeartbeatSnapshot.calculated_at.desc()).first()
                    if snapshot and snapshot.status == 'healthy':
                        healthy_count += 1
                except Exception:
                    continue
        except Exception as e:
            logger.warning(f"Error counting healthy people: {e}")
            healthy_count = health_overview['healthy']
        
        ai_analysis = {
            'positive_shifts': f"{healthy_count} people showing healthy engagement",
            'health_drops': f"{health_overview['at_risk']} people showing declining health",
            'attendance_drops': f"{len(missing_attendance)} people missed 3+ weeks",
            'giving_rhythm_changes': 'No significant changes detected',
            'serving_burnout': 'No serving burnout detected',
            'youth_disengagement': f"{health_overview['youth_at_risk']} youth showing decreased engagement",
            'leadership_ready': 'Analysis pending'
        }
        
        # Generate weekly Pastor Focus List
        pastor_focus_list = []
        
        # Add people with critical status
        critical_people = []
        try:
            from models import HeartbeatSnapshot
            for p in persons:
                try:
                    snapshot = HeartbeatSnapshot.query.filter_by(
                        person_id=p.id
                    ).order_by(HeartbeatSnapshot.calculated_at.desc()).first()
                    if snapshot and snapshot.status == 'critical':
                        critical_people.append(p)
                except Exception:
                    continue
        except Exception as e:
            logger.warning(f"Error finding critical people: {e}")
        
        for person in critical_people[:5]:  # Top 5
            days_ago = 0
            try:
                if hasattr(person, 'engagement_profile') and person.engagement_profile:
                    last_seen = getattr(person.engagement_profile, 'last_seen', None)
                    if last_seen:
                        if isinstance(last_seen, str):
                            from datetime import datetime as dt
                            last_seen = dt.fromisoformat(last_seen.replace('Z', '+00:00')).date()
                        elif hasattr(last_seen, 'date'):
                            last_seen = last_seen.date()
                        days_ago = (datetime.utcnow().date() - last_seen).days
            except Exception:
                pass
            
            pastor_focus_list.append({
                'name': person.preferred_name or person.full_name,
                'reason': f'Critical status - last seen {days_ago} days ago',
                'action': 'Check on - may need immediate pastoral care',
                'priority': 'high'
            })
        
        # Add people with missing attendance
        for missing in missing_attendance[:5]:  # Top 5
            if not any(item['name'] == missing['name'] for item in pastor_focus_list):
                pastor_focus_list.append({
                    'name': missing['name'],
                    'reason': f'Missed {missing["days"]} days',
                    'action': 'Follow up - check if they need encouragement',
                    'priority': 'medium'
                })
        
        return jsonify({
            'health_overview': health_overview,
            'ai_analysis': ai_analysis,
            'pastor_focus_list': pastor_focus_list,
            'trends': {
                'by_campus': {},  # TODO: Implement campus trends
                'by_ministry': {}  # TODO: Implement ministry trends
            }
        })
        
    except Exception as e:
        logger.error(f"Error fetching heartbeat dashboard: {e}", exc_info=True)
        return jsonify({'error': 'Failed to fetch heartbeat dashboard'}), 500


@app.route('/api/pastoral-care/cases', methods=['GET'])
@login_required
def get_pastoral_care_cases():
    """Get all pastoral care cases"""
    try:
        if not current_user.has_permission('query_access'):
            return jsonify({'error': 'Insufficient permissions'}), 403
        
        # Get query parameters
        status_filter = request.args.get('status', None)  # open, resolved, closed
        priority_filter = request.args.get('priority', None)  # high, medium, low
        person_id = request.args.get('person_id', None)
        
        # Build query
        query = PastoralCareCase.query
        
        if status_filter:
            query = query.filter_by(status=status_filter)
        else:
            # Default to open cases only
            query = query.filter_by(status='open')
        
        if priority_filter:
            query = query.filter_by(priority=priority_filter)
        
        if person_id:
            query = query.filter_by(person_id=person_id)
        
        cases = query.order_by(
            db.case(
                (PastoralCareCase.priority == 'high', 1),
                (PastoralCareCase.priority == 'medium', 2),
                (PastoralCareCase.priority == 'low', 3),
                else_=4
            ),
            PastoralCareCase.created_at.desc()
        ).all()
        
        return jsonify({
            'cases': [case.to_dict() for case in cases],
            'total': len(cases)
        })
        
    except Exception as e:
        logger.error(f"Error fetching pastoral care cases: {e}", exc_info=True)
        return jsonify({'error': 'Failed to fetch pastoral care cases'}), 500


@app.route('/api/pastoral-care/cases', methods=['POST'])
@login_required
def create_pastoral_care_case():
    """Create a new pastoral care case"""
    try:
        if not current_user.has_permission('query_access'):
            return jsonify({'error': 'Insufficient permissions'}), 403
        
        data = request.get_json()
        
        # Validate required fields
        if not data.get('person_id'):
            return jsonify({'error': 'person_id is required'}), 400
        
        # Check if person exists
        person = Person.query.filter_by(id=data['person_id'], is_active=True).first()
        if not person:
            return jsonify({'error': 'Person not found'}), 404
        
        # Generate case ID
        case_id = f"pcc_{uuid.uuid4().hex[:12]}"
        
        # Parse suggested_responses and family_dependencies
        suggested_responses = data.get('suggested_responses', [])
        family_dependencies = data.get('family_dependencies', [])
        
        # Create case
        case = PastoralCareCase(
            id=case_id,
            person_id=data['person_id'],
            priority=data.get('priority', 'medium'),
            status=data.get('status', 'open'),
            notes=data.get('notes', ''),
            assigned_leader=data.get('assigned_leader'),
            follow_up_date=datetime.strptime(data['follow_up_date'], '%Y-%m-%d').date() if data.get('follow_up_date') else None,
            ai_summary=data.get('ai_summary'),
            suggested_responses=json.dumps(suggested_responses) if suggested_responses else None,
            family_dependencies=json.dumps(family_dependencies) if family_dependencies else None
        )
        
        db.session.add(case)
        db.session.flush()  # Flush to get case.id
        
        # SYNC: Create corresponding CareCase for Heartbeat engine (central system)
        try:
            # Map PastoralCareCase status to CareCase status
            status_map = {
                'open': 'open',
                'resolved': 'closed',
                'closed': 'closed'
            }
            care_case_status = status_map.get(case.status, 'open')
            
            # Determine care case type from notes or default to 'pastoral_care'
            care_case_type = 'pastoral_care'
            if case.notes:
                notes_lower = case.notes.lower()
                if any(word in notes_lower for word in ['bereavement', 'death', 'grief', 'loss']):
                    care_case_type = 'bereavement'
                elif any(word in notes_lower for word in ['marriage', 'divorce', 'relationship']):
                    care_case_type = 'marriage'
                elif any(word in notes_lower for word in ['mental', 'depression', 'anxiety', 'counseling']):
                    care_case_type = 'mental_health'
                elif any(word in notes_lower for word in ['prayer', 'pray']):
                    care_case_type = 'prayer_request'
            
            # Create CareCase for heartbeat engine
            heartbeat_care_case = CareCase(
                person_id=case.person_id,
                type=care_case_type,
                status=care_case_status,
                priority=case.priority,
                summary=case.notes[:500] if case.notes else f"Pastoral care case: {case.id}",
                details=case.notes if case.notes else None,
                created_by_person_id=getattr(current_user, 'id', None) or case.person_id,
                created_at=datetime.utcnow(),
                updated_at=datetime.utcnow()
            )
            db.session.add(heartbeat_care_case)
            logger.info(f"✅ Created CareCase {heartbeat_care_case.id} for PastoralCareCase {case.id} (synced for Heartbeat)")
        except Exception as sync_error:
            logger.error(f"⚠️ Failed to sync CareCase for PastoralCareCase {case.id}: {sync_error}", exc_info=True)
            # Continue even if sync fails - don't break the main operation
        
        db.session.commit()
        
        # Recalculate heartbeat to reflect the new care case
        try:
            from heartbeat_engine import HeartbeatEngine
            engine = HeartbeatEngine()
            engine.calculate_heartbeat(person.id)
            logger.info(f"💗 Heartbeat recalculated after creating pastoral care case")
        except Exception as heartbeat_error:
            logger.warning(f"Could not recalculate heartbeat: {heartbeat_error}")
        
        # Update person's heartbeat status if high priority case (affects health)
        if case.priority == 'high' and person.engagement_profile:
            # High care case reduces health
            person.engagement_profile.pulse_status = 'amber'
            db.session.commit()
        
        return jsonify(case.to_dict()), 201
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error creating pastoral care case: {e}", exc_info=True)
        return jsonify({'error': 'Failed to create pastoral care case'}), 500


@app.route('/api/pastoral-care/cases/<case_id>', methods=['PUT'])
@login_required
def update_pastoral_care_case(case_id):
    """Update a pastoral care case"""
    try:
        if not current_user.has_permission('query_access'):
            return jsonify({'error': 'Insufficient permissions'}), 403
        
        case = PastoralCareCase.query.filter_by(id=case_id).first()
        if not case:
            return jsonify({'error': 'Case not found'}), 404
        
        data = request.get_json()
        
        # Update fields
        if 'priority' in data:
            case.priority = data['priority']
        if 'status' in data:
            old_status = case.status
            case.status = data['status']
            
            # If resolving a case, improve person's heartbeat
            if old_status == 'open' and data['status'] == 'resolved' and case.person and case.person.engagement_profile:
                # Resolved case improves health
                if case.person.engagement_profile.pulse_status == 'red':
                    case.person.engagement_profile.pulse_status = 'amber'
                elif case.person.engagement_profile.pulse_status == 'amber':
                    case.person.engagement_profile.pulse_status = 'green'
                db.session.commit()
        
        if 'notes' in data:
            case.notes = data['notes']
        if 'assigned_leader' in data:
            case.assigned_leader = data['assigned_leader']
        if 'follow_up_date' in data:
            case.follow_up_date = datetime.strptime(data['follow_up_date'], '%Y-%m-%d').date() if data['follow_up_date'] else None
        if 'ai_summary' in data:
            case.ai_summary = data['ai_summary']
        if 'suggested_responses' in data:
            case.suggested_responses = json.dumps(data['suggested_responses']) if data['suggested_responses'] else None
        if 'family_dependencies' in data:
            case.family_dependencies = json.dumps(data['family_dependencies']) if data['family_dependencies'] else None
        
        case.updated_at = datetime.utcnow()
        
        # SYNC: Update corresponding CareCase for Heartbeat engine
        try:
            # Find the CareCase that corresponds to this PastoralCareCase
            # We'll match by person_id and similar summary/details
            heartbeat_care_cases = CareCase.query.filter_by(person_id=case.person_id).all()
            
            # Try to find matching CareCase by checking if summary matches
            matching_case = None
            if case.notes:
                for hc in heartbeat_care_cases:
                    if hc.summary and case.notes[:500] in hc.summary:
                        matching_case = hc
                        break
            
            # If no exact match, use the most recent open case for this person
            if not matching_case:
                open_cases = [c for c in heartbeat_care_cases if c.status in ['open', 'in_progress']]
                if open_cases:
                    matching_case = max(open_cases, key=lambda x: x.created_at)
            
            if matching_case:
                # Map PastoralCareCase status to CareCase status
                status_map = {
                    'open': 'open',
                    'resolved': 'closed',
                    'closed': 'closed'
                }
                matching_case.status = status_map.get(case.status, matching_case.status)
                matching_case.priority = case.priority
                if case.notes:
                    matching_case.summary = case.notes[:500]
                    matching_case.details = case.notes
                matching_case.updated_at = datetime.utcnow()
                logger.info(f"✅ Updated CareCase {matching_case.id} for PastoralCareCase {case.id}")
            else:
                # No matching case found - create one (shouldn't happen, but handle it)
                logger.warning(f"⚠️ No matching CareCase found for PastoralCareCase {case.id}, creating new one")
                status_map = {'open': 'open', 'resolved': 'closed', 'closed': 'closed'}
                new_care_case = CareCase(
                    person_id=case.person_id,
                    type='pastoral_care',
                    status=status_map.get(case.status, 'open'),
                    priority=case.priority,
                    summary=case.notes[:500] if case.notes else f"Pastoral care case: {case.id}",
                    details=case.notes if case.notes else None,
                    created_by_person_id=getattr(current_user, 'id', None) or case.person_id,
                    created_at=datetime.utcnow(),
                    updated_at=datetime.utcnow()
                )
                db.session.add(new_care_case)
        except Exception as sync_error:
            logger.error(f"⚠️ Failed to sync CareCase for PastoralCareCase {case.id}: {sync_error}", exc_info=True)
        
        db.session.commit()
        
        # Recalculate heartbeat if status changed
        if 'status' in data and case.person:
            try:
                from heartbeat_engine import HeartbeatEngine
                engine = HeartbeatEngine()
                engine.calculate_heartbeat(case.person_id)
                logger.info(f"💗 Heartbeat recalculated after updating pastoral care case")
            except Exception as heartbeat_error:
                logger.warning(f"Could not recalculate heartbeat: {heartbeat_error}")
        
        return jsonify(case.to_dict())
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error updating pastoral care case: {e}", exc_info=True)
        return jsonify({'error': 'Failed to update pastoral care case'}), 500


@app.route('/api/pastoral-care/cases/<case_id>', methods=['DELETE'])
@login_required
def delete_pastoral_care_case(case_id):
    """Delete a pastoral care case"""
    try:
        if not current_user.has_permission('query_access'):
            return jsonify({'error': 'Insufficient permissions'}), 403
        
        case = PastoralCareCase.query.filter_by(id=case_id).first()
        if not case:
            return jsonify({'error': 'Case not found'}), 404
        
        person_id = case.person_id  # Save for heartbeat recalculation
        
        # SYNC: Close corresponding CareCase (don't delete, just mark as closed)
        try:
            heartbeat_care_cases = CareCase.query.filter_by(person_id=case.person_id).all()
            if case.notes:
                for hc in heartbeat_care_cases:
                    if hc.summary and case.notes[:500] in hc.summary:
                        hc.status = 'closed'
                        hc.updated_at = datetime.utcnow()
                        logger.info(f"✅ Closed CareCase {hc.id} for deleted PastoralCareCase {case_id}")
                        break
        except Exception as sync_error:
            logger.error(f"⚠️ Failed to sync CareCase deletion for PastoralCareCase {case_id}: {sync_error}", exc_info=True)
        
        db.session.delete(case)
        db.session.commit()
        
        # Recalculate heartbeat after deletion
        if person_id:
            try:
                from heartbeat_engine import HeartbeatEngine
                engine = HeartbeatEngine()
                engine.calculate_heartbeat(person_id)
                logger.info(f"💗 Heartbeat recalculated after deleting pastoral care case")
            except Exception as heartbeat_error:
                logger.warning(f"Could not recalculate heartbeat: {heartbeat_error}")
        
        return jsonify({'success': True, 'message': 'Case deleted successfully'})
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error deleting pastoral care case: {e}", exc_info=True)
        return jsonify({'error': 'Failed to delete pastoral care case'}), 500


@app.route('/api/pastoral-care/cases/<case_id>/resolve', methods=['POST'])
@login_required
def resolve_pastoral_care_case(case_id):
    """Resolve a pastoral care case (affects heartbeat)"""
    try:
        if not current_user.has_permission('query_access'):
            return jsonify({'error': 'Insufficient permissions'}), 403
        
        case = PastoralCareCase.query.filter_by(id=case_id).first()
        if not case:
            return jsonify({'error': 'Case not found'}), 404
        
        case.status = 'resolved'
        case.updated_at = datetime.utcnow()
        
        # SYNC: Update corresponding CareCase to closed status
        try:
            heartbeat_care_cases = CareCase.query.filter_by(person_id=case.person_id).all()
            if case.notes:
                for hc in heartbeat_care_cases:
                    if hc.summary and case.notes[:500] in hc.summary:
                        hc.status = 'closed'
                        hc.updated_at = datetime.utcnow()
                        logger.info(f"✅ Closed CareCase {hc.id} for resolved PastoralCareCase {case_id}")
                        break
        except Exception as sync_error:
            logger.error(f"⚠️ Failed to sync CareCase resolution for PastoralCareCase {case_id}: {sync_error}", exc_info=True)
        
        # Improve person's heartbeat when case is resolved
        if case.person and case.person.engagement_profile:
            if case.person.engagement_profile.pulse_status == 'red':
                case.person.engagement_profile.pulse_status = 'amber'
            elif case.person.engagement_profile.pulse_status == 'amber':
                case.person.engagement_profile.pulse_status = 'green'
        
        db.session.commit()
        
        # Recalculate heartbeat to reflect resolved case
        if case.person_id:
            try:
                from heartbeat_engine import HeartbeatEngine
                engine = HeartbeatEngine()
                engine.calculate_heartbeat(case.person_id)
                logger.info(f"💗 Heartbeat recalculated after resolving pastoral care case")
            except Exception as heartbeat_error:
                logger.warning(f"Could not recalculate heartbeat: {heartbeat_error}")
        
        return jsonify(case.to_dict())
        
    except Exception as e:
        db.session.rollback()
        logger.error(f"Error resolving pastoral care case: {e}", exc_info=True)
        return jsonify({'error': 'Failed to resolve pastoral care case'}), 500


@app.route('/api/people/new-christians', methods=['GET'])
@login_required
def get_new_christians():
    """Get all new Christians with discipleship progress"""
    try:
        if not current_user.has_permission('query_access'):
            return jsonify({'error': 'Insufficient permissions'}), 403
        
        # Get persons who are new Christians (have baptism date, new_christian flag, or new_christian_date)
        persons = Person.query.filter_by(is_active=True).all()
        
        new_christians = []
        two_years_ago = datetime.utcnow().date() - timedelta(days=730)
        
        for person in persons:
            try:
                is_new_christian = False
                new_christian_date = None
                
                # Check for new_christian_date field (preferred) - safely access
                new_christian_date_attr = getattr(person, 'new_christian_date', None)
                if new_christian_date_attr:
                    if new_christian_date_attr >= two_years_ago:
                        is_new_christian = True
                        new_christian_date = new_christian_date_attr.isoformat() if hasattr(new_christian_date_attr, 'isoformat') else str(new_christian_date_attr)
                # Check for is_new_christian flag - safely access
                elif getattr(person, 'is_new_christian', False):
                    is_new_christian = True
                    # Use baptism date or created_at as fallback
                    if person.baptised_on:
                        new_christian_date = person.baptised_on.isoformat() if hasattr(person.baptised_on, 'isoformat') else str(person.baptised_on)
                    elif person.created_at:
                        created_date = person.created_at.date() if hasattr(person.created_at, 'date') else person.created_at
                        new_christian_date = created_date.isoformat() if hasattr(created_date, 'isoformat') else str(created_date)
                # Check for baptism date (within last 2 years)
                elif person.baptised_on and person.baptised_on >= two_years_ago:
                    is_new_christian = True
                    new_christian_date = person.baptised_on.isoformat() if hasattr(person.baptised_on, 'isoformat') else str(person.baptised_on)
                
                if is_new_christian:
                    # Get pathway progress
                    pathway_progress = "Not started"
                    try:
                        pathway = PersonPathwayProgress.query.filter_by(person_id=person.id).first()
                        if pathway:
                            completed_steps = PersonPathwayStepCompletion.query.filter_by(
                                person_id=person.id,
                                completed=True
                            ).count()
                            total_steps = PathwayStep.query.count()
                            pathway_progress = f"Step {completed_steps} of {total_steps}"
                    except:
                        pass
                    
                    # Calculate group attendance
                    group_attendance = 0
                    try:
                        engagement_profile = getattr(person, 'engagement_profile', None)
                        if engagement_profile:
                            try:
                                attendance_log = json.loads(getattr(engagement_profile, 'attendance_log', None) or '[]')
                                group_attendance = len([a for a in attendance_log if a.get('type') == 'group'])
                            except:
                                pass
                    except Exception:
                        pass
                    
                    # Generate AI analysis
                    ai_analysis = f"This person is progressing well. "
                    if person.baptised_on:
                        days_since_baptism = (datetime.utcnow().date() - person.baptised_on).days
                        ai_analysis += f"Baptised {days_since_baptism} days ago. "
                    
                    suggested_next_step = "Continue discipleship"
                    if not pathway_progress or pathway_progress == "Not started":
                        suggested_next_step = "Start Foundations course"
                    elif group_attendance < 3:
                        suggested_next_step = "Connect to a group"
                    elif person.first_served_on is None:
                        suggested_next_step = "Start serving"
                    
                    new_christians.append({
                        'id': person.id,
                        'name': person.preferred_name or person.full_name,
                        'full_name': person.full_name,
                        'campus': getattr(person, 'campus', None),
                        'department': getattr(person, 'department', None),
                        'new_christian_date': new_christian_date,
                        'foundations_progress': '50%',  # TODO: Calculate from pathway
                        'pathway_progress': pathway_progress,
                        'attendance_since_decision': group_attendance,
                        'group_attendance': int((group_attendance / 12) * 100) if group_attendance > 0 else 0,  # Percentage
                        'pulse_tv_usage': 'Medium',  # TODO: Calculate from engagement
                        'ai_analysis': ai_analysis,
                        'suggested_next_step': suggested_next_step
                    })
            except Exception as e:
                logger.warning(f"Error processing person {getattr(person, 'id', 'unknown')} in new_christians: {e}")
                continue
        
        return jsonify({
            'new_christians': new_christians,
            'total': len(new_christians)
        })
        
    except Exception as e:
        logger.error(f"Error fetching new Christians: {e}", exc_info=True)
        return jsonify({'error': 'Failed to fetch new Christians'}), 500


@app.route('/api/attendance/patterns', methods=['GET'])
@login_required
def get_attendance_patterns():
    """Get attendance patterns and missing streaks"""
    try:
        if not current_user.has_permission('query_access'):
            return jsonify({'error': 'Insufficient permissions'}), 403
        
        # Get all active persons
        persons = Person.query.filter_by(is_active=True).all()
        
        # Calculate missing streaks
        missing_streaks = []
        today = datetime.utcnow().date()
        
        for person in persons:
            try:
                # Safely access engagement_profile
                engagement_profile = None
                try:
                    engagement_profile = person.engagement_profile
                except Exception:
                    pass
                
                if engagement_profile:
                    last_seen = getattr(engagement_profile, 'last_seen', None)
                    if last_seen:
                        try:
                            # Handle both date and datetime objects
                            if isinstance(last_seen, str):
                                from datetime import datetime as dt
                                last_seen = dt.fromisoformat(last_seen.replace('Z', '+00:00')).date()
                            elif hasattr(last_seen, 'date'):
                                last_seen = last_seen.date()
                            
                            days_since_seen = (today - last_seen).days
                            
                            if days_since_seen > 14:  # 2+ weeks
                                missing_streaks.append({
                                    'person_id': person.id,
                                    'name': person.preferred_name or person.full_name,
                                    'days': days_since_seen,
                                    'last_attended': last_seen.isoformat() if hasattr(last_seen, 'isoformat') else str(last_seen)
                                })
                        except Exception as e:
                            logger.debug(f"Error calculating days_since_seen for {person.id}: {e}")
            except Exception as e:
                logger.warning(f"Error processing person {getattr(person, 'id', 'unknown')} in attendance patterns: {e}")
                continue
        
        # Sort by days (most critical first)
        missing_streaks.sort(key=lambda x: x['days'], reverse=True)
        
        # Calculate first-time visitors (people created in last 30 days)
        thirty_days_ago = datetime.utcnow() - timedelta(days=30)
        first_time_visitors = len([
            p for p in persons 
            if p.created_at and p.created_at >= thirty_days_ago
        ])
        
        # Calculate average attendance (placeholder - would need actual attendance records)
        # TODO: Implement actual attendance calculation from attendance logs
        attendance_logs = []
        for person in persons:
            if person.engagement_profile:
                try:
                    log = json.loads(person.engagement_profile.attendance_log or '[]')
                    attendance_logs.extend(log)
                except:
                    pass
        
        # Count unique attendance dates
        unique_dates = set()
        for log_entry in attendance_logs:
            if isinstance(log_entry, dict) and 'date' in log_entry:
                unique_dates.add(log_entry['date'])
        
        return jsonify({
            'sunday_avg': len(unique_dates),  # Placeholder
            'sunday_month': len([d for d in unique_dates if datetime.fromisoformat(d).date() >= (today - timedelta(days=30))]),
            'sunday_trend': 0,  # TODO: Calculate trend
            'kids_attendance': {},  # TODO: Implement
            'youth_attendance': {},  # TODO: Implement
            'missing_streaks': missing_streaks[:20],  # Top 20
            'first_time_visitors': first_time_visitors,
            'families_missing': [],  # TODO: Implement
            'serving_attendance': {},  # TODO: Implement
            'event_attendance': {}  # TODO: Implement
        })
        
    except Exception as e:
        logger.error(f"Error fetching attendance patterns: {e}", exc_info=True)
        return jsonify({'error': 'Failed to fetch attendance patterns'}), 500


